B.aJ3=new A.a("\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645",null,"\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0639\u064a\u0646\u064a\u0629 (\u0627\u0644\u0645\u062d\u0633\u0648\u0633\u0629) \u0639\u0646\u062f \u0628\u064a\u0627\u062c\u064a\u0647 \u062a\u0647\u0645 \u0627\u0644\u0623\u0637\u0641\u0627\u0644 \u0641\u064a \u0633\u0646:",B.ard,2,"\u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0639\u064a\u0646\u064a\u0629 (7-11/12): \u064a\u0643\u062a\u0633\u0628 \u0627\u0644\u0637\u0641\u0644 \u0627\u0644\u0627\u0646\u062d\u0641\u0627\u0638 \u0648\u0627\u0644\u062a\u0635\u0646\u064a\u0641 \u0648\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0648\u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0645\u0642\u0644\u0648\u0628\u0629 \u0644\u0643\u0646 \u0641\u064a \u062d\u062f\u0648\u062f \u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0627\u0644\u0645\u062d\u0633\u0648\u0633\u0629.",u.c)
B.am3=s(["\u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0627\u0644\u0641\u0631\u0636\u064a \u0627\u0644\u0627\u0633\u062a\u0646\u0628\u0627\u0637\u064a \u0648\u0627\u0644\u062a\u062c\u0631\u064a\u062f","\u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u0643\u0644\u064a \u0639\u0644\u0649 \u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0627\u0644\u0645\u062d\u0633\u0648\u0633\u0629","\u0627\u0644\u062a\u0645\u0631\u0643\u0632 \u062d\u0648\u0644 \u0627\u0644\u0630\u0627\u062a \u0628\u0634\u0643\u0644 \u0643\u0627\u0645\u0644","\u0627\u0644\u062a\u0642\u0644\u064a\u062f \u0627\u0644\u062d\u0631\u0641\u064a \u062f\u0648\u0646 \u062a\u0641\u0643\u064a\u0631","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
