B.aGJ=new A.a("\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645",null,"\u0645\u0631\u0627\u062d\u0644 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u062e\u0644\u0642\u064a \u0639\u0646\u062f \u0643\u0648\u0644\u0628\u0631\u063a \u062a\u0634\u0645\u0644 \u0639\u0644\u0649 \u0627\u0644\u062a\u0648\u0627\u0644\u064a:",B.akX,0,"\u0643\u0648\u0644\u0628\u0631\u063a \u0642\u0633\u0645 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u062e\u0644\u0642\u064a \u0625\u0644\u0649: \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0645\u0627 \u0642\u0628\u0644 \u0627\u0644\u062a\u0642\u0644\u064a\u062f\u064a\u060c \u062b\u0645 \u0627\u0644\u062a\u0642\u0644\u064a\u062f\u064a\u060c \u062b\u0645 \u0645\u0627 \u0628\u0639\u062f \u0627\u0644\u062a\u0642\u0644\u064a\u062f\u064a (\u0645\u0628\u0627\u062f\u0626 \u0645\u062c\u0631\u062f\u0629).","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb \u2014 \u0635 61")
B.aev=s(["\u0627\u0633\u062a\u0631\u062c\u0627\u0639 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0643\u0645\u0627 \u0648\u0631\u062f\u062a","\u0625\u0639\u0627\u062f\u0629 \u0635\u064a\u0627\u063a\u0629 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0648\u062a\u0641\u0633\u064a\u0631\u0647\u0627 \u0628\u0639\u0628\u0627\u0631\u0627\u062a \u0623\u062e\u0631\u0649","\u062a\u062c\u0632\u0626\u0629 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0625\u0644\u0649 \u0639\u0646\u0627\u0635\u0631\u0647\u0627","\u0625\u0635\u062f\u0627\u0631 \u062d\u0643\u0645 \u0639\u0644\u0649 \u0642\u064a\u0645\u0629 \u0627\u0644\u0645\u0639\u0631\u0641\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b7I=new A.a("\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645",null,"\u0641\u064a \u062a\u0635\u0646\u064a\u0641 \u0628\u0644\u0648\u0645\u060c \u064a\u0642\u0635\u062f \u0628\u0640\xab\u0627\u0644\u0641\u0647\u0645\xbb:",B.aev,1,"\u0627\u0644\u0641\u0647\u0645 \u064a\u0639\u0644\u0648 \u0627\u0644\u062a\u0630\u0643\u0631: \u0627\u0644\u062a\u0641\u0633\u064a\u0631 \u0648\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0635\u064a\u0627\u063a\u0629 \u0648\u0627\u0644\u062a\u0631\u062c\u0645\u0629\u060c \u0628\u064a\u0646\u0645\u0627 \xab\u0627\u0644\u062a\u0630\u0643\u0631\xbb \u0647\u0648 \u0645\u062c\u0631\u062f \u0627\u0644\u0627\u0633\u062a\u0631\u062c\u0627\u0639.",u.U)
B.afP=s(["\u0627\u0644\u062a\u0630\u0643\u0631\u060c \u0627\u0644\u0641\u0647\u0645\u060c \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0627\u0644\u062a\u062d\u0644\u064a\u0644\u060c \u0627\u0644\u062a\u0631\u0643\u064a\u0628\u060c \u0627\u0644\u062a\u0642\u0648\u064a\u0645","\u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0627\u0644\u062a\u0630\u0643\u0631\u060c \u0627\u0644\u0641\u0647\u0645\u060c \u0627\u0644\u062a\u062d\u0644\u064a\u0644\u060c \u0627\u0644\u062a\u0642\u0648\u064a\u0645\u060c \u0627\u0644\u062a\u0631\u0643\u064a\u0628","\u0627\u0644\u0641\u0647\u0645\u060c \u0627\u0644\u062a\u0630\u0643\u0631\u060c \u0627\u0644\u062a\u062d\u0644\u064a\u0644\u060c \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0627\u0644\u062a\u0631\u0643\u064a\u0628\u060c \u0627\u0644\u062a\u0642\u0648\u064a\u0645","\u0627\u0644\u062a\u0630\u0643\u0631\u060c \u0627\u0644\u0641\u0647\u0645\u060c \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0627\u0644\u062a\u062d\u0644\u064a\u0644\u060c \u0627\u0644\u062a\u0642\u0648\u064a\u0645\u060c \u0627\u0644\u062a\u0631\u0643\u064a\u0628","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aXH=new A.a("\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645",null,"\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0639\u0644\u064a\u0627 \u0641\u064a \u062a\u0635\u0646\u064a\u0641 \u0628\u0644\u0648\u0645 \u0644\u0644\u062a\u0639\u0644\u0645 \u0647\u064a\u060c \u0645\u0631\u062a\u0628\u0629 \u062a\u0635\u0627\u0639\u062f\u064a\u0627\u064b:",B.afP,3,"\u0627\u0644\u062a\u0635\u0646\u064a\u0641 \u0627\u0644\u0643\u0644\u0627\u0633\u064a\u0643\u064a \u0644\u0628\u0644\u0648\u0645: \u062a\u0630\u0643\u0631 \u2190 \u0641\u0647\u0645 \u2190 \u062a\u0637\u0628\u064a\u0642 \u2190 \u062a\u062d\u0644\u064a\u0644 \u2190 \u062a\u0642\u0648\u064a\u0645 \u2190 \u062a\u0631\u0643\u064a\u0628 (\u0648\u0628\u0639\u0636 \u0627\u0644\u0646\u0633\u062e \u062a\u0636\u0639 \u0627\u0644\u0625\u0628\u062f\u0627\u0639 \u0623\u0639\u0644\u0627\u0647).",u.U)
B.adt=s(["\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0641\u0631\u062f\u064a \u0627\u0644\u062a\u0646\u0627\u0641\u0633\u064a \u062f\u0627\u062e\u0644 \u0627\u0644\u0642\u0633\u0645","\u0639\u0645\u0644 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0641\u064a \u0645\u062c\u0645\u0648\u0639\u0627\u062a \u0635\u063a\u064a\u0631\u0629 \u0628\u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u0645\u0634\u062a\u0631\u0643\u0629 \u0648\u062a\u0641\u0627\u0639\u0644 \u0648\u062a\u0646\u0627\u0635\u0641 \u0627\u0644\u0623\u062f\u0648\u0627\u0631","\u062a\u0644\u0642\u064a \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0645\u0646 \u0627\u0644\u0645\u0639\u0644\u0651\u0645 \u062f\u0648\u0646 \u062a\u0641\u0627\u0639\u0644","\u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u062c\u0645\u0627\u0639\u064a \u0628\u0642\u064a\u0627\u062f\u0629 \u062d\u0635\u0631\u064a\u0629 \u0644\u0644\u0645\u0639\u0644\u0651\u0645","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aRk=new A.a("\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645",null,"\u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u062a\u0639\u0627\u0648\u0646\u064a \u064a\u0642\u0648\u0645 \u0639\u0644\u0649:",B.adt,1,"\u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u062a\u0639\u0627\u0648\u0646\u064a: \u0645\u062c\u0645\u0648\u0639\u0627\u062a 2-6 \u0623\u0641\u0631\u0627\u062f\u060c \u0623\u0647\u062f\u0627\u0641 \u0645\u0634\u062a\u0631\u0643\u0629\u060c \u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u0641\u0631\u062f\u064a\u0629 \u0648\u062c\u0645\u0627\u0639\u064a\u0629\u060c \u0648\u062a\u0641\u0627\u0639\u0644 \u0625\u064a\u062c\u0627\u0628\u064a \u0628\u064a\u0646 \u0627\u0644\u0623\u0639\u0636\u0627\u0621.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb")
B.WD=s(["\u0645\u062f\u0641\u0648\u0639\u0629 \u0628\u0645\u0643\u0627\u0641\u0622\u062a \u062e\u0627\u0631\u062c\u064a\u0629","\u0646\u0627\u0628\u0639\u0629 \u0645\u0646 \u0631\u063a\u0628\u0629 \u0630\u0627\u062a\u064a\u0629 \u0641\u064a \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u0627\u0632","\u0645\u0631\u062a\u0628\u0637\u0629 \u0641\u0642\u0637 \u0628\u0627\u0644\u0639\u0642\u0627\u0628","\u0644\u0627 \u062a\u0624\u062b\u0631 \u0641\u064a \u0627\u0644\u062a\u062d\u0635\u064a\u0644","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b_5=new A.a("\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645",null,"\u0627\u0644\u062f\u0627\u0641\u0639\u064a\u0629 \u0627\u0644\u062f\u0627\u062e\u0644\u064a\u0629 \u0644\u0644\u062a\u0639\u0644\u0645 \u062a\u062a\u0645\u064a\u0632 \u0639\u0646 \u0627\u0644\u062e\u0627\u0631\u062c\u064a\u0629 \u0628\u0623\u0646\u0647\u0627:",B.WD,1,"\u0627\u0644\u062f\u0627\u0641\u0639\u064a\u0629 \u0627\u0644\u062f\u0627\u062e\u0644\u064a\u0629 \u0645\u0635\u062f\u0631\u0647\u0627 \u0630\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0645 (\u062d\u0628 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u0627\u0632) \u0648\u0647\u064a \u0623\u0642\u0648\u0649 \u0623\u062b\u0631\u0627\u064b \u0648\u0627\u0633\u062a\u0645\u0631\u0627\u0631\u0627\u064b \u0645\u0646 \u0627\u0644\u062f\u0627\u0641\u0639\u064a\u0629 \u0627\u0644\u062e\u0627\u0631\u062c\u064a\u0629.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb \u2014 \u0635 67")
B.aeM=s(["\u062a\u0648\u062d\u064a\u062f \u0627\u0644\u0633\u0631\u0639\u0629 \u0648\u0627\u0644\u0645\u0646\u0647\u062c\u064a\u0629 \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646","\u062a\u0646\u0648\u064a\u0639 \u0627\u0644\u0648\u0636\u0639\u064a\u0627\u062a \u0648\u0627\u0644\u0648\u062a\u064a\u0631\u0629 \u0648\u0627\u0644\u062f\u0639\u0645 \u062d\u0633\u0628 \u062d\u0627\u062c\u0627\u062a \u0643\u0644 \u0645\u062a\u0639\u0644\u0645","\u0625\u0647\u0645\u0627\u0644 \u0627\u0644\u0645\u062a\u0639\u062b\u0631\u064a\u0646 \u0644\u0635\u0627\u0644\u062d \u0627\u0644\u0645\u062a\u0641\u0648\u0642\u064a\u0646","\u062c\u0639\u0644 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0623\u062f\u0627\u0629 \u062a\u0647\u062f\u064a\u062f \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aR_=new A.a("\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645",null,"\u0645\u0631\u0627\u0639\u0627\u0629 \u0627\u0644\u0641\u0631\u0648\u0642 \u0627\u0644\u0641\u0631\u062f\u064a\u0629 \u0641\u064a \u0627\u0644\u0646\u0645\u0648 \u062a\u062a\u0637\u0644\u0628 \u0645\u0646 \u0627\u0644\u0623\u0633\u062a\u0627\u0630:",B.aeM,1,"\u0627\u0644\u0641\u0631\u0648\u0642 \u0627\u0644\u0641\u0631\u062f\u064a\u0629 \u0641\u064a \u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0644\u062a\u0639\u0644\u0645 \u062a\u0633\u062a\u062f\u0639\u064a \u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629 \u0641\u0627\u0631\u0642\u064a\u0629 \u062a\u062a\u0646\u0648\u0639 \u0641\u064a\u0647\u0627 \u0627\u0644\u0648\u0636\u0639\u064a\u0627\u062a \u0648\u0627\u0644\u0623\u062f\u0648\u0627\u0631 \u0648\u0627\u0644\u0648\u0633\u0627\u0626\u0644.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb")
