B.aTT=new A.a("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u062a\u0642\u0627\u0637\u0639 \u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0645\u0639 \u0627\u0644\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629 \u064a\u0638\u0647\u0631 \u0641\u064a \u062f\u0631\u0627\u0633\u0629:",B.akA,0,"\u0627\u0644\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629 \u062a\u062f\u0631\u0633 \u0633\u0644\u0648\u0643 \u0627\u0644\u0641\u0631\u062f \u062f\u0627\u062e\u0644 \u0627\u0644\u062c\u0645\u0627\u0639\u0629: \u0627\u0644\u0642\u064a\u0627\u062f\u0629\u060c \u0627\u0644\u0645\u0646\u0627\u062e\u060c \u0627\u0644\u062a\u0648\u0627\u0635\u0644\u060c \u0627\u0644\u062a\u0642\u0644\u064a\u062f\u060c \u0648\u0627\u0644\u062f\u064a\u0646\u0627\u0645\u064a\u0629 \u0627\u0644\u062c\u0645\u0627\u0639\u064a\u0629.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb")
B.awO=s(["\u0639\u0645\u0644\u064a\u0629 \u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0630\u0647\u0646\u064a \u0648\u062a\u0631\u0643\u064a\u0632\u0647 \u0639\u0644\u0649 \u0645\u062b\u064a\u0631 \u0645\u0639\u064a\u0646","\u0639\u0645\u0644\u064a\u0629 \u062a\u062e\u0632\u064a\u0646 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u0646\u0647\u0627\u0626\u064a\u0629","\u0645\u062c\u0631\u062f \u0631\u062f \u0641\u0639\u0644 \u0644\u0627 \u0625\u0631\u0627\u062f\u064a","\u0645\u0631\u0627\u062f\u0641 \u0644\u0644\u0646\u0633\u064a\u0627\u0646","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aZr=new A.a("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u0627\u0644\u0627\u0646\u062a\u0628\u0627\u0647 \u0641\u064a \u0627\u0644\u0639\u0645\u0644\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u064a\u064f\u0639\u0631\u064e\u0651\u0641 \u0628\u0623\u0646\u0647:",B.awO,0,"\u0627\u0644\u0627\u0646\u062a\u0628\u0627\u0647 \u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0625\u062f\u0631\u0627\u0643\u064a \u0639\u0644\u0649 \u0645\u062b\u064a\u0631 \u062f\u0648\u0646 \u063a\u064a\u0631\u0647\u060c \u0648\u0644\u0647 \u0623\u0634\u0643\u0627\u0644: \u0645\u0646\u062a\u0642\u0649\u060c \u0645\u0642\u0633\u0645\u060c \u0645\u0633\u062a\u0645\u0631.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb")
B.af6=s(["\u0627\u0644\u062d\u0633\u064a\u0629\u060c \u062b\u0645 \u0642\u0635\u064a\u0631\u0629 \u0627\u0644\u0645\u062f\u0649\u060c \u062b\u0645 \u0637\u0648\u064a\u0644\u0629 \u0627\u0644\u0645\u062f\u0649","\u0637\u0648\u064a\u0644\u0629 \u0627\u0644\u0645\u062f\u0649\u060c \u062b\u0645 \u0627\u0644\u062d\u0633\u064a\u0629\u060c \u062b\u0645 \u0642\u0635\u064a\u0631\u0629 \u0627\u0644\u0645\u062f\u0649","\u0642\u0635\u064a\u0631\u0629 \u0627\u0644\u0645\u062f\u0649\u060c \u062b\u0645 \u0637\u0648\u064a\u0644\u0629 \u0627\u0644\u0645\u062f\u0649 \u0641\u0642\u0637","\u0627\u0644\u062d\u0633\u064a\u0629 \u062b\u0645 \u0642\u0635\u064a\u0631\u0629 \u0627\u0644\u0645\u062f\u0649 \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b89=new A.a("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u062d\u0633\u0628 \u0646\u0645\u0648\u0630\u062c \u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a\u060c \u0627\u0644\u0630\u0627\u0643\u0631\u0629 \u062a\u0645\u0631 \u0639\u0627\u062f\u0629 \u0639\u0628\u0631 \u0627\u0644\u0645\u0631\u0627\u062d\u0644 \u0627\u0644\u062a\u0627\u0644\u064a\u0629:",B.af6,0,"\u0627\u0644\u0646\u0645\u0648\u0630\u062c (\u0623\u062a\u0643\u0646\u0633\u0648\u0646 \u0648\u0634\u064a\u0641\u0631\u064a\u0646): \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0629 \u062a\u062f\u062e\u0644 \u0627\u0644\u0630\u0627\u0643\u0631\u0629 \u0627\u0644\u062d\u0633\u064a\u0629 \u062b\u0645 \u0642\u0635\u064a\u0631\u0629 \u0627\u0644\u0645\u062f\u0649\u060c \u0648\u0628\u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0648\u0627\u0644\u0645\u0639\u0646\u0649 \u062a\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \u0637\u0648\u064a\u0644\u0629 \u0627\u0644\u0645\u062f\u0649.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb")
B.a_m=s(["\u0625\u0628\u0646\u062c\u0647\u0627\u0648\u0633","\u0628\u0627\u0641\u0644\u0648\u0641","\u062f\u0648\u0631\u0643\u0627\u064a\u0645","\u062c\u0627\u0631\u062f\u0646\u0631","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aRr=new A.a("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u0645\u0646\u062d\u0646\u0649 \xab\u0627\u0644\u0646\u0633\u064a\u0627\u0646\xbb \u0627\u0644\u0630\u064a \u064a\u0628\u064a\u0646 \u0623\u0646 \u0627\u0644\u0646\u0633\u064a\u0627\u0646 \u064a\u0643\u0648\u0646 \u0633\u0631\u064a\u0639\u0627\u064b \u0628\u0639\u062f \u0627\u0644\u062a\u0639\u0644\u0645 \u0645\u0628\u0627\u0634\u0631\u0629 \u062b\u0645 \u064a\u062a\u0628\u0627\u0637\u0623 \u064a\u0646\u0633\u0628 \u0625\u0644\u0649:",B.a_m,0,"\u0625\u0628\u0646\u062c\u0647\u0627\u0648\u0633 \u0635\u0627\u062d\u0628 \u0645\u0646\u062d\u0646\u0649 \u0627\u0644\u0646\u0633\u064a\u0627\u0646: \u0623\u0643\u0628\u0631 \u0646\u0633\u0628\u0629 \u0646\u0633\u064a\u0627\u0646 \u062a\u0643\u0648\u0646 \u0641\u064a \u0627\u0644\u0633\u0627\u0639\u0627\u062a \u0627\u0644\u0623\u0648\u0644\u0649 \u0628\u0639\u062f \u0627\u0644\u062a\u0639\u0644\u0645\u060c \u062b\u0645 \u064a\u062a\u0646\u0627\u0642\u0635.",u.N)
B.Xv=s(["\u0627\u0644\u0642\u062f\u0631\u0629\u060c \u0627\u0644\u062c\u0647\u062f\u060c \u0635\u0639\u0648\u0628\u0629 \u0627\u0644\u0645\u0647\u0645\u0629\u060c \u0648\u0627\u0644\u062d\u0638","\u0644\u0648\u0646 \u0627\u0644\u0623\u062f\u0648\u0627\u062a \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629 \u0641\u0642\u0637","\u0633\u0627\u0639\u0627\u062a \u0627\u0644\u0646\u0648\u0645 \u0641\u0642\u0637","\u062d\u062c\u0645 \u0627\u0644\u0642\u0633\u0645 \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
