B.aUs=new A.a("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u0641\u064a \u0627\u0644\u0643\u0634\u0641 \u0639\u0646 \u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u062f\u0627\u062e\u0644 \u0627\u0644\u0642\u0633\u0645\u060c \u064a\u0644\u0639\u0628 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u062f\u0648\u0631:",B.aii,0,"\u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0645\u0631\u0627\u0642\u0628 \u0623\u0648\u0644 \u064a\u0631\u0635\u062f \u0627\u0644\u0639\u0644\u0627\u0645\u0627\u062a \u0639\u0628\u0631 \u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0648\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u064a\u062d\u064a\u0644 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0625\u0644\u0649 \u0627\u0644\u0645\u062a\u062e\u0635\u0635\u064a\u0646 \u062f\u0648\u0646 \u0648\u0635\u0645.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.a_D=s(["\u0623\u0641\u0643\u0627\u0631 \u0645\u0633\u0628\u0642\u0629 \u062e\u0627\u0637\u0626\u0629 \u062a\u0639\u064a\u0642 \u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u062c\u062f\u064a\u062f\u0629 \u0625\u0646 \u0644\u0645 \u062a\u0633\u062a\u062b\u0645\u0631","\u0645\u0639\u0631\u0641\u0629 \u0635\u062d\u064a\u062d\u0629 \u0644\u0627 \u062a\u062d\u062a\u0627\u062c \u0625\u0644\u0649 \u062a\u0639\u062f\u064a\u0644","\u063a\u064a\u0627\u0628 \u062a\u0627\u0645 \u0644\u0623\u064a \u062a\u0635\u0648\u0631","\u062d\u0635\u064a\u0644\u0629 \u062a\u0645\u0627\u0631\u064a\u0646 \u0645\u062d\u0641\u0648\u0638\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
