B.aGH=new A.a("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u0641\u064a \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0627\u0644\u062d\u062f\u064a\u062b\u0629\u060c \u064a\u064f\u0646\u0638\u0631 \u0625\u0644\u0649 \u062e\u0637\u0623 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0628\u0627\u0639\u062a\u0628\u0627\u0631\u0647:",B.a8M,1,"\u0627\u0644\u062e\u0637\u0623 \u0623\u062b\u0631 \u0644\u0644\u062a\u0645\u062b\u0644\u0627\u062a \u0648\u0645\u0635\u062f\u0631 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u062a\u0634\u062e\u064a\u0635\u064a\u0629: \u064a\u0643\u0634\u0641 \u0637\u0631\u064a\u0642\u0629 \u062a\u0641\u0643\u064a\u0631 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u064a\u0648\u062c\u0647 \u0627\u0644\u062f\u0639\u0645 (\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u062e\u0637\u0623).","\xab\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629\xbb")
B.abB=s(["\u062a\u062c\u0646\u0628 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0627\u0631\u062a\u0643\u0627\u0628 \u0623\u064a \u062e\u0637\u0623","\u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u0627\u0644\u062e\u0637\u0623 \u0644\u0641\u0647\u0645 \u0627\u0644\u062a\u0645\u062b\u0644\u0627\u062a \u0648\u062a\u0639\u062f\u064a\u0644\u0647\u0627 \u0628\u0644\u0627 \u0639\u0642\u0627\u0628","\u0645\u0639\u0627\u0642\u0628\u0629 \u0643\u0644 \u062e\u0637\u0623 \u0628\u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0627\u062a","\u0625\u0644\u063a\u0627\u0621 \u0627\u0644\u062a\u0635\u062d\u064a\u062d \u0646\u0647\u0627\u0626\u064a\u0627\u064b","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b1m=new A.a("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u062e\u0637\u0623 \u062a\u0642\u0648\u0645 \u0639\u0644\u0649:",B.abB,1,"\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u062e\u0637\u0623 \u062a\u062c\u0639\u0644 \u0645\u0646 \u0627\u0644\u062e\u0637\u0623 \u0645\u0635\u062f\u0631 \u062a\u0639\u0644\u0645: \u062a\u062d\u0644\u064a\u0644 \u0623\u0633\u0628\u0627\u0628\u0647 \u0648\u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u062a\u0645\u062b\u0644\u0627\u062a \u0648\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0627\u0644\u0635\u062d\u064a\u062d\u0629.","\xab\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629\xbb")
B.a1a=s(["\u0639\u062f\u0645 \u0645\u0644\u0627\u0621\u0645\u0629 \u0627\u0644\u0637\u0631\u064a\u0642\u0629\u060c \u0648\u0635\u0639\u0648\u0628\u0629 \u0627\u0644\u0645\u062d\u062a\u0648\u0649\u060c \u0648\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u062a\u0642\u0648\u064a\u0645","\u0644\u0648\u0646 \u0627\u0644\u0632\u064a \u0627\u0644\u0645\u062f\u0631\u0633\u064a","\u0639\u062f\u062f \u0646\u0648\u0627\u0641\u0630 \u0627\u0644\u0642\u0633\u0645","\u0637\u0648\u0644 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062f\u0631\u0627\u0633\u064a","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b0u=new A.a("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u0645\u0646 \u0627\u0644\u0639\u0648\u0627\u0626\u0642 \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629 \u0644\u0644\u062a\u0639\u0644\u0645 \u0646\u062c\u062f:",B.a1a,0,"\u0627\u0644\u0639\u0648\u0627\u0626\u0642 \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629 \u062a\u062a\u0639\u0644\u0642 \u0628\u0637\u0631\u0642 \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u063a\u064a\u0631 \u0627\u0644\u0645\u0644\u0627\u0626\u0645\u0629 \u0648\u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0648\u0637\u0631\u0642 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u063a\u064a\u0631 \u0627\u0644\u0645\u0648\u0627\u0643\u0628\u0629.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
B.aja=s(["\u062a\u0634\u062e\u064a\u0635 \u062f\u0642\u064a\u0642 \u0644\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0648\u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0630\u0648\u064a \u062d\u0627\u062c\u0627\u062a \u0645\u062a\u0642\u0627\u0631\u0628\u0629","\u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u062d\u0633\u0628 \u0623\u0633\u0645\u0627\u0626\u0647\u0645","\u0627\u0644\u0641\u0631\u0632 \u0627\u0644\u0639\u0634\u0648\u0627\u0626\u064a","\u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0644\u0644\u0623\u0642\u0648\u064a\u0627\u0621 \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b2N=new A.a("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u0645\u062c\u0645\u0648\u0639\u0627\u062a \u0627\u0644\u062f\u0639\u0645 \u0644\u0644\u0645\u062a\u0639\u062b\u0631\u064a\u0646 \u062a\u064f\u0628\u0646\u0649 \u0639\u0644\u0649 \u0623\u0633\u0627\u0633:",B.aja,0,"\u0627\u0644\u062f\u0639\u0645 \u064a\u0628\u062f\u0623 \u0628\u0627\u0644\u062a\u0634\u062e\u064a\u0635 \u062b\u0645 \u062a\u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0648\u0641\u0642 \u0646\u0648\u0639\u064a\u0629 \u0627\u0644\u062a\u0639\u062b\u0631 \u0648\u062a\u062f\u0628\u064a\u0631 \u0623\u0646\u0634\u0637\u0629 \u0645\u0639\u0627\u0644\u062c\u0629 \u0645\u0646\u0627\u0633\u0628\u0629.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
