B.aK6=new A.a("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0641\u0627\u0631\u0642\u064a\u0629 \u062a\u0631\u0627\u0639\u064a \u0627\u0644\u0641\u0631\u0648\u0642 \u0628\u064a\u0646 \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0641\u064a:",B.a00,0,"\u0627\u0644\u062a\u0641\u0631\u064a\u0642 \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a: \u062a\u0646\u0648\u064a\u0639 \u0627\u0644\u0645\u062f\u062e\u0644\u0627\u062a (\u0627\u0644\u0645\u062d\u062a\u0648\u0649/\u0627\u0644\u0637\u0631\u064a\u0642\u0629/\u0627\u0644\u0648\u0633\u0627\u0626\u0637/\u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0627\u062a/\u0627\u0644\u062a\u0642\u0648\u064a\u0645) \u0644\u0627\u0633\u062a\u064a\u0639\u0627\u0628 \u0627\u0644\u0641\u0631\u0648\u0642.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb")
B.arE=s(["\u0635\u0639\u0648\u0628\u0629 \u0641\u064a \u0627\u0644\u062a\u0631\u0643\u064a\u0632\u060c \u0648\u0627\u0646\u062f\u0641\u0627\u0639\u064a\u0629\u060c \u0648\u062d\u0631\u0643\u0629 \u0645\u0641\u0631\u0637\u0629","\u062e\u0645\u0648\u0644 \u062f\u0627\u0626\u0645 \u0628\u0644\u0627 \u062d\u0631\u0643\u0629","\u0642\u062f\u0631\u0629 \u0641\u0627\u0626\u0642\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0631\u0643\u064a\u0632","\u0627\u0636\u0637\u0631\u0627\u0628 \u0641\u064a \u0627\u0644\u0646\u0648\u0645 \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aPS=new A.a("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u062f\u0627\u0621 \u0641\u0631\u0637 \u0627\u0644\u062d\u0631\u0643\u0629 \u0648\u062a\u0634\u062a\u062a \u0627\u0644\u0627\u0646\u062a\u0628\u0627\u0647 (TDAH) \u064a\u0638\u0647\u0631 \u0639\u0627\u062f\u0629 \u0644\u062f\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0641\u064a \u0635\u0648\u0631\u0629:",B.arE,0,"TDAH \u0627\u0636\u0637\u0631\u0627\u0628 \u0646\u0645\u0627\u0626\u064a \u064a\u0639\u064a\u0642 \u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0648\u0627\u0644\u0627\u0646\u0636\u0628\u0627\u0637 \u0627\u0644\u0627\u0646\u0641\u0639\u0627\u0644\u064a \u0648\u0627\u0644\u0633\u0644\u0648\u0643\u064a\u060c \u0648\u064a\u062a\u0637\u0644\u0628 \u062a\u062f\u0628\u064a\u0631\u0627\u064b \u062a\u0631\u0628\u0648\u064a\u0627\u064b \u0645\u0644\u0627\u0626\u0645\u0627\u064b \u0648\u062f\u0639\u0645\u0627\u064b \u0645\u062a\u062e\u0635\u0635\u0627\u064b.","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629\xbb")
B.a7h=s(["\u0645\u0634\u0631\u0648\u0639 \u0641\u0631\u062f\u064a \u0628\u0645\u0631\u0627\u0641\u0642\u0629 \u0627\u0644\u0645\u0639\u0644\u0651\u0645 \u0648\u0623\u0648\u0644\u064a\u0627\u0621 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u062e\u062a\u0635\u064a\u0646","\u0625\u0628\u0639\u0627\u062f \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0639\u0646 \u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0646\u0647\u0627\u0626\u064a\u0627\u064b","\u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u0633\u0646\u0629 \u062f\u0648\u0646 \u0623\u064a \u062a\u063a\u064a\u064a\u0631","\u0645\u0646\u062d \u0627\u0644\u0646\u0642\u0637 \u062f\u0648\u0646 \u062a\u0639\u0644\u0645","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b3K=new A.a("\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647",null,"\u0639\u0646\u062f \u0627\u0644\u062a\u0639\u062b\u0631\u0627\u062a \u0627\u0644\u0639\u0645\u064a\u0642\u0629 \u0648\u0627\u0644\u0645\u0633\u062a\u0645\u0631\u0629\u060c \u064a\u064f\u0646\u0635\u062d \u0628\u062a\u0643\u064a\u064a\u0641 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0639\u0628\u0631:",B.a7h,0,"\u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0639\u0645\u064a\u0642\u0629 \u062a\u062a\u0637\u0644\u0628 \u0628\u0631\u0646\u0627\u0645\u062c\u0627 \u0641\u0631\u062f\u064a\u0627 \u0644\u0644\u062a\u0643\u064a\u064a\u0641 \u0648\u0627\u0644\u0645\u0648\u0627\u0643\u0628\u0629 (\u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0648\u0627\u0644\u0623\u0633\u0631\u0629 \u0648\u0627\u0644\u0645\u0635\u0627\u0644\u062d \u0627\u0644\u0645\u062e\u062a\u0635\u0629).","\xab\u0639\u062f\u0629 \u0627\u0644\u062a\u0643\u0648\u064a\u0646 - \u0645\u062c\u0632\u0648\u0621\u0629 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\xbb")
