B.ahw=s(["\u062a\u062f\u0631\u064a\u0633 \u062c\u0645\u064a\u0639 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0646\u0641\u0633 \u0627\u0644\u062f\u0631\u0633 \u0645\u0647\u0645\u0627 \u0643\u0627\u0646\u062a \u0645\u0633\u062a\u0648\u064a\u0627\u062a\u0647\u0645","\u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0648\u0641\u0642 \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0645\u062f\u0631\u0633\u064a \u062d\u0635\u0631\u0627\u064b","\u062a\u0642\u0633\u064a\u0645 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0625\u0644\u0649 \u0645\u062c\u0645\u0648\u0639\u0627\u062a \u062d\u0633\u0628 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0648\u0644\u064a\u0633 \u062d\u0633\u0628 \u0627\u0644\u0633\u0646","\u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f \u0639\u0644\u0649 \u0627\u0644\u0648\u0627\u062c\u0628\u0627\u062a \u0627\u0644\u0645\u0646\u0632\u0644\u064a\u0629 \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aS0=new A.a("\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u062f\u0629 \u2014 \u0645\u0642\u0627\u0631\u0628\u0629 TaRL",null,"\u0645\u0627\u0630\u0627 \u064a\u0639\u0646\u064a \u0645\u0628\u062f\u0623 TaRL\u061f",B.ahw,2,"TaRL \u064a\u0639\u0646\u064a \u062a\u0642\u0633\u064a\u0645 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0625\u0644\u0649 \u0645\u062c\u0645\u0648\u0639\u0627\u062a \u062d\u0633\u0628 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0641\u0639\u0644\u064a \u0648\u0644\u064a\u0633 \u062d\u0633\u0628 \u0627\u0644\u0633\u0646.","\u0628\u0646\u0643 \u0623\u0633\u0626\u0644\u0629 \u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u062f\u0629")
B.ao7=s(["\u0633\u0627\u0639\u062a\u0627\u0646 \u064a\u0648\u0645\u064a\u0627\u064b \u0644\u0644\u0639\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0641\u0631\u0646\u0633\u064a\u0629 \u0648\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0633\u0627\u0639\u0629 \u0648\u0627\u062d\u062f\u0629 \u064a\u0648\u0645\u064a\u0627\u064b \u0644\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u0639\u0644\u0645\u064a\u0629","\u062b\u0644\u0627\u062b \u0633\u0627\u0639\u0627\u062a \u064a\u0648\u0645\u064a\u0627\u064b \u0644\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u0645\u0648\u0627\u0632\u064a\u0629","\u0623\u0631\u0628\u0639 \u0633\u0627\u0639\u0627\u062a \u064a\u0648\u0645\u064a\u0627\u064b \u0644\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0628\u062f\u0646\u064a\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aHC=new A.a("\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u062f\u0629 \u2014 \u0645\u0642\u0627\u0631\u0628\u0629 TaRL",null,"\u0643\u0645 \u0633\u0627\u0639\u0629 \u064a\u0648\u0645\u064a\u0627\u064b \u062a\u064f\u062e\u0635\u0635 \u0644\u0644\u0623\u0633\u0627\u0633\u064a\u0627\u062a \u0641\u064a \u0627\u0644\u0631\u064a\u0627\u062f\u0629\u061f",B.ao7,0,"\u062a\u064f\u062e\u0635\u0635 \u0633\u0627\u0639\u062a\u0627\u0646 \u064a\u0648\u0645\u064a\u0627\u064b \u0641\u064a \u0627\u0644\u0631\u064a\u0627\u062f\u0629 \u0644\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0627\u0644\u0623\u0633\u0627\u0633: \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0641\u0631\u0646\u0633\u064a\u0629 \u0648\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a.","\u0628\u0646\u0643 \u0623\u0633\u0626\u0644\u0629 \u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u062f\u0629")
B.a1r=s(["\u0645\u0631\u062a\u0643\u0632\u0627\u062a \u0645\u0627\u0644\u064a\u0629 \u0648\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629 \u0641\u0642\u0637","\u0645\u0631\u062a\u0643\u0632\u0627\u062a \u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629 \u0648\u0644\u0648\u062c\u064a\u0633\u062a\u064a\u0643\u064a\u0629 \u0648\u062a\u062f\u0628\u064a\u0631\u064a\u0629","\u0645\u0631\u062a\u0643\u0632\u0627\u062a \u0625\u062f\u0627\u0631\u064a\u0629 \u0648\u0642\u0636\u0627\u0626\u064a\u0629","\u0645\u0631\u062a\u0643\u0632\u0627\u062a \u062a\u0642\u0646\u064a\u0629 \u0648\u0635\u0646\u0627\u0639\u064a\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
