B.aQ8=new A.a("\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u062f\u0629 \u2014 \u0645\u0642\u0627\u0631\u0628\u0629 TaRL",null,"\u0645\u0627 \u0647\u0648 \u0646\u0645\u0648\u0630\u062c \u0627\u0644\u062d\u0635\u0629 \u0641\u064a \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0627\u0644\u0635\u0631\u064a\u062d\u0629 \u0628\u0627\u0644\u0631\u064a\u0627\u062f\u0629\u061f",B.aqQ,2,"\u0646\u0645\u0648\u0630\u062c \u0627\u0644\u062d\u0635\u0629 \u0641\u064a \u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0629 \u0627\u0644\u0635\u0631\u064a\u062d\u0629: \u0623\u0646\u0627 \u0623\u0628\u064a\u0646 (\u0627\u0644\u0646\u0645\u0630\u062c\u0629) \u062b\u0645 \u0646\u062f\u064a\u0631\u0648 \u0628\u062c\u0648\u062c (\u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0648\u062c\u0647\u0629) \u062b\u0645 \u062f\u064a\u0631 \u0628\u0648\u062d\u062f\u0643 (\u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0633\u062a\u0642\u0644\u0629).","\u0628\u0646\u0643 \u0623\u0633\u0626\u0644\u0629 \u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u062f\u0629")
B.al7=s(["\u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629","\u0628\u0639\u062f \u0643\u0644 \u0648\u062d\u062f\u0629 \u062f\u0631\u0627\u0633\u064a\u0629","\u062e\u0644\u0627\u0644 \u0627\u0644\u0639\u0637\u0644\u0629 \u0627\u0644\u0635\u064a\u0641\u064a\u0629","\u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b50=new A.a("\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u062f\u0629 \u2014 \u0645\u0642\u0627\u0631\u0628\u0629 TaRL",null,"\u0645\u062a\u0649 \u064a\u064f\u0646\u062c\u064e\u0632 \u0627\u0644\u062a\u0642\u064a\u064a\u0645 \u0627\u0644\u062a\u0634\u062e\u064a\u0635\u064a \u0641\u064a \u0627\u0644\u0631\u064a\u0627\u062f\u0629\u061f",B.al7,3,"\u064a\u064f\u0646\u062c\u0632 \u0627\u0644\u062a\u0642\u064a\u064a\u0645 \u0627\u0644\u062a\u0634\u062e\u064a\u0635\u064a \u0641\u064a \u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629 \u0644\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0641\u0639\u0644\u064a \u0644\u0644\u062a\u0644\u0627\u0645\u064a\u0630.","\u0628\u0646\u0643 \u0623\u0633\u0626\u0644\u0629 \u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u062f\u0629")
