B.a3F=s(["30 \u062f\u0642\u064a\u0642\u0629 (\u062d\u0635\u0629 \u0648\u0627\u062d\u062f\u0629)","60 \u062f\u0642\u064a\u0642\u0629 (\u062d\u0635\u062a\u0627\u0646)","90 \u062f\u0642\u064a\u0642\u0629 (\u062b\u0644\u0627\u062b \u062d\u0635\u0635)","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629"],t.s)
B.aRt=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u063a\u0644\u0627\u0641 \u0627\u0644\u0632\u0645\u0646\u064a \u0627\u0644\u0623\u0633\u0628\u0648\u0639\u064a \u0627\u0644\u0645\u062e\u0635\u0635 \u0644\u0645\u0643\u0648\u0646 \u0627\u0644\u0634\u0643\u0644 \u0648\u0627\u0644\u062a\u0637\u0628\u064a\u0642\u0627\u062a \u0627\u0644\u0643\u062a\u0627\u0628\u064a\u0629 \u0647\u0648:",B.a3F,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: 30 \u062f\u0642\u064a\u0642\u0629 (\u062d\u0635\u0629 \u0648\u0627\u062d\u062f\u0629)",u.e)
B.atm=s(["\u0627\u0644\u0625\u0646\u062c\u0627\u0632 \u2190 \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u2190 \u0627\u0644\u062a\u0635\u062d\u064a\u062d \u0648\u0627\u0644\u0639\u0631\u0636 \u2190 \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u0648\u0627\u0644\u062a\u0646\u0642\u064a\u062d.","\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u2190 \u0627\u0644\u0625\u0646\u062c\u0627\u0632 (\u0645\u062d\u0627\u0648\u0644\u0629 \u0623\u0648\u0644\u0649) \u2190 \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u0648\u0627\u0644\u062a\u0646\u0642\u064a\u062d \u2190 \u0627\u0644\u062a\u0635\u062d\u064a\u062d \u0648\u0627\u0644\u0639\u0631\u0636.","\u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u0648\u0627\u0644\u062a\u0646\u0642\u064a\u062d \u2190 \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u2190 \u0627\u0644\u0625\u0646\u062c\u0627\u0632 \u2190 \u0627\u0644\u062a\u0635\u062d\u064a\u062d \u0648\u0627\u0644\u0639\u0631\u0636.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
