B.aW6=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u062a\u064a \u062a\u064f\u0639\u062a\u0645\u062f \u0642\u0628\u064a\u0644 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0644\u0627\u0633\u062a\u0643\u0634\u0627\u0641 \u0627\u0644\u0645\u0648\u0636\u0648\u0639 \u062a\u0639\u062a\u0645\u062f \u0639\u0644\u0649:",B.ay1,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0635\u064a\u0627\u063a\u0629 \u0627\u0644\u062a\u0648\u0642\u0639\u0627\u062a \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0627\u0644\u0645\u0634\u064a\u0631\u0627\u062a \u0627\u0644\u062a\u0631\u0643\u064a\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u0635\u0631\u064a\u0629 (\u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0648\u0627\u0644\u0635\u0648\u0631\u0629).",u.e)
B.a7F=s(["\u0642\u0631\u0627\u0621\u0629 \u0623\u0633\u0631\u0639 \u062a\u0644\u0645\u064a\u0630 \u0641\u064a \u0627\u0644\u0641\u0635\u0644 \u0644\u064a\u0642\u062a\u062f\u064a \u0628\u0647 \u0628\u0627\u0642\u064a \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630.","\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0627\u0644\u062c\u0647\u0631\u064a\u0629 \u0627\u0644\u0645\u062a\u0623\u0646\u064a\u0629 \u0648\u0627\u0644\u0645\u062a\u0645\u062b\u0644\u0629 \u0644\u0644\u0645\u0639\u0646\u0649 \u0644\u062a\u0643\u0648\u0646 \u0645\u0639\u064a\u0627\u0631\u0627\u064b \u064a\u064f\u0642\u062a\u062f\u0649 \u0628\u0647.","\u0642\u0631\u0627\u0621\u0629 \u062c\u0645\u064a\u0639 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0641\u064a \u0648\u0642\u062a \u0648\u0627\u062d\u062f \u0628\u0635\u0648\u062a \u0645\u0631\u062a\u0641\u0639.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b1o=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0646\u0645\u0630\u062c\u064a\u0629 \u0641\u064a \u062d\u0635\u0635 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0647\u0648:",B.a7F,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0627\u0644\u062c\u0647\u0631\u064a\u0629 \u0627\u0644\u0645\u062a\u0623\u0646\u064a\u0629 \u0648\u0627\u0644\u0645\u062a\u0645\u062b\u0644\u0629 \u0644\u0644\u0645\u0639\u0646\u0649 \u0644\u062a\u0643\u0648\u0646 \u0645\u0639\u064a\u0627\u0631\u0627\u064b \u064a\u064f\u0642\u062a\u062f\u0649 \u0628\u0647.",u.e)
B.aqW=s(["\u062a\u0642\u062f\u064a\u0645 \u0642\u0648\u0627\u0639\u062f \u0627\u0644\u0625\u0639\u0631\u0627\u0628 \u0627\u0644\u0635\u0631\u064a\u062d\u0629 \u062f\u0648\u0646 \u0623\u0645\u062b\u0644\u0629.","\u062a\u0645\u0631\u064a\u0631 \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0628\u0634\u0643\u0644 \u0636\u0645\u0646\u064a \u0648\u0645\u062f\u0645\u062c \u0641\u064a \u0627\u0644\u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u062f\u0648\u0646 \u062a\u0635\u0631\u064a\u062d \u0628\u0627\u0644\u0642\u0627\u0639\u062f\u0629.","\u0625\u0644\u063a\u0627\u0621 \u0627\u0644\u0638\u0648\u0627\u0647\u0631 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0646\u0647\u0627\u0626\u064a\u0627\u064b \u0645\u0646 \u0627\u0644\u062a\u062e\u0637\u064a\u0637.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b3Y=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0627\u0633\u062a\u0636\u0645\u0627\u0631 \u0641\u064a \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0638\u0648\u0627\u0647\u0631 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0628\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0623\u0648\u0644\u0649 \u0645\u0646 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a \u064a\u0639\u0646\u064a:",B.aqW,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0645\u0631\u064a\u0631 \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0628\u0634\u0643\u0644 \u0636\u0645\u0646\u064a \u0648\u0645\u062f\u0645\u062c \u0641\u064a \u0627\u0644\u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u062f\u0648\u0646 \u062a\u0635\u0631\u064a\u062d \u0628\u0627\u0644\u0642\u0627\u0639\u062f\u0629.",u.e)
B.a69=s(["\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0623\u0648\u0644 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a.","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u062b\u0627\u0644\u062b \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a.","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a.","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u062e\u0627\u0645\u0633 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a."],t.s)
B.b0j=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u062a\u0635\u0631\u064a\u062d \u0628\u0627\u0644\u0638\u0648\u0627\u0647\u0631 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 (\u0635\u0631\u0641 \u0648\u062a\u062d\u0648\u064a\u0644\u060c \u062a\u0631\u0627\u0643\u064a\u0628\u060c \u0625\u0645\u0644\u0627\u0621) \u0641\u064a \u0647\u064a\u0643\u0644\u0629 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u064a\u0628\u062f\u0623 \u0631\u0633\u0645\u064a\u0627\u064b \u0645\u0646:",B.a69,2,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a.",u.e)
B.ahm=s(["\u064a\u064f\u0648\u0638\u0641 \u0644\u062e\u062f\u0645\u0629 \u0648\u0638\u064a\u0641\u0629 \u0645\u0633\u062a\u0642\u0628\u0644\u064a\u0651\u0629 \u0644\u0644\u062a\u0644\u0645\u064a\u0630.","\u064a\u064f\u0648\u0638\u0641 \u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u0638\u0648\u0627\u0647\u0631 \u0644\u063a\u0648\u064a\u0629 \u0648\u0645\u062c\u0627\u0644\u064a\u0629 \u0645\u062d\u062f\u062f\u0629 \u0628\u0637\u0631\u064a\u0642\u0629 \u0645\u062f\u0645\u062c\u0629 \u0645\u0639 \u0627\u0644\u0641\u0647\u0645.","\u064a\u064f\u0643\u062a\u0628 \u0628\u0623\u0633\u0644\u0648\u0628 \u0625\u062f\u0627\u0631\u064a \u0648\u0631\u0633\u0645\u064a \u0641\u0642\u0637.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b_t=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u064a\u064f\u0633\u0645\u0649 \u0627\u0644\u0646\u0635 \u0627\u0644\u0648\u0638\u064a\u0641\u064a \u0628\u0647\u0630\u0627 \u0627\u0644\u0627\u0633\u0645 \u0644\u0623\u0646\u0647:",B.ahm,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u064a\u064f\u0648\u0638\u0641 \u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u0638\u0648\u0627\u0647\u0631 \u0644\u063a\u0648\u064a\u0629 \u0648\u0645\u062c\u0627\u0644\u064a\u0629 \u0645\u062d\u062f\u062f\u0629 \u0628\u0637\u0631\u064a\u0642\u0629 \u0645\u062f\u0645\u062c\u0629 \u0645\u0639 \u0627\u0644\u0641\u0647\u0645.",u.e)
B.as_=s(["\u062d\u0635\u0629 \u0648\u0627\u062d\u062f\u0629 \u0641\u064a \u0627\u0644\u0633\u0646\u0629.","4 \u062d\u0635\u0635 \u0628\u0648\u0627\u0642\u0639 \u062d\u0635\u0629 \u0641\u064a \u0643\u0644 \u0623\u0633\u0628\u0648\u0639 \u0645\u0646 \u0623\u0633\u0627\u0628\u064a\u0639 \u0625\u0631\u0633\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a.","\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0641\u0642\u0637.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aXd=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u062a\u064f\u0642\u062f\u0645 \u0627\u0644\u0645\u0647\u0627\u0631\u0629 \u0627\u0644\u0648\u0627\u062d\u062f\u0629 \u0641\u064a \u0645\u0643\u0648\u0646 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u0633\u062a\u0631\u0633\u0644\u0629 \u0639\u0644\u0649 \u0645\u062f\u0649:",B.as_,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: 4 \u062d\u0635\u0635 \u0628\u0648\u0627\u0642\u0639 \u062d\u0635\u0629 \u0641\u064a \u0643\u0644 \u0623\u0633\u0628\u0648\u0639 \u0645\u0646 \u0623\u0633\u0627\u0628\u064a\u0639 \u0625\u0631\u0633\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a.",u.e)
B.a9q=s(["\u0635\u064a\u0627\u063a\u0629 \u062a\u0648\u0642\u0639\u0627\u062a \u062d\u0648\u0644 \u0627\u0644\u0646\u0635 \u0642\u0628\u0644 \u0642\u0631\u0627\u0621\u062a\u0647.","\u0627\u0644\u0628\u062d\u062b \u0639\u0646 \u0645\u0634\u062a\u0642\u0627\u062a \u0627\u0644\u0643\u0644\u0645\u0629 \u0645\u0646 \u0646\u0641\u0633 \u0627\u0644\u062c\u0630\u0631 \u0627\u0644\u0644\u063a\u0648\u064a \u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0631\u0635\u064a\u062f \u0627\u0644\u0645\u0639\u062c\u0645\u064a.","\u062a\u062d\u062f\u064a\u062f \u0623\u0636\u062f\u0627\u062f \u0627\u0644\u0645\u0631\u0627\u062f\u0641\u0627\u062a \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0641\u0642\u0637.","\u0625\u0639\u0631\u0627\u0628 \u0627\u0644\u0643\u0644\u0645\u0629 \u0625\u0639\u0631\u0627\u0628\u0627\u064b \u062a\u0627\u0645\u0627\u064b."],t.s)
B.aRh=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 "\u0639\u0627\u0626\u0644\u0629 \u0627\u0644\u0643\u0644\u0645\u0629" \u062a\u0647\u062f\u0641 \u0628\u0627\u0644\u0623\u0633\u0627\u0633 \u0625\u0644\u0649:',B.a9q,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0628\u062d\u062b \u0639\u0646 \u0645\u0634\u062a\u0642\u0627\u062a \u0627\u0644\u0643\u0644\u0645\u0629 \u0645\u0646 \u0646\u0641\u0633 \u0627\u0644\u062c\u0630\u0631 \u0627\u0644\u0644\u063a\u0648\u064a \u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0631\u0635\u064a\u062f \u0627\u0644\u0645\u0639\u062c\u0645\u064a.",u.e)
B.a8h=s(["\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u0627\u0644\u0625\u0646\u062c\u0627\u0632.","\u0645\u0631\u062d\u0644\u0629 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642 / \u0627\u0644\u062a\u0645\u0647\u064a\u062f.","\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0646\u0647\u0627\u0626\u064a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b4S=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0645\u062d\u0648\u0631 \u0627\u0644\u062b\u0627\u0646\u064a: \u0647\u0646\u062f\u0633\u0629 \u0627\u0644\u062c\u0630\u0627\u0630\u0629 \u0648\u0645\u0631\u0627\u062d\u0644 \u0628\u0646\u0627\u0621 \u0627\u0644\u062f\u0631\u0633 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0641\u064a \u0647\u064a\u0643\u0644\u0629 \u0623\u064a \u062c\u0630\u0627\u0630\u0629 \u062f\u0631\u0633 \u062a\u0646\u062a\u0645\u064a \u0644\u0645\u062f\u062e\u0644 \u0627\u0644\u0648\u0636\u0639\u064a\u0627\u062a \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629 \u0647\u064a:",B.a8h,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0645\u0631\u062d\u0644\u0629 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642 / \u0627\u0644\u062a\u0645\u0647\u064a\u062f.",u.e)
B.akQ=s(["\u0648\u0636\u0639 \u0627\u0644\u0639\u0644\u0627\u0645\u0627\u062a \u0648\u0627\u0644\u062f\u0631\u062c\u0627\u062a \u0644\u0644\u062a\u0644\u0627\u0645\u064a\u0630.","\u0625\u062d\u062f\u0627\u062b \u0635\u0631\u0627\u0639 \u0645\u0639\u0631\u0641\u064a \u0648\u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0648\u0627\u0644\u0631\u0628\u0637 \u0628\u0627\u0644\u062f\u0631\u0633 \u0627\u0644\u062c\u062f\u064a\u062f.","\u0625\u0639\u0637\u0627\u0621 \u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u062f\u0631\u0633 \u0645\u0643\u062a\u0648\u0628\u0629 \u0639\u0644\u0649 \u0627\u0644\u0633\u0628\u0648\u0631\u0629 \u0644\u0646\u0642\u0644\u0647\u0627.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aLQ=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u062a\u0633\u062a\u0647\u062f\u0641 "\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642" \u0641\u064a \u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u062f\u0631\u0633 \u0628\u0634\u0643\u0644 \u0631\u0626\u064a\u0633\u064a:',B.akQ,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0625\u062d\u062f\u0627\u062b \u0635\u0631\u0627\u0639 \u0645\u0639\u0631\u0641\u064a \u0648\u062a\u0634\u062e\u064a\u0635 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0648\u0627\u0644\u0631\u0628\u0637 \u0628\u0627\u0644\u062f\u0631\u0633 \u0627\u0644\u062c\u062f\u064a\u062f.",u.e)
B.Y6=s(["\u0646\u0642\u0644 \u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0627\u0644\u0645\u0643\u062a\u0648\u0628\u0629 \u0641\u064a \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0645\u062f\u0631\u0633\u064a \u0645\u0628\u0627\u0634\u0631\u0629.","\u0639\u0631\u0636 \u0627\u0644\u0634\u0648\u0627\u0647\u062f\u060c \u0642\u0631\u0627\u0621\u062a\u0647\u0627\u060c \u062a\u062d\u0644\u064a\u0644\u0647\u0627\u060c \u0627\u0644\u0645\u0648\u0627\u0632\u0646\u0629 \u0628\u064a\u0646\u0647\u0627 \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0633\u062a\u0646\u062a\u0627\u062c \u0627\u0644\u0642\u0627\u0639\u062f\u0629.","\u0625\u0646\u062c\u0627\u0632 \u062a\u0645\u0627\u0631\u064a\u0646 \u0643\u062a\u0627\u0628\u064a\u0629 \u062f\u0627\u0639\u0645\u0629 \u0641\u064a \u062f\u0641\u062a\u0631 \u0627\u0644\u062f\u0639\u0645.","\u062a\u0635\u062d\u064a\u062d \u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0641\u0631\u0636 \u0627\u0644\u0645\u0646\u0632\u0644\u064a."],t.s)
B.b6u=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0645\u0631\u062d\u0644\u0629 "\u0627\u0644\u0628\u0646\u0627\u0621 \u0648\u0627\u0644\u0627\u0643\u062a\u0634\u0627\u0641" \u0641\u064a \u062f\u0631\u0633 \u0627\u0644\u0638\u0648\u0627\u0647\u0631 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u062a\u0634\u0645\u0644 \u0623\u0646\u0634\u0637\u0629:',B.Y6,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0639\u0631\u0636 \u0627\u0644\u0634\u0648\u0627\u0647\u062f\u060c \u0642\u0631\u0627\u0621\u062a\u0647\u0627\u060c \u062a\u062d\u0644\u064a\u0644\u0647\u0627\u060c \u0627\u0644\u0645\u0648\u0627\u0632\u0646\u0629 \u0628\u064a\u0646\u0647\u0627 \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0633\u062a\u0646\u062a\u0627\u062c \u0627\u0644\u0642\u0627\u0639\u062f\u0629.",u.e)
B.a6r=s(["\u0628\u0646\u0627\u0621 \u0645\u0641\u0647\u0648\u0645 \u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u062c\u062f\u064a\u062f \u0644\u0645 \u064a\u0633\u0628\u0642 \u0634\u0631\u062d\u0647.","\u0646\u0642\u0644 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0645\u0646 \u0627\u0644\u0641\u0647\u0645 \u0627\u0644\u0646\u0638\u0631\u064a \u0625\u0644\u0649 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0639\u0628\u0631 \u062a\u0645\u0627\u0631\u064a\u0646 \u0648\u0625\u0646\u062c\u0627\u0632\u0627\u062a \u0645\u062d\u062f\u062f\u0629.","\u0635\u064a\u0627\u063a\u0629 \u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u0648\u062d\u062f\u0629 \u0627\u0644\u0642\u0627\u062f\u0645\u0629.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aPQ=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u0631\u0626\u064a\u0633\u064a \u0645\u0646 \u0645\u0631\u062d\u0644\u0629 "\u0627\u0644\u062a\u062b\u0628\u064a\u062a \u0648\u0627\u0644\u062a\u0637\u0628\u064a\u0642" \u062f\u0627\u062e\u0644 \u0627\u0644\u0641\u0635\u0644 \u0647\u0648:',B.a6r,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0646\u0642\u0644 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0645\u0646 \u0627\u0644\u0641\u0647\u0645 \u0627\u0644\u0646\u0638\u0631\u064a \u0625\u0644\u0649 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0639\u0628\u0631 \u062a\u0645\u0627\u0631\u064a\u0646 \u0648\u0625\u0646\u062c\u0627\u0632\u0627\u062a \u0645\u062d\u062f\u062f\u0629.",u.e)
B.Xm=s(["\u0627\u0644\u0628\u0646\u0627\u0621 \u2190 \u0627\u0644\u062a\u0645\u0647\u064a\u062f \u2190 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u2190 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645.","\u0627\u0644\u062a\u0645\u0647\u064a\u062f \u0648\u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0645\u0634\u0643\u0644 \u2190 \u0627\u0644\u0628\u0646\u0627\u0621 \u0648\u0627\u0644\u0627\u0643\u062a\u0634\u0627\u0641 \u2190 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u0627\u0644\u062a\u062b\u0628\u064a\u062a \u2190 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645.","\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u2190 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u2190 \u0627\u0644\u0628\u0646\u0627\u0621 \u2190 \u0627\u0644\u062a\u0645\u0647\u064a\u062f.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b51=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u0627\u0644\u0639\u0644\u0645\u064a \u0627\u0644\u0645\u0646\u0637\u0642\u064a \u0644\u0645\u0642\u0627\u0637\u0639 \u062c\u0630\u0627\u0630\u0629 \u062f\u0631\u0633 \u0644\u063a\u0648\u064a \u0647\u0648:",B.Xm,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062a\u0645\u0647\u064a\u062f \u0648\u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0645\u0634\u0643\u0644 \u2190 \u0627\u0644\u0628\u0646\u0627\u0621 \u0648\u0627\u0644\u0627\u0643\u062a\u0634\u0627\u0641 \u2190 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u0627\u0644\u062a\u062b\u0628\u064a\u062a \u2190 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645.",u.e)
B.awT=s(["\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0648\u0645\u0644\u0627\u062d\u0638\u0629 \u0627\u0644\u0635\u0648\u0631 \u0641\u0642\u0637.","\u0627\u0644\u062a\u0633\u0645\u064a\u0639 \u0627\u0644\u0623\u0648\u0644\u064a \u0644\u0644\u0623\u0633\u062a\u0627\u0630 \u0648\u0635\u064a\u0627\u063a\u0629 \u0627\u0644\u062a\u0648\u0642\u0639\u0627\u062a.","\u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u060c \u0627\u0644\u062a\u0631\u0643\u064a\u0628\u060c \u0627\u0644\u062a\u0644\u062e\u064a\u0635\u060c \u0648\u0625\u0628\u062f\u0627\u0621 \u0627\u0644\u0631\u0623\u064a \u0641\u064a \u0642\u0636\u0627\u064a\u0627 \u0627\u0644\u0646\u0635.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aPa=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u064a \u062a\u064f\u0646\u062c\u0632 \u062e\u0644\u0627\u0644 \u0645\u0631\u062d\u0644\u0629 "\u0645\u0627 \u0628\u0639\u062f \u0627\u0644\u0642\u0631\u0627\u0621\u0629" \u0641\u064a \u0645\u0643\u0648\u0646 \u0627\u0644\u0646\u0635 \u0627\u0644\u0648\u0638\u064a\u0641\u064a \u062a\u0634\u0645\u0644:',B.awT,2,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u060c \u0627\u0644\u062a\u0631\u0643\u064a\u0628\u060c \u0627\u0644\u062a\u0644\u062e\u064a\u0635\u060c \u0648\u0625\u0628\u062f\u0627\u0621 \u0627\u0644\u0631\u0623\u064a \u0641\u064a \u0642\u0636\u0627\u064a\u0627 \u0627\u0644\u0646\u0635.",u.e)
B.a0i=s(["\u0639\u0627\u0645\u0629 \u062c\u062f\u0627\u064b \u0648\u0634\u0627\u0645\u0644\u0629 \u0644\u062c\u0645\u064a\u0639 \u0633\u0646\u0648\u0627\u062a \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a.","\u0645\u062d\u062f\u062f\u0629\u060c \u062f\u0642\u064a\u0642\u0629\u060c \u0648\u0642\u0627\u0628\u0644\u0629 \u0644\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0648\u0627\u0644\u0642\u064a\u0627\u0633 \u0644\u062f\u0649 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u062e\u0644\u0627\u0644 \u0627\u0644\u062d\u0635\u0629.","\u062e\u0627\u0635\u0629 \u0628\u0645\u0647\u0627\u0645 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0641\u0642\u0637 \u062f\u0648\u0646 \u0627\u0644\u062a\u0644\u0645\u064a\u0630.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
