B.aYU=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0645\u0634\u0631\u0648\u0639 "\u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u0645\u062f\u0645\u062c" (PEI) \u064a\u064f\u0639\u062a\u0628\u0631 \u0627\u0644\u0625\u0637\u0627\u0631 \u0627\u0644\u0645\u0646\u0647\u062c\u064a \u0627\u0644\u0645\u0639\u062a\u0645\u062f \u0644\u0640:',B.a9m,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0646\u0632\u064a\u0644 \u0648\u0628\u0631\u0645\u062c\u0629 \u0645\u062e\u062a\u0644\u0641 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0648\u062d\u0633\u0627\u0628 \u0623\u0648\u0644\u0648\u064a\u0627\u062a \u062a\u062d\u0633\u064a\u0646 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0628\u0627\u0644\u0645\u0624\u0633\u0633\u0629.",u.e)
B.a7T=s(["\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0639\u0644\u0627\u062c\u064a.","\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0648\u0642\u0627\u0626\u064a.","\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0639\u0648\u064a\u0636\u064a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b27=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0630\u064a \u064a\u064f\u0642\u062f\u0645 \u0642\u0628\u0644 \u0627\u0646\u0637\u0644\u0627\u0642 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0644\u0648\u0642\u0627\u064a\u0629 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0645\u0646 \u0627\u0644\u0648\u0642\u0648\u0639 \u0641\u064a \u062a\u0639\u062b\u0631\u0627\u062a \u0645\u062a\u0648\u0642\u0639\u0629 \u064a\u064f\u0633\u0645\u0649:",B.a7T,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0648\u0642\u0627\u0626\u064a.",u.e)
B.Yo=s(["\u0648\u062b\u064a\u0642\u0629 \u0625\u062f\u0627\u0631\u064a\u0629 \u0648\u0642\u0627\u0646\u0648\u0646\u064a\u0629 \u0625\u0644\u0632\u0627\u0645\u064a\u0629 \u064a\u062a\u062d\u0645\u0644 \u0627\u0644\u0645\u062f\u0631\u0633 \u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u062a\u062d\u064a\u064a\u0646\u0647\u0627 \u0644\u0644\u0631\u062c\u0648\u0639 \u0625\u0644\u064a\u0647\u0627 \u0639\u0646\u062f \u0627\u0644\u062d\u0648\u0627\u062f\u062b \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629.","\u0645\u062c\u0631\u062f \u0645\u0633\u0648\u062f\u0629 \u0634\u062e\u0635\u064a\u0629 \u0644\u0644\u0623\u0633\u062a\u0627\u0630 \u0644\u0627 \u0642\u064a\u0645\u0629 \u0644\u0647\u0627 \u0625\u062f\u0627\u0631\u064a\u0627\u064b.","\u0648\u062b\u064a\u0642\u0629 \u064a\u064f\u0645\u0633\u0643\u0647\u0627 \u0639\u0633\u0633 \u0627\u0644\u0645\u0624\u0633\u0633\u0629.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aY0=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u062a\u0639\u062a\u0628\u0631 \u0648\u062b\u064a\u0642\u0629 "\u0633\u062c\u0644 \u0627\u0644\u062d\u0636\u0648\u0631 \u0648\u0627\u0644\u063a\u064a\u0627\u0628" \u0628\u0627\u0644\u0641\u0635\u0644 \u0627\u0644\u062f\u0631\u0627\u0633\u064a:',B.Yo,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0648\u062b\u064a\u0642\u0629 \u0625\u062f\u0627\u0631\u064a\u0629 \u0648\u0642\u0627\u0646\u0648\u0646\u064a\u0629 \u0625\u0644\u0632\u0627\u0645\u064a\u0629 \u064a\u062a\u062d\u0645\u0644 \u0627\u0644\u0645\u062f\u0631\u0633 \u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u062a\u062d\u064a\u064a\u0646\u0647\u0627 \u0644\u0644\u0631\u062c\u0648\u0639 \u0625\u0644\u064a\u0647\u0627 \u0639\u0646\u062f \u0627\u0644\u062d\u0648\u0627\u062f\u062b \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629.",u.e)
B.adx=s(["\u0627\u0644\u062a\u062e\u0635\u0635 \u0627\u0644\u0635\u0627\u0631\u0645.","\u0627\u0644\u062a\u062f\u0627\u062e\u0644 \u0648\u0627\u0644\u062a\u0642\u0627\u0637\u0639 \u0628\u064a\u0646 \u0627\u0644\u0645\u0648\u0627\u062f (Interdisciplinarit\xe9).","\u0627\u0644\u0641\u0635\u0644 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aKa=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0645\u0628\u062f\u0623 \u0627\u0644\u062a\u0631\u0628\u0648\u064a \u0627\u0644\u0630\u064a \u064a\u0642\u0636\u064a \u0628\u0627\u0644\u0631\u0628\u0637 \u0628\u064a\u0646 \u062a\u0639\u0644\u0645\u0627\u062a \u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u0645\u062e\u062a\u0644\u0641\u0629 \u0648\u0627\u0644\u0645 \u062a\u0642\u0627\u0637\u0639 \u0628\u064a\u0646\u0647\u0627 \u064a\u064f\u0639\u0631\u0641 \u0628\u0640:",B.adx,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062a\u062f\u0627\u062e\u0644 \u0648\u0627\u0644\u062a\u0642\u0627\u0637\u0639 \u0628\u064a\u0646 \u0627\u0644\u0645\u0648\u0627\u062f (Interdisciplinarit\xe9).",u.e)
B.atn=s(["\u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u062d\u0635\u0631\u064a \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0645\u0639\u0631\u0641\u064a \u0627\u0644\u0635\u0645 \u0641\u0642\u0637.","\u062a\u0646\u0645\u064a\u0629 \u0634\u062e\u0635\u064a\u0629 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0645\u0646 \u0645\u062e\u062a\u0644\u0641 \u0627\u0644\u062c\u0648\u0627\u0646\u0628 \u0627\u0644\u0641\u0643\u0631\u064a\u0629\u060c \u0627\u0644\u0648\u062c\u062f\u0627\u0646\u064a\u0629\u060c \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629\u060c \u0648\u0627\u0644\u0645\u0647\u0627\u0631\u064a\u0629 \u0639\u0628\u0631 \u0623\u0646\u0634\u0637\u0629 \u0645\u0648\u0627\u0632\u064a\u0629.","\u062a\u0646\u0638\u064a\u0645 \u0645\u0633\u0627\u0628\u0642\u0627\u062a \u0628\u064a\u0646 \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0646.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aVI=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u062a\u0633\u062a\u0647\u062f\u0641 \u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062d\u064a\u0627\u0629 \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629 \u0628\u0627\u0644\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629:",B.atn,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0646\u0645\u064a\u0629 \u0634\u062e\u0635\u064a\u0629 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0645\u0646 \u0645\u062e\u062a\u0644\u0641 \u0627\u0644\u062c\u0648\u0627\u0646\u0628 \u0627\u0644\u0641\u0643\u0631\u064a\u0629\u060c \u0627\u0644\u0648\u062c\u062f\u0627\u0646\u064a\u0629\u060c \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629\u060c \u0648\u0627\u0644\u0645\u0647\u0627\u0631\u064a\u0629 \u0639\u0628\u0631 \u0623\u0646\u0634\u0637\u0629 \u0645\u0648\u0627\u0632\u064a\u0629.",u.e)
B.Ye=s(["\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u064a\u0648\u0645 \u0627\u0644\u062f\u0631\u0627\u0633\u064a \u0627\u0644\u0648\u0627\u062d\u062f\u0629.","\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u062f\u0648\u0631\u064a \u0623\u0648 \u0627\u0644\u0645\u062c\u0627\u0644/\u0627\u0644\u0648\u062d\u062f\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629.","\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u0645\u0647\u0646\u064a \u0644\u0645\u062f\u0629 \u0639\u0634\u0631 \u0633\u0646\u0648\u0627\u062a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aLq=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0645\u062f\u0649 \u0627\u0644\u0645\u062a\u0648\u0633\u0637 \u0641\u064a \u0639\u0645\u0644 \u0627\u0644\u0645\u062f\u0631\u0633 \u064a\u0634\u0645\u0644:",B.Ye,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u062f\u0648\u0631\u064a \u0623\u0648 \u0627\u0644\u0645\u062c\u0627\u0644/\u0627\u0644\u0648\u062d\u062f\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629.",u.e)
B.ahV=s(["\u0643\u062a\u0627\u0628\u0629 \u0645\u0644\u062e\u0635 \u0645\u0639\u0642\u062f \u0641\u064a \u0627\u0644\u0625\u0645\u0644\u0627\u0621.","\u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0627\u0644\u0641\u0639\u0627\u0644\u060c \u0627\u0644\u0641\u0647\u0645\u060c \u0648\u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0627\u0644\u0633\u0644\u064a\u0645 \u0648\u0627\u0644\u0645\u0634\u0627\u0641\u0647\u0629 \u0648\u0625\u0628\u062f\u0627\u0621 \u0627\u0644\u0631\u0623\u064a.","\u062d\u0641\u0638 \u0627\u0644\u0625\u0639\u0631\u0627\u0628 \u0648\u062a\u0637\u0628\u064a\u0642\u0647 \u0643\u062a\u0627\u0628\u064a\u0627\u064b.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b7V=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0645\u0646 \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0634\u0641\u0647\u064a\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u0647\u062f\u0641\u0629 \u0641\u064a \u0645\u0643\u0648\u0646 \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0634\u0641\u0647\u064a \u0628\u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a:",B.ahV,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0627\u0644\u0641\u0639\u0627\u0644\u060c \u0627\u0644\u0641\u0647\u0645\u060c \u0648\u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0627\u0644\u0633\u0644\u064a\u0645 \u0648\u0627\u0644\u0645\u0634\u0627\u0641\u0647\u0629 \u0648\u0625\u0628\u062f\u0627\u0621 \u0627\u0644\u0631\u0623\u064a.",u.e)
B.al4=s(["\u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u062a\u064a \u062a\u064f\u0645\u0631\u0631 \u0636\u0645\u0646\u064a\u0627\u064b \u0645\u0646 \u062e\u0644\u0627\u0644 \u0627\u0644\u0646\u0635\u0648\u0635 \u062f\u0648\u0646 \u062a\u0633\u0645\u064a\u0629 \u0627\u0644\u0645\u0641\u0647\u0648\u0645.","\u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u062a\u064a \u062a\u062a\u0636\u0645\u0646 \u062a\u0633\u0645\u064a\u062a\u0647\u0627 \u0648\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u0647\u0627 \u0648\u0627\u0633\u062a\u062e\u0631\u0627\u062c \u0634\u0648\u0627\u0647\u062f\u0647\u0627 \u0648\u0625\u0639\u0631\u0627\u0628\u0647\u0627.","\u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u0634\u0641\u0647\u064a\u0629 \u063a\u064a\u0631 \u0627\u0644\u0645\u0643\u062a\u0648\u0628\u0629.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b6r=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a",'\u0627\u0644\u0645\u0642\u0635\u0648\u062f \u0628\u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 "\u0627\u0644\u0635\u0631\u064a\u062d\u0629" \u0647\u0648:',B.al4,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0627\u0644\u062a\u064a \u062a\u062a\u0636\u0645\u0646 \u062a\u0633\u0645\u064a\u062a\u0647\u0627 \u0648\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u0647\u0627 \u0648\u0627\u0633\u062a\u062e\u0631\u0627\u062c \u0634\u0648\u0627\u0647\u062f\u0647\u0627 \u0648\u0625\u0639\u0631\u0627\u0628\u0647\u0627.",u.e)
