B.aOu=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u062a\u064f\u062e\u0635\u0635 \u0627\u0644\u062d\u0635\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0645\u0646 \u0645\u0643\u0648\u0646 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u0627\u062a \u0627\u0644\u0643\u062a\u0627\u0628\u064a\u0629 \u0641\u064a \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0633\u0627\u062f\u0633 \u0644\u0640:",B.a4r,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0634\u0643\u0644 \u0648\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0646\u0635 \u0648\u0641\u0647\u0645\u0647 \u0648\u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u062c\u0632\u0626\u064a \u0639\u0644\u0649 \u0627\u0644\u0638\u0648\u0627\u0647\u0631.",u.e)
B.ab3=s(["\u0627\u0644\u0645\u0639\u064a\u0627\u0631 \u0627\u0644\u0639\u0627\u0645 \u0627\u0644\u0634\u0627\u0645\u0644.","\u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u0627\u0644\u0625\u062c\u0631\u0627\u0626\u064a\u0629 \u0627\u0644\u0645\u0644\u0645\u0648\u0633\u0629 \u0648\u0627\u0644\u0643\u0645\u064a\u0629 \u0623\u0648 \u0627\u0644\u0643\u064a\u0641\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u062f\u0644 \u0639\u0644\u0649 \u062a\u062d\u0642\u0642 \u0627\u0644\u0645\u0639\u064a\u0627\u0631.","\u062f\u0631\u062c\u0629 \u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646 \u0627\u0644\u0639\u062f\u062f\u064a.","\u0643\u0644 \u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b2p=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0645\u0624\u0634\u0631 (Indicateur) \u0641\u064a \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0643\u0641\u0627\u064a\u0627\u062a \u0647\u0648:",B.ab3,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u0627\u0644\u0625\u062c\u0631\u0627\u0626\u064a\u0629 \u0627\u0644\u0645\u0644\u0645\u0648\u0633\u0629 \u0648\u0627\u0644\u0643\u0645\u064a\u0629 \u0623\u0648 \u0627\u0644\u0643\u064a\u0641\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u062f\u0644 \u0639\u0644\u0649 \u062a\u062d\u0642\u0642 \u0627\u0644\u0645\u0639\u064a\u0627\u0631.",u.e)
