B.amz=s(["\u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0646\u062c\u0627\u062d \u0648\u062a\u0648\u0641\u064a\u0631 \u0627\u0644\u0645\u0646\u062d.","\u0627\u0644\u0623\u0646\u062f\u064a\u0629 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a\u0629.","\u0627\u0644\u0639\u0644\u0627\u0645\u0629 \u0627\u0644\u062a\u062c\u0627\u0631\u064a\u0629 \u0644\u0644\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u064a\u0629.","\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u062f\u0629 (\xc9coles pionni\xe8res) \u0627\u0644\u0645\u062c\u0647\u0632\u0629 \u0628\u0627\u0644\u062a\u0643\u0646\u0648\u0644\u0648\u062c\u064a\u0627 \u0648\u0627\u0644\u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u062d\u062f\u064a\u062b\u0629 \u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0645\u0645\u0646\u0647\u062c."],t.s)
B.aXu=new A.a("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"\u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u0645\u0631\u062c\u0639\u064a \u0627\u0644\u0630\u064a \u062c\u0644\u0628\u062a\u0647 \u062e\u0627\u0631\u0637\u0629 \u0627\u0644\u0637\u0631\u064a\u0642 \u0644\u0644\u0631\u0641\u0639 \u0645\u0646 \u062c\u0627\u0630\u0628\u064a\u0629 \u0627\u0644\u0645\u0624\u0633\u0633\u0627\u062a \u0648\u062a\u0648\u0641\u064a\u0631 \u0638\u0631\u0648\u0641 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0645\u0646\u0627\u0633\u0628\u0629 \u0644\u0644\u0623\u0637\u0631 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629 \u0647\u0648:",B.amz,3,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u062f\u0629 (\xc9coles pionni\xe8res) \u0627\u0644\u0645\u062c\u0647\u0632\u0629 \u0628\u0627\u0644\u062a\u0643\u0646\u0648\u0644\u0648\u062c\u064a\u0627 \u0648\u0627\u0644\u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u062d\u062f\u064a\u062b\u0629 \u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0645\u0645\u0646\u0647\u062c.",u.e)
B.a4q=s(["\u0627\u0644\u062a\u0646\u0627\u0648\u0644 \u0648\u0627\u0644\u062a\u0639\u062f\u062f \u0627\u0644\u0644\u063a\u0648\u064a \u0648\u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0623\u0645 \u0641\u0642\u0637 \u0641\u064a \u0627\u0644\u062a\u062f\u0631\u064a\u0633.","\u0625\u0639\u0645\u0627\u0644 \u0627\u0644\u062a\u0639\u062f\u062f\u064a\u0629 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0628\u0627\u0644\u062a\u062f\u0631\u062c \u0648\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0627\u0644\u0644\u063a\u0648\u064a \u0644\u062a\u0646\u0648\u064a\u0639 \u0644\u063a\u0627\u062a \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0648\u0627\u0644\u062a\u0642\u0646\u064a\u0629.","\u0625\u0644\u063a\u0627\u0621 \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0644\u063a\u0627\u062a \u0627\u0644\u0623\u062c\u0646\u0628\u064a\u0629 \u0641\u064a \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a.","\u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629 \u0643\u0644\u063a\u0629 \u062a\u062f\u0631\u064a\u0633 \u062d\u0635\u0631\u064a\u0629 \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u0648\u0627\u062f."],t.s)
B.aUq=new A.a("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"\u064a\u0646\u0635 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0625\u0637\u0627\u0631 51.17 \u0639\u0644\u0649 \u0623\u0646 \u0647\u0646\u062f\u0633\u0629 \u0627\u0644\u0644\u063a\u0627\u062a \u062a\u0639\u062a\u0645\u062f \u0623\u0633\u0627\u0633\u0627\u064b \u0639\u0644\u0649:",B.a4q,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0625\u0639\u0645\u0627\u0644 \u0627\u0644\u062a\u0639\u062f\u062f\u064a\u0629 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0628\u0627\u0644\u062a\u062f\u0631\u062c \u0648\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0627\u0644\u0644\u063a\u0648\u064a \u0644\u062a\u0646\u0648\u064a\u0639 \u0644\u063a\u0627\u062a \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0648\u0627\u0644\u062a\u0642\u0646\u064a\u0629.",u.e)
B.ajx=s(["\u062a\u062f\u0631\u064a\u0633 \u0623\u0633\u0628\u0648\u0639 \u0628\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0648\u0623\u0633\u0628\u0648\u0639 \u0628\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0641\u0631\u0646\u0633\u064a\u0629.","\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062e\u064a\u0627\u0631 \u0627\u0644\u0644\u063a\u0648\u064a \u0627\u0644\u0645\u0632\u062f\u0648\u062c \u0644\u062a\u062f\u0631\u064a\u0633 \u0628\u0639\u0636 \u0627\u0644\u0645\u0648\u0627\u062f \u0623\u0648 \u0628\u0639\u0636 \u0627\u0644\u0645\u0636\u0627\u0645\u064a\u0646 \u0627\u0644\u0645\u062c\u0627\u0644\u0627\u062a (\u0645\u062b\u0644 \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0648\u0627\u0644\u062a\u0642\u0646\u064a\u0629) \u0628\u0644\u063a\u0627\u062a \u0623\u062c\u0646\u0628\u064a\u0629.","\u062a\u0631\u062c\u0645\u0629 \u0643\u0644 \u0643\u0644\u0645\u0629 \u064a\u0644\u0642\u064a\u0647\u0627 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0641\u0648\u0631\u064a\u0627\u064b \u0644\u0644\u063a\u0629 \u062b\u0627\u0646\u064a\u0629.","\u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0644\u063a\u0627\u062a \u0641\u064a \u0627\u0644\u0641\u062a\u0631\u0629 \u0627\u0644\u0645\u0633\u0627\u0626\u064a\u0629 \u0641\u0642\u0637."],t.s)
B.b_o=new A.a("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'\u0622\u0644\u064a\u0629 "\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0627\u0644\u0644\u063a\u0648\u064a" (Alternance linguistique) \u062a\u0646\u0635 \u0639\u0644\u0649:',B.ajx,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062e\u064a\u0627\u0631 \u0627\u0644\u0644\u063a\u0648\u064a \u0627\u0644\u0645\u0632\u062f\u0648\u062c \u0644\u062a\u062f\u0631\u064a\u0633 \u0628\u0639\u0636 \u0627\u0644\u0645\u0648\u0627\u062f \u0623\u0648 \u0628\u0639\u0636 \u0627\u0644\u0645\u0636\u0627\u0645\u064a\u0646 \u0627\u0644\u0645\u062c\u0627\u0644\u0627\u062a (\u0645\u062b\u0644 \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0648\u0627\u0644\u062a\u0642\u0646\u064a\u0629) \u0628\u0644\u063a\u0627\u062a \u0623\u062c\u0646\u0628\u064a\u0629.",u.e)
B.arZ=s(["\u0639\u062f\u062f \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0646 \u0641\u064a \u0643\u0644 \u0645\u0624\u0633\u0633\u0629.","\u0627\u0644\u0647\u062f\u0631 \u0627\u0644\u0645\u062f\u0631\u0633\u064a \u0648\u0627\u0644\u0627\u0646\u0642\u0637\u0627\u0639 \u0639\u0646 \u0627\u0644\u062f\u0631\u0627\u0633\u0629 \u0628\u0646\u0633\u0628\u0629 \u0627\u0644\u062b\u0644\u062b.","\u0627\u0644\u063a\u0644\u0627\u0641 \u0627\u0644\u0632\u0645\u0646\u064a \u0644\u0644\u0645\u0648\u0627\u062f \u0627\u0644\u0639\u0644\u0645\u064a\u0629.","\u0639\u062f\u062f \u0627\u0644\u0645\u0641\u062a\u0634\u064a\u0646 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u064a\u0646."],t.s)
