B.XJ=s(["\u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0641\u0639\u0644\u064a\u0629 \u0644\u0644\u0648\u0638\u064a\u0641\u0629 \u0623\u0648 \u062e\u0644\u0627\u0644 \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u0630\u0647\u0627\u0628 \u0648\u0627\u0644\u0625\u064a\u0627\u0628 \u0627\u0644\u0627\u0639\u062a\u064a\u0627\u062f\u064a \u0628\u064a\u0646 \u0645\u0642\u0631 \u0627\u0644\u0639\u0645\u0644 \u0648\u0627\u0644\u0633\u0643\u0646.","\u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0639\u0637\u0644\u0629 \u0627\u0644\u0635\u064a\u0641\u064a\u0629 \u062e\u0627\u0631\u062c \u0627\u0644\u062a\u0631\u0627\u0628 \u0627\u0644\u0648\u0637\u0646\u064a \u0641\u064a \u0631\u062d\u0644\u0629 \u0634\u062e\u0635\u064a\u0629.","\u0641\u064a \u0623\u064a \u0648\u0642\u062a \u0648\u0645\u0643\u0627\u0646 \u0628\u063a\u0636 \u0627\u0644\u0646\u0638\u0631 \u0639\u0646 \u0627\u0644\u0639\u0644\u0627\u0642\u0629 \u0628\u0627\u0644\u0639\u0645\u0644.","\u0641\u0642\u0637 \u0625\u0630\u0627 \u0648\u0642\u0639\u062a \u062f\u0627\u062e\u0644 \u062d\u062c\u0631\u0629 \u0627\u0644\u0641\u0635\u0644 \u062d\u0635\u0631\u0627\u064b."],t.s)
B.aX1=new A.a("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'\u0623\u0633\u0628\u0627\u0628 \u062d\u0627\u062f\u062b\u0629 \u0627\u0644\u0634\u063a\u0644 \u0623\u0648 "\u062d\u0627\u062f\u062b\u0629 \u0627\u0644\u062e\u062f\u0645\u0629" \u0644\u0644\u0623\u0633\u062a\u0627\u0630 \u062a\u0639\u062a\u0628\u0631 \u0643\u0630\u0644\u0643 \u0625\u0630\u0627 \u0648\u0642\u0639\u062a:',B.XJ,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0641\u0639\u0644\u064a\u0629 \u0644\u0644\u0648\u0638\u064a\u0641\u0629 \u0623\u0648 \u062e\u0644\u0627\u0644 \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u0630\u0647\u0627\u0628 \u0648\u0627\u0644\u0625\u064a\u0627\u0628 \u0627\u0644\u0627\u0639\u062a\u064a\u0627\u062f\u064a \u0628\u064a\u0646 \u0645\u0642\u0631 \u0627\u0644\u0639\u0645\u0644 \u0648\u0627\u0644\u0633\u0643\u0646.",u.e)
B.a3X=s(["\u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0627\u0644\u062a\u062d\u0641\u0638 \u0648\u0643\u062a\u0645\u0627\u0646 \u0643\u0644 \u0627\u0644\u0645\u0639\u0637\u064a\u0627\u062a \u0648\u0627\u0644\u0648\u062b\u0627\u0626\u0642 \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0623\u0648 \u0627\u0644\u0625\u062f\u0627\u0631\u064a\u0629 \u0627\u0644\u062a\u064a \u064a\u0637\u0644\u0639 \u0639\u0644\u064a\u0647\u0627 \u0628\u062d\u0643\u0645 \u0639\u0645\u0644\u0647.","\u062d\u064a\u0629 \u0643\u0634\u0641 \u0643\u0644 \u0633\u0631 \u0644\u0644\u0631\u0623\u064a \u0627\u0644\u0639\u0627\u0645 \u0639\u0628\u0631 \u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a.","\u0627\u0644\u0627\u0642\u062a\u0635\u0627\u0631 \u0639\u0644\u0649 \u062d\u0645\u0627\u064a\u0629 \u0645\u0639\u0637\u064a\u0627\u062a \u0627\u0644\u0645\u062f\u064a\u0631 \u0641\u0642\u0637.","\u0625\u0641\u0634\u0627\u0621 \u0627\u0644\u0645\u0639\u0637\u064a\u0627\u062a \u0628\u0639\u062f \u0627\u0644\u062a\u0642\u0627\u0639\u062f \u0645\u0628\u0627\u0634\u0631\u0629."],t.s)
B.b_0=new A.a("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'\u064a\u0642\u0639 \u0627\u0644\u0639\u0628\u0621 \u0648\u0627\u0644\u0623\u062b\u0631 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a \u0644\u0640 "\u0627\u0644\u0633\u0631 \u0627\u0644\u0645\u0647\u0646\u064a" \u0639\u0644\u0649 \u0645\u0648\u0638\u0641\u064a \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0648\u0637\u0646\u064a\u0629 \u0648\u0641\u0642 \u0645\u0628\u062f\u0623:',B.a3X,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0627\u0644\u062a\u062d\u0641\u0638 \u0648\u0643\u062a\u0645\u0627\u0646 \u0643\u0644 \u0627\u0644\u0645\u0639\u0637\u064a\u0627\u062a \u0648\u0627\u0644\u0648\u062b\u0627\u0626\u0642 \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0623\u0648 \u0627\u0644\u0625\u062f\u0627\u0631\u064a\u0629 \u0627\u0644\u062a\u064a \u064a\u0637\u0644\u0639 \u0639\u0644\u064a\u0647\u0627 \u0628\u062d\u0643\u0645 \u0639\u0645\u0644\u0647.",u.e)
B.ax5=s(["\u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0643\u0643\u0644 \u0645\u0646\u0627\u0642\u0634\u0629 \u0627\u0644\u062c\u0648\u0627\u0646\u0628 \u0627\u0644\u0645\u0627\u0644\u064a\u0629.","\u0643\u0644 \u0645\u0627\u062f\u0629 \u062f\u0631\u0627\u0633\u064a\u0629 \u0623\u0648 \u0623\u0642\u0637\u0627\u0628 \u0627\u0644\u0645\u0648\u0627\u062f \u0644\u0645\u0646\u0627\u0642\u0634\u0629 \u0623\u0633\u0627\u0644\u064a\u0628 \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0648\u0627\u0644\u0628\u0631\u0627\u0645\u062c \u0648\u0627\u0644\u062a\u0646\u0633\u064a\u0642 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a.","\u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0627\u0644\u062c\u062f\u062f \u0641\u064a \u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0633\u0646\u0629.","\u062a\u0646\u0638\u064a\u0645 \u0627\u0644\u0631\u062d\u0644\u0627\u062a \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629 \u0648\u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0631\u0641\u064a\u0647\u064a\u0629 \u0641\u0642\u0637."],t.s)
