B.aco=s(["\u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u062e\u0627\u0635 \u0644\u062c\u0645\u0639\u064a\u0629 \u062f\u0639\u0645 \u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0646\u062c\u0627\u062d \u0648\u0627\u0644\u062c\u0645\u0639\u064a\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0629 \u0648\u0627\u0644\u0645\u0643\u062a\u0628 \u0627\u0644\u062a\u0646\u0641\u064a\u0630\u064a \u0627\u0644\u0645\u0639\u0646\u064a.","\u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0634\u062e\u0635\u064a \u0644\u0644\u0623\u0633\u062a\u0627\u0630.","\u0627\u0644\u062c\u0645\u0627\u0639\u0629 \u0627\u0644\u062a\u0631\u0627\u0628\u064a\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629.","\u0646\u0642\u0627\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u064a\u0645."],t.s)
B.aH2=new A.a("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"\u0627\u0644\u0631\u0633\u0648\u0645 \u0648\u0627\u0644\u0627\u0633\u062a\u062d\u0642\u0627\u0642\u0627\u062a \u0627\u0644\u0645\u0633\u062f\u062f\u0629 \u0639\u0646\u062f \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0641\u064a \u0627\u0644\u0623\u0646\u062f\u064a\u0629 \u0648\u0627\u0644\u062c\u0645\u0639\u064a\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0629 \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629 \u0648\u062a\u0623\u0645\u064a\u0646\u0647\u0645 \u062a\u064f\u0635\u0631\u0641 \u062a\u062d\u062a \u0625\u0634\u0631\u0627\u0641:",B.aco,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u062e\u0627\u0635 \u0644\u062c\u0645\u0639\u064a\u0629 \u062f\u0639\u0645 \u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0646\u062c\u0627\u062d \u0648\u0627\u0644\u062c\u0645\u0639\u064a\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0629 \u0648\u0627\u0644\u0645\u0643\u062a\u0628 \u0627\u0644\u062a\u0646\u0641\u064a\u0630\u064a \u0627\u0644\u0645\u0639\u0646\u064a.",u.e)
B.as0=s(["\u0623\u062f\u0627\u0621 \u0627\u0644\u0645\u0647\u0627\u0645 \u0628\u0627\u0644\u0646\u0632\u0627\u0647\u0629 \u0648\u0627\u0644\u062a\u062d\u0644\u064a \u0628\u0627\u0644\u062d\u064a\u0627\u062f\u060c \u0648\u0627\u062d\u062a\u0631\u0627\u0645 \u0627\u0644\u0631\u0624\u0633\u0627\u0621 \u0648\u0627\u0644\u0645\u0631\u0624\u0648\u0633\u064a\u0646 \u0648\u0627\u0644\u0627\u0645\u062a\u0646\u0627\u0639 \u0639\u0646 \u0627\u0644\u0645\u0635\u0627\u0644\u062d \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0627\u0644\u0645\u062a\u0639\u0627\u0631\u0636\u0629.","\u0625\u0645\u0643\u0627\u0646\u064a\u0629 \u0627\u0644\u0627\u0645\u062a\u0646\u0627\u0639 \u0639\u0646 \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0641\u064a \u062d\u0627\u0644\u0629 \u0639\u062f\u0645 \u0627\u0644\u0631\u063a\u0628\u0629.","\u062a\u0646\u0641\u064a\u0630 \u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0648\u0627\u0645\u0631 \u0627\u0644\u0634\u0641\u0647\u064a\u0629 \u062d\u062a\u0649 \u0644\u0648 \u0643\u0627\u0646\u062a \u0645\u062e\u0627\u0644\u0641\u0629 \u0644\u0644\u0642\u0627\u0646\u0648\u0646 \u0628\u0634\u0643\u0644 \u0635\u0627\u0631\u062e.","\u062d\u0631\u064a\u0629 \u0627\u0644\u062a\u0635\u0631\u0641 \u0627\u0644\u062a\u0627\u0645 \u0641\u064a \u0627\u0644\u0645\u0646\u0627\u0647\u062c \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629 \u062d\u0633\u0628 \u0627\u0644\u0631\u0623\u064a \u0627\u0644\u0634\u062e\u0635\u064a."],t.s)
B.b1g=new A.a("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'\u064a\u064f\u0642\u0635\u062f \u0628\u0627\u0644\u062d\u062b \u0627\u0644\u0625\u062f\u0627\u0631\u064a \u0639\u0644\u0649 "\u0627\u0644\u062a\u0636\u0627\u0645\u0646 \u0648\u0627\u0644\u0648\u0627\u062c\u0628 \u0627\u0644\u0645\u0647\u0646\u064a":',B.as0,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0623\u062f\u0627\u0621 \u0627\u0644\u0645\u0647\u0627\u0645 \u0628\u0627\u0644\u0646\u0632\u0627\u0647\u0629 \u0648\u0627\u0644\u062a\u062d\u0644\u064a \u0628\u0627\u0644\u062d\u064a\u0627\u062f\u060c \u0648\u0627\u062d\u062a\u0631\u0627\u0645 \u0627\u0644\u0631\u0624\u0633\u0627\u0621 \u0648\u0627\u0644\u0645\u0631\u0624\u0648\u0633\u064a\u0646 \u0648\u0627\u0644\u0627\u0645\u062a\u0646\u0627\u0639 \u0639\u0646 \u0627\u0644\u0645\u0635\u0627\u0644\u062d \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0627\u0644\u0645\u062a\u0639\u0627\u0631\u0636\u0629.",u.e)
B.aix=s(["\u0627\u0644\u0646\u0638\u0631 \u0641\u064a \u0646\u062a\u0627\u0626\u062c \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0648\u062a\u062a\u0628\u0639 \u0645\u0633\u0627\u0631\u0647\u0645 \u0627\u0644\u062f\u0631\u0627\u0633\u064a \u0648\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u062a\u062d\u0635\u064a\u0644 \u0644\u0627\u062a\u062e\u0627\u0630 \u0642\u0631\u0627\u0631\u0627\u062a \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0623\u0648 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","\u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0639\u0644\u0649 \u0635\u0641\u0642\u0627\u062a \u0627\u0644\u0628\u0646\u0627\u0621 \u0628\u0627\u0644\u0645\u062f\u0627\u0631\u0633.","\u062a\u062d\u062f\u064a\u062f \u0631\u0648\u0627\u062a\u0628 \u0627\u0644\u0623\u0633\u0627\u062a\u0630\u0629 \u0648\u062a\u062b\u0628\u064a\u062a\u0647\u0645.","\u062a\u0639\u064a\u064a\u0646 \u0627\u0644\u0623\u0633\u0627\u062a\u0630\u0629 \u0641\u064a \u0627\u0644\u0641\u0635\u0648\u0644."],t.s)
B.aNd=new A.a("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"\u0645\u062c\u0627\u0644\u0633 \u0627\u0644\u0623\u0642\u0633\u0627\u0645 \u0641\u064a \u0627\u0644\u0633\u0644\u0643 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a \u062a\u062a\u0648\u0644\u0649 \u0645\u0647\u0645\u0629:",B.aix,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0646\u0638\u0631 \u0641\u064a \u0646\u062a\u0627\u0626\u062c \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0648\u062a\u062a\u0628\u0639 \u0645\u0633\u0627\u0631\u0647\u0645 \u0627\u0644\u062f\u0631\u0627\u0633\u064a \u0648\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u062a\u062d\u0635\u064a\u0644 \u0644\u0627\u062a\u062e\u0627\u0630 \u0642\u0631\u0627\u0631\u0627\u062a \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0623\u0648 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.",u.e)
B.aqC=s(["\u0627\u0644\u0627\u0645\u062a\u0646\u0627\u0639 \u0639\u0646 \u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0627\u0644\u0634\u0641\u0647\u064a \u062f\u0627\u062e\u0644 \u0627\u0644\u0641\u0635\u0644.","\u0645\u0645\u0627\u0631\u0633\u0629 \u062d\u0631\u064a\u0629 \u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0628\u0623\u0633\u0644\u0648\u0628 \u0645\u062a\u0632\u0646 \u0648\u0639\u062f\u0645 \u0627\u0644\u0625\u0633\u0627\u0621\u0629 \u0644\u0643\u0631\u0627\u0645\u0629 \u0627\u0644\u0648\u0638\u064a\u0641\u0629 \u0623\u0648 \u0625\u0641\u0634\u0627\u0621 \u0623\u0633\u0631\u0627\u0631 \u0627\u0644\u0625\u062f\u0627\u0631\u0629 \u0641\u064a \u0627\u0644\u0623\u0645\u0627\u0643\u0646 \u0627\u0644\u0639\u0627\u0645\u0629 \u0648\u0627\u0644\u0648\u0633\u0627\u0626\u0637.","\u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0627\u0644\u062f\u0641\u0627\u062a\u0631 \u0648\u0627\u0644\u0643\u062a\u0628 \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629 \u0641\u064a \u0627\u0644\u0645\u0646\u0632\u0644.","\u0639\u062f\u0645 \u062d\u0636\u0648\u0631 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u0627\u062a \u0627\u0644\u0625\u062f\u0627\u0631\u064a\u0629."],t.s)
B.aIk=new A.a("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'\u0627\u0644\u0648\u0627\u062c\u0628 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a \u0648\u0627\u0644\u0623\u062e\u0644\u0627\u0642\u064a \u0627\u0644\u0645\u0633\u0645\u0649 "\u0627\u0644\u0648\u0627\u062c\u0628 \u0628\u0627\u0644\u062a\u062d\u0641\u0638" \u0627\u0644\u0645\u0644\u0642\u0649 \u0639\u0644\u0649 \u0639\u0627\u062a\u0642 \u0627\u0644\u0645\u0648\u0638\u0641 \u064a\u0639\u0646\u064a:',B.aqC,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0645\u0645\u0627\u0631\u0633\u0629 \u062d\u0631\u064a\u0629 \u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0628\u0623\u0633\u0644\u0648\u0628 \u0645\u062a\u0632\u0646 \u0648\u0639\u062f\u0645 \u0627\u0644\u0625\u0633\u0627\u0621\u0629 \u0644\u0643\u0631\u0627\u0645\u0629 \u0627\u0644\u0648\u0638\u064a\u0641\u0629 \u0623\u0648 \u0625\u0641\u0634\u0627\u0621 \u0623\u0633\u0631\u0627\u0631 \u0627\u0644\u0625\u062f\u0627\u0631\u0629 \u0641\u064a \u0627\u0644\u0623\u0645\u0627\u0643\u0646 \u0627\u0644\u0639\u0627\u0645\u0629 \u0648\u0627\u0644\u0648\u0633\u0627\u0626\u0637.",u.e)
B.a3h=s(["\u0623\u0642\u062f\u0645 \u0623\u0633\u062a\u0627\u0630 \u0628\u0627\u0644\u0645\u0624\u0633\u0633\u0629.","\u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0628\u0635\u0641\u062a\u0647 \u0631\u0626\u064a\u0633\u0627\u064b \u0644\u0644\u0645\u0643\u062a\u0628 \u0628\u0635\u0641\u0629 \u062a\u0644\u0642\u0627\u0626\u064a\u0629 \u0642\u0627\u0646\u0648\u0646\u064a\u0629.","\u0631\u0626\u064a\u0633 \u062c\u0645\u0639\u064a\u0629 \u0627\u0644\u0622\u0628\u0627\u0621.","\u0631\u0626\u064a\u0633 \u0627\u0644\u062c\u0645\u0627\u0639\u0629 \u0627\u0644\u0645\u062d\u0644\u064a\u0629"],t.s)
B.aEu=new A.a("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'\u0644\u062a\u0623\u0633\u064a\u0633 "\u062c\u0645\u0639\u064a\u0629 \u062f\u0639\u0645 \u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0646\u062c\u0627\u062d" (GSES) \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629\u060c \u064a\u062a\u0634\u0643\u0644 \u0645\u0643\u062a\u0628\u0647\u0627 \u0627\u0644\u0645\u0633\u064a\u0631 \u0628\u0631\u0626\u0627\u0633\u0629:',B.a3h,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0645\u062f\u064a\u0631 \u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0628\u0635\u0641\u062a\u0647 \u0631\u0626\u064a\u0633\u0627\u064b \u0644\u0644\u0645\u0643\u062a\u0628 \u0628\u0635\u0641\u0629 \u062a\u0644\u0642\u0627\u0626\u064a\u0629 \u0642\u0627\u0646\u0648\u0646\u064a\u0629.",u.e)
