B.auR=s(["\u0635\u064a\u0627\u063a\u0629 \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0627\u0644\u0625\u062f\u0627\u0631\u064a \u0627\u0644\u064a\u0648\u0645\u064a.","\u0627\u0644\u0634\u0631\u062d \u0648\u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0627\u0644\u0635\u0631\u064a\u062d \u0639\u0646 \u062e\u0637\u0629 \u0627\u0644\u062d\u0644 \u0627\u0644\u062a\u064a \u062a\u0648\u0635\u0644 \u0625\u0644\u064a\u0647\u0627 \u0644\u0632\u0645\u0644\u0627\u0626\u0647 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0631\u0645\u0648\u0632 \u0648\u0644\u063a\u0629 \u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a\u0629.","\u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0627\u0644\u0634\u0627\u0645\u0644 \u0644\u0634\u0631\u062d \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0648\u0645\u0633\u0637\u0631\u0629 \u0627\u0644\u062d\u0644 \u0639\u0644\u0649 \u0627\u0644\u0633\u0628\u0648\u0631\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b7O=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u0645\u0631\u062d\u0644\u0629 "\u0627\u0644\u0635\u064a\u0627\u063a\u0629" ( Situation  de  formulation ) \u0641\u064a \u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0648\u0636\u0639\u064a\u0627\u062a \u062a\u062a\u0637\u0644\u0628 \u0645\u0646 \u0627\u0644\u0645\u062a\u0639\u0644\u0645:',B.auR,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0634\u0631\u062d \u0648\u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0627\u0644\u0635\u0631\u064a\u062d \u0639\u0646 \u062e\u0637\u0629 \u0627\u0644\u062d\u0644 \u0627\u0644\u062a\u064a \u062a\u0648\u0635\u0644 \u0625\u0644\u064a\u0647\u0627 \u0644\u0632\u0645\u0644\u0627\u0626\u0647 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0631\u0645\u0648\u0632 \u0648\u0644\u063a\u0629 \u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a\u0629.",u.e)
B.a1g=s(["\u062d\u0641\u0638 \u0627\u0644\u062a\u0639\u0627\u0631\u064a\u0641 \u0627\u0644\u0631\u0633\u0645\u064a\u0629 \u0627\u0644\u0645\u0643\u062a\u0648\u0628\u0629 \u0641\u064a \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0645\u062f\u0631\u0633.","\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646 \u0648\u0627\u0644\u062d\u062c\u062c \u0627\u0644\u0645\u0646\u0637\u0642\u064a\u0629 \u0644\u0625\u062b\u0628\u0627\u062a \u0635\u062d\u0629 \u0646\u062a\u0627\u0626\u062c\u0647 \u0623\u0648 \u0625\u0642\u0646\u0627\u0639 \u0623\u0642\u0631\u0627\u0646\u0647 \u0628\u062c\u062f\u0648\u0649 \u0637\u0631\u064a\u0642\u062a\u0647.","\u0646\u0642\u0644 \u0627\u0644\u062d\u0644\u0648\u0644 \u0627\u0644\u0645\u0643\u062a\u0648\u0628\u0629 \u0645\u0646 \u062f\u0641\u062a\u0631 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0645\u0628\u0627\u0634\u0631\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b0d=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u0641\u064a \u0648\u0636\u0639\u064a\u0629 "\u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629" ( Situation  de  validation )\u060c \u064a\u0643\u0648\u0646 \u0627\u0644\u062f\u0648\u0631 \u0627\u0644\u0623\u0633\u0627\u0633\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0647\u0648:',B.a1g,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0628\u0631\u0627\u0647\u064a\u0646 \u0648\u0627\u0644\u062d\u062c\u062c \u0627\u0644\u0645\u0646\u0637\u0642\u064a\u0629 \u0644\u0625\u062b\u0628\u0627\u062a \u0635\u062d\u0629 \u0646\u062a\u0627\u0626\u062c\u0647 \u0623\u0648 \u0625\u0642\u0646\u0627\u0639 \u0623\u0642\u0631\u0627\u0646\u0647 \u0628\u062c\u062f\u0648\u0649 \u0637\u0631\u064a\u0642\u062a\u0647.",u.e)
B.avk=s(["\u062a\u0631\u0643 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u064a\u0642\u0631\u0631\u0648\u0646 \u0627\u0644\u062a\u0639\u0627\u0631\u064a\u0641 \u0627\u0644\u0631\u0633\u0645\u064a\u0629 \u062f\u0648\u0646 \u062a\u062f\u062e\u0644 \u0627\u0644\u0623\u0633\u062a\u0627\u0630.","\u062a\u062f\u062e\u0644 \u0627\u0644\u0645\u062f\u0631\u0633 \u0644\u0625\u0636\u0641\u0627\u0621 \u0627\u0644\u0635\u0628\u063a\u0629 \u0627\u0644\u0631\u0633\u0645\u064a\u0629 \u0648\u0627\u0644\u0645\u0648\u0636\u0648\u0639\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u062c\u062f\u064a\u062f \u0648\u0636\u0628\u0637 \u0627\u0644\u0645\u0635\u0637\u0644\u062d\u0627\u062a \u0648\u0627\u0644\u0631\u0645\u0648\u0632.","\u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u0631\u0648\u0627\u0626\u0632 \u0648\u0627\u0644\u0623\u0644\u0648\u0627\u062d \u0644\u0625\u062c\u0631\u0627\u0621 \u0627\u0644\u062d\u0633\u0627\u0628 \u0627\u0644\u0630\u0647\u0646\u064a.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aSu=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u0645\u0631\u062d\u0644\u0629 "\u0627\u0644\u0645\u0623\u0633\u0633\u0629" ( Situation  d\'institutionnalisation ) \u062a\u062a\u062c\u0644\u0649 \u0628\u0627\u0644\u0623\u0633\u0627\u0633 \u0641\u064a:',B.avk,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u062f\u062e\u0644 \u0627\u0644\u0645\u062f\u0631\u0633 \u0644\u0625\u0636\u0641\u0627\u0621 \u0627\u0644\u0635\u0628\u063a\u0629 \u0627\u0644\u0631\u0633\u0645\u064a\u0629 \u0648\u0627\u0644\u0645\u0648\u0636\u0648\u0639\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u062c\u062f\u064a\u062f \u0648\u0636\u0628\u0637 \u0627\u0644\u0645\u0635\u0637\u0644\u062d\u0627\u062a \u0648\u0627\u0644\u0631\u0645\u0648\u0632.",u.e)
B.a2T=s(["\u062a\u0648\u0641\u064a\u0631 \u0628\u064a\u0626\u0629 \u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0647\u0627\u062f\u0626\u0629 \u0648\u0645\u062b\u0627\u0644\u064a\u0629 \u0644\u0644\u062a\u0644\u0627\u0645\u064a\u0630.","\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0644\u0645\u0624\u0634\u0631\u0627\u062a \u0645\u0643\u0634\u0648\u0641\u0629 \u0623\u0648 \u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u062c\u0648\u0627\u0628 \u0628\u0637\u0631\u064a\u0642\u0629 \u063a\u064a\u0631 \u0645\u0628\u0627\u0634\u0631\u0629 \u062a\u062d\u0631\u0645 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0645\u0646 \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0639\u0627\u0626\u0642.","\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0623\u0644\u0639\u0627\u0628 \u0648\u0627\u0644\u0645\u0633\u0631\u062d \u0641\u064a \u0634\u0631\u062d \u062f\u0631\u0648\u0633 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b26=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u064a\u064f\u0642\u0635\u062f \u0628\u0645\u0641\u0647\u0648\u0645 "\u0623\u062b\u0631 \u0646\u0648\u0628\u064a\u0644" (Effet Topaze) \u0641\u064a \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643:',B.a2T,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0644\u0645\u0624\u0634\u0631\u0627\u062a \u0645\u0643\u0634\u0648\u0641\u0629 \u0623\u0648 \u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u062c\u0648\u0627\u0628 \u0628\u0637\u0631\u064a\u0642\u0629 \u063a\u064a\u0631 \u0645\u0628\u0627\u0634\u0631\u0629 \u062a\u062d\u0631\u0645 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0645\u0646 \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0639\u0627\u0626\u0642.",u.e)
B.a0y=s(["\u0627\u0639\u062a\u0628\u0627\u0631 \u0633\u0644\u0648\u0643 \u0623\u0648 \u0625\u062c\u0627\u0628\u0629 \u0628\u0633\u064a\u0637\u0629 \u062c\u062f\u0627\u064b \u0648\u063a\u064a\u0631 \u0631\u064a\u0627\u0636\u064a\u0629 \u0635\u0627\u062f\u0631\u0629 \u0639\u0646 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u0628\u0645\u062b\u0627\u0628\u0629 \u0628\u0631\u0647\u0627\u0646 \u0631\u064a\u0627\u0636\u064a \u0639\u0645\u064a\u0642.","\u0627\u0644\u0639\u0642\u0627\u0628 \u0627\u0644\u0635\u0627\u0631\u0645 \u0639\u0644\u0649 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0627\u0644\u0625\u0645\u0644\u0627\u0626\u064a\u0629 \u0641\u064a \u0645\u0627\u062f\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a.","\u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0648\u0633\u0627\u0626\u0637 \u0627\u0644\u0631\u0642\u0645\u064a\u0629 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aPq=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'"\u0623\u062b\u0631 \u062c\u0648\u0631\u062f\u0627\u0646" (Effet Jourdain) \u064a\u062d\u062f\u062b \u0639\u0646\u062f\u0645\u0627 \u064a\u0642\u0648\u0645 \u0627\u0644\u0645\u062f\u0631\u0633 \u0628\u0640:',B.a0y,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0639\u062a\u0628\u0627\u0631 \u0633\u0644\u0648\u0643 \u0623\u0648 \u0625\u062c\u0627\u0628\u0629 \u0628\u0633\u064a\u0637\u0629 \u062c\u062f\u0627\u064b \u0648\u063a\u064a\u0631 \u0631\u064a\u0627\u0636\u064a\u0629 \u0635\u0627\u062f\u0631\u0629 \u0639\u0646 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u0628\u0645\u062b\u0627\u0628\u0629 \u0628\u0631\u0647\u0627\u0646 \u0631\u064a\u0627\u0636\u064a \u0639\u0645\u064a\u0642.",u.e)
B.adG=s(["\u0627\u0646\u0632\u0644\u0627\u0642 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0639\u0644\u0649 \u0627\u0644\u0633\u0628\u0648\u0631\u0629.","\u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0647\u062f\u0641 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0623\u0635\u0644\u064a \u0628\u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u0645\u0641\u0631\u0637 \u0639\u0644\u0649 \u0648\u0633\u064a\u0644\u0629 \u0645\u0633\u0627\u0639\u062f\u0629 \u062a\u062d\u0648\u0644 \u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u062b\u0627\u0646\u0648\u064a \u0625\u0644\u0649 \u0645\u0648\u0636\u0648\u0639 \u0623\u0633\u0627\u0633\u064a.","\u0627\u0646\u062a\u0642\u0627\u0644 \u0627\u0644\u0641\u0635\u0644 \u0645\u0646 \u0645\u0648\u0636\u0648\u0639 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0625\u0644\u0649 \u0645\u0648\u0636\u0648\u0639 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aZP=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u064a\u0646\u062c\u0645 "\u0627\u0644\u0627\u0646\u0632\u0644\u0627\u0642 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a" (Glissement didactique) \u0639\u0646:',B.adG,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0647\u062f\u0641 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0623\u0635\u0644\u064a \u0628\u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u0645\u0641\u0631\u0637 \u0639\u0644\u0649 \u0648\u0633\u064a\u0644\u0629 \u0645\u0633\u0627\u0639\u062f\u0629 \u062a\u062d\u0648\u0644 \u0627\u0644\u0647\u062f\u0641 \u0627\u0644\u062b\u0627\u0646\u0648\u064a \u0625\u0644\u0649 \u0645\u0648\u0636\u0648\u0639 \u0623\u0633\u0627\u0633\u064a.",u.e)
B.ay9=s(["\u062a\u0644\u0641 \u0648\u0633\u0627\u0626\u0644 \u0648\u0645\u0639\u062f\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0628\u0627\u0644\u0645\u0624\u0633\u0633\u0629 \u0644\u0644\u0642\u062f\u0645.","\u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0644\u0646\u0641\u0633 \u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0628\u0646\u0641\u0633 \u0627\u0644\u062a\u0641\u0627\u0635\u064a\u0644 \u062d\u062a\u0649 \u064a\u0641\u0642\u062f \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u0646\u0634\u0627\u0637 \u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0648\u064a\u062d\u0641\u0638 \u0627\u0644\u062d\u0644 \u0622\u0644\u064a\u0627\u064b.","\u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0643\u0628\u0627\u0631 \u0627\u0644\u0633\u0646 \u0641\u064a \u0623\u0642\u0633\u0627\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u063a\u064a\u0631 \u0627\u0644\u0646\u0638\u0627\u0645\u064a\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aMs=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u0627\u0644\u0627\u0646\u0632\u0644\u0627\u0642 \u0627\u0644\u0645\u0633\u0645\u0649 "\u0634\u064a\u062e\u0648\u062e\u0629 \u0627\u0644\u0648\u0636\u0639\u064a\u0627\u062a" (Vieillissement des situations) \u064a\u0639\u0646\u064a:',B.ay9,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0644\u0646\u0641\u0633 \u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0628\u0646\u0641\u0633 \u0627\u0644\u062a\u0641\u0627\u0635\u064a\u0644 \u062d\u062a\u0649 \u064a\u0641\u0642\u062f \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u0646\u0634\u0627\u0637 \u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0648\u064a\u062d\u0641\u0638 \u0627\u0644\u062d\u0644 \u0622\u0644\u064a\u0627\u064b.",u.e)
B.af5=s(["\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u062d\u0633-\u062d\u0631\u0643\u064a.","\u0645\u0631\u062d\u0644\u0629 \u0645\u0627 \u0642\u0628\u0644 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a (\u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0627\u0644\u0631\u0645\u0632\u064a \u0627\u0644\u062a\u0645\u0631\u0643\u0632\u064a).","\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0645\u0627\u062f\u064a\u0629/\u0627\u0644\u0645\u0644\u0645\u0648\u0633\u0629 (\u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638\u060c \u0627\u0644\u062a\u0631\u062a\u064a\u0628\u060c \u0627\u0644\u062a\u0635\u0646\u064a\u0641 \u0627\u0644\u0645\u0627\u062f\u064a).","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aJI=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u062d\u0633\u0628 "\u062c\u0627\u0646 \u0628\u064a\u0627\u062c\u064a\u0647"\u060c \u064a\u0645\u0631 \u0637\u0641\u0644 \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0631\u0627\u0628\u0639\u0629 \u0627\u0628\u062a\u062f\u0627\u0626\u064a (8-10 \u0633\u0646\u0648\u0627\u062a) \u0628\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0645\u0639\u0631\u0641\u064a \u0627\u0644\u0645\u0644\u0642\u0628\u0629 \u0628\u0640:',B.af5,2,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0645\u0627\u062f\u064a\u0629/\u0627\u0644\u0645\u0644\u0645\u0648\u0633\u0629 (\u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638\u060c \u0627\u0644\u062a\u0631\u062a\u064a\u0628\u060c \u0627\u0644\u062a\u0635\u0646\u064a\u0641 \u0627\u0644\u0645\u0627\u062f\u064a).",u.e)
B.a0V=s(["\u0643\u0645\u064a\u0629 \u0627\u0644\u0633\u0627\u0626\u0644 \u0623\u0648 \u0627\u0644\u0645\u0627\u062f\u0629 \u062a\u062a\u063a\u064a\u0631 \u062a\u0644\u0642\u0627\u0626\u064a\u0627\u064b \u0628\u062a\u063a\u064a\u0631 \u0634\u0643\u0644 \u0627\u0644\u0625\u0646\u0627\u0621.","\u0643\u0645\u064a\u0629 \u0627\u0644\u0645\u0627\u062f\u0629 \u062a\u0628\u0642\u0649 \u062b\u0627\u0628\u062a\u0647 \u0648\u0645\u062d\u0641\u0648\u0638\u0629 \u0631\u063a\u0645 \u062a\u063a\u064a\u0631 \u0634\u0643\u0644\u0647\u0627 \u0627\u0644\u062e\u0627\u0631\u062c\u064a \u0623\u0648 \u062a\u0645\u0648\u0642\u0639\u0647\u0627 \u0627\u0644\u0641\u0636\u0627\u0626\u064a.","\u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0644\u0627 \u064a\u0645\u0643\u0646 \u062c\u0645\u0639\u0647\u0627 \u0625\u0644\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0645\u062a\u0634\u0627\u0628\u0647\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aYN=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u0645\u0641\u0647\u0648\u0645 "\u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0627\u0644\u0643\u0645\u064a\u0629 \u0648\u0627\u0644\u0645\u0627\u062f\u0629" \u0639\u0646\u062f \u0628\u064a\u0627\u062c\u064a\u0647 \u064a\u0639\u0646\u064a \u0642\u062f\u0631\u0629 \u0627\u0644\u0637\u0641\u0644 \u0639\u0644\u0649 \u0625\u062f\u0631\u0627\u0643 \u0623\u0646:',B.a0V,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0643\u0645\u064a\u0629 \u0627\u0644\u0645\u0627\u062f\u0629 \u062a\u0628\u0642\u0649 \u062b\u0627\u0628\u062a\u0647 \u0648\u0645\u062d\u0641\u0648\u0638\u0629 \u0631\u063a\u0645 \u062a\u063a\u064a\u0631 \u0634\u0643\u0644\u0647\u0627 \u0627\u0644\u062e\u0627\u0631\u062c\u064a \u0623\u0648 \u062a\u0645\u0648\u0642\u0639\u0647\u0627 \u0627\u0644\u0641\u0636\u0627\u0626\u064a.",u.e)
B.aoh=s(["\u0642\u062f\u0631\u0629 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u0639\u0644\u0649 \u0627\u0644\u062d\u0644 \u0628\u0645\u0641\u0631\u062f\u0647 \u0648\u0642\u062f\u0631\u062a\u0647 \u0639\u0644\u0649 \u0627\u0644\u062d\u0644 \u0628\u0645\u0633\u0627\u0639\u062f\u0629 \u0648\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0623\u0648 \u0627\u0644\u0623\u0642\u0631\u0627\u0646.","\u0645\u0639\u062f\u0644 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u0641\u064a \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0648\u0645\u0639\u062f\u0644\u0647 \u0641\u064a \u0627\u0644\u0644\u063a\u0627\u062a.","\u0627\u0644\u0633\u0646 \u0627\u0644\u0632\u0645\u0646\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0633\u0646\u0647 \u0627\u0644\u0639\u0642\u0644\u064a \u0627\u0644\u0645\u062d\u0633\u0648\u0628 \u0628\u0627\u0644\u0631\u0648\u0627\u0626\u0632 \u0627\u0644\u0646\u0641\u0633\u064a\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aR9=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'"\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0642\u0631\u064a\u0628" (ZPD) \u0644\u0644\u0628\u0627\u062d\u062b "\u0641\u064a\u063a\u0648\u062a\u0633\u0643\u064a" \u062a\u0645\u062b\u0644 \u0627\u0644\u0641\u0627\u0631\u0642 \u0628\u064a\u0646:',B.aoh,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0642\u062f\u0631\u0629 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u0639\u0644\u0649 \u0627\u0644\u062d\u0644 \u0628\u0645\u0641\u0631\u062f\u0647 \u0648\u0642\u062f\u0631\u062a\u0647 \u0639\u0644\u0649 \u0627\u0644\u062d\u0644 \u0628\u0645\u0633\u0627\u0639\u062f\u0629 \u0648\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0623\u0648 \u0627\u0644\u0623\u0642\u0631\u0627\u0646.",u.e)
B.arf=s(["\u0627\u0644\u0641\u0639\u0644 \u0648\u0627\u0644\u0635\u064a\u0627\u063a\u0629.","\u0627\u0644\u0627\u0633\u062a\u064a\u0639\u0627\u0628 (Assimilation) \u0648\u0627\u0644\u062a\u0644\u0627\u0624\u0645/\u0627\u0644\u0645\u0644\u0627\u0621\u0645\u0629 (Accommodation).","\u0627\u0644\u062d\u0641\u0638 \u0648\u0627\u0644\u062a\u0643\u0631\u0627\u0631.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aQN=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u0627\u0644\u0646\u0638\u0627\u0641\u0629 \u0627\u0644\u0645\u0639\u0631\u0641\u064a\u0629 \u0627\u0644\u0645\u0633\u0645\u0649 "\u0627\u0644\u062a\u0643\u064a\u0641" (Adaptation) \u0639\u0646\u062f \u0628\u064a\u0627\u062c\u064a\u0647 \u062a\u062a\u0645 \u0639\u0628\u0631 \u0639\u0645\u0644\u064a\u062a\u064a\u0646 \u0645\u062a\u0643\u0627\u0645\u0644\u062a\u064a\u0646 \u0647\u0645\u0627:',B.arf,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0627\u0633\u062a\u064a\u0639\u0627\u0628 (Assimilation) \u0648\u0627\u0644\u062a\u0644\u0627\u0624\u0645/\u0627\u0644\u0645\u0644\u0627\u0621\u0645\u0629 (Accommodation).",u.e)
B.a_2=s(["\u0646\u0642\u0635 \u0641\u064a \u0627\u0644\u0623\u062f\u0648\u0627\u062a \u0648\u0627\u0644\u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0627\u0644\u0645\u0627\u062f\u064a\u0629 \u062f\u0627\u062e\u0644 \u0627\u0644\u0641\u0635\u0644.","\u0635\u0639\u0648\u0628\u0629 \u0646\u0627\u062a\u062c\u0629 \u0639\u0646 \u0645\u0639\u0627\u0631\u0641 \u0633\u0627\u0628\u0642\u0629 \u0643\u0627\u0646\u062a \u0635\u062d\u064a\u062d\u0629 \u0641\u064a \u0633\u064a\u0627\u0642 \u0645\u0639\u064a\u0646 \u0644\u0643\u0646\u0647\u0627 \u0623\u0635\u0628\u062d\u062a \u062a\u062d\u0648\u0644 \u062f\u0648\u0646 \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u062c\u062f\u064a\u062f.","\u0636\u0639\u0641 \u0641\u064a \u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0648\u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0628\u064a\u0648\u0644\u0648\u062c\u064a \u0644\u062f\u0649 \u0627\u0644\u062a\u0644\u0645\u064a\u0630.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b4r=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u064a\u064f\u0639\u0631\u0641 "\u0627\u0644\u0639\u0627\u0626\u0642 \u0627\u0644\u0625\u0628\u0633\u062a\u0645\u0648\u0644\u0648\u062c\u064a" \u062d\u0633\u0628 "\u0628\u0627\u0634\u0644\u0627\u0631" \u0628\u0623\u0646\u0647:',B.a_2,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0635\u0639\u0648\u0628\u0629 \u0646\u0627\u062a\u062c\u0629 \u0639\u0646 \u0645\u0639\u0627\u0631\u0641 \u0633\u0627\u0628\u0642\u0629 \u0643\u0627\u0646\u062a \u0635\u062d\u064a\u062d\u0629 \u0641\u064a \u0633\u064a\u0627\u0642 \u0645\u0639\u064a\u0646 \u0644\u0643\u0646\u0647\u0627 \u0623\u0635\u0628\u062d\u062a \u062a\u062d\u0648\u0644 \u062f\u0648\u0646 \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0627\u0644\u062c\u062f\u064a\u062f.",u.e)
B.acc=s(["\u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u0634\u0631\u062d \u063a\u064a\u0631 \u0627\u0644\u0645\u0646\u0627\u0633\u0628\u0629 \u0645\u0646 \u0627\u0644\u0623\u0633\u062a\u0627\u0630.","\u0639\u062f\u0645 \u0646\u0636\u062c \u0627\u0644\u0642\u062f\u0631\u0627\u062a \u0627\u0644\u0630\u0647\u0646\u064a\u0629 \u0648\u0627\u0644\u0645\u0639\u0631\u0641\u064a\u0629 \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0644\u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0641\u064a \u062a\u0644\u0643 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0639\u0645\u0631\u064a\u0629.","\u062a\u0643\u0627\u0633\u0644 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0639\u062f\u0645 \u0625\u0646\u062c\u0627\u0632\u0647 \u0644\u0644\u0648\u0627\u062c\u0628\u0627\u062a.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aYA=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u0627\u0644\u062e\u0637\u0623 \u0627\u0644\u0646\u0627\u062c\u0645 \u0639\u0646 "\u0627\u0644\u0645\u0635\u062f\u0631 \u0627\u0644\u0646\u0645\u0627\u0626\u064a/\u0627\u0644\u0646\u0634\u0648\u0626\u064a" \u064a\u0639\u0648\u062f \u0628\u0627\u0644\u0623\u0633\u0627\u0633 \u0625\u0644\u0649:',B.acc,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0639\u062f\u0645 \u0646\u0636\u062c \u0627\u0644\u0642\u062f\u0631\u0627\u062a \u0627\u0644\u0630\u0647\u0646\u064a\u0629 \u0648\u0627\u0644\u0645\u0639\u0631\u0641\u064a\u0629 \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0644\u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0645\u0641\u0647\u0648\u0645 \u0641\u064a \u062a\u0644\u0643 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0639\u0645\u0631\u064a\u0629.",u.e)
B.afs=s(["\u0627\u0644\u0646\u0636\u062c \u0627\u0644\u0628\u064a\u0648\u0644\u0648\u062c\u064a \u0644\u0644\u062c\u0647\u0627\u0632 \u0627\u0644\u0639\u0635\u0628\u064a.","\u0627\u0644\u0637\u0631\u064a\u0642\u0629 \u0623\u0648 \u0627\u0644\u0625\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0648\u0627\u0644\u0623\u0633\u0644\u0648\u0628 \u0627\u0644\u0630\u064a \u0627\u0639\u062a\u0645\u062f \u0627\u0644\u0645\u062f\u0631\u0633 \u0641\u064a \u062a\u0642\u062f\u064a\u0645 \u0648\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0641\u0647\u0648\u0645.","\u0639\u062f\u0645 \u062a\u0648\u0641\u0631 \u0627\u0644\u0633\u0643\u0646 \u0627\u0644\u0644\u0627\u0626\u0642 \u0644\u0644\u0645\u062a\u0639\u0644\u0645.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b19=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u0627\u0644\u062e\u0637\u0623 \u0627\u0644\u0646\u0627\u062c\u0645 \u0639\u0646 "\u0627\u0644\u0645\u0635\u062f\u0631 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a" \u064a\u0631\u062c\u0639 \u0625\u0644\u0649:',B.afs,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0637\u0631\u064a\u0642\u0629 \u0623\u0648 \u0627\u0644\u0625\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0648\u0627\u0644\u0623\u0633\u0644\u0648\u0628 \u0627\u0644\u0630\u064a \u0627\u0639\u062a\u0645\u062f \u0627\u0644\u0645\u062f\u0631\u0633 \u0641\u064a \u062a\u0642\u062f\u064a\u0645 \u0648\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0641\u0647\u0648\u0645.",u.e)
B.Zq=s(["\u0625\u0639\u0637\u0627\u0621 \u0627\u0644\u0639\u0644\u0627\u0645\u0629 \u0648\u0627\u0644\u062f\u0631\u062c\u0629 \u0627\u0644\u0639\u062f\u062f\u064a\u0629 \u0641\u0642\u0637 \u062f\u0648\u0646 \u062a\u0639\u0644\u064a\u0642.","\u062a\u0642\u062f\u064a\u0645 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0648\u0625\u0634\u0627\u0631\u0627\u062a \u0641\u0648\u0631\u064a\u0629 \u0644\u0644 \u062a\u0644\u0645\u064a\u0630 \u062a\u0634\u0631\u062d \u0645\u0635\u062f\u0631 \u062e\u0637\u0626\u0647 \u0648\u0643\u064a\u0641\u064a\u0629 \u062a\u0642\u0644\u064a\u0635 \u0627\u0644\u0641\u062c\u0648\u0629 \u0644\u0644\u0623\u062f\u0627\u0621 \u0627\u0644\u0635\u062d\u064a\u062d.","\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u062f\u0631\u0633 \u0645\u0646 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u062f\u0648\u0646 \u0627\u0633\u062a\u062b\u0646\u0627\u0621.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aKF=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u064a\u064f\u0642\u0635\u062f \u0628\u0640 "\u0627\u0644\u062a\u063a\u0630\u064a\u0629 \u0627\u0644\u0631\u0627\u062c\u0639\u0629" (Feedback) \u0627\u0644\u0641\u0639\u0627\u0644\u0629 \u0641\u064a \u0645\u0627\u062f\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a:',B.Zq,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0642\u062f\u064a\u0645 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0648\u0625\u0634\u0627\u0631\u0627\u062a \u0641\u0648\u0631\u064a\u0629 \u0644\u0644 \u062a\u0644\u0645\u064a\u0630 \u062a\u0634\u0631\u062d \u0645\u0635\u062f\u0631 \u062e\u0637\u0626\u0647 \u0648\u0643\u064a\u0641\u064a\u0629 \u062a\u0642\u0644\u064a\u0635 \u0627\u0644\u0641\u062c\u0648\u0629 \u0644\u0644\u0623\u062f\u0627\u0621 \u0627\u0644\u0635\u062d\u064a\u062d.",u.e)
B.aow=s(["\u062a\u0642\u0633\u064a\u0645 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u062d\u0633\u0628 \u0633\u0646\u0647\u0645 \u0627\u0644\u0645\u062f\u0631\u0633 \u0648\u0627\u0644\u0627\u0639\u062a\u0645\u0627\u062f \u0639\u0644\u0649 \u0627\u0644\u0643\u062a\u0627\u0628 \u0627\u0644\u0645\u062f\u0631\u0633 \u062d\u0635\u0631\u0627\u064b.","\u062a\u0641\u064a\u064a\u0626 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u062d\u0633\u0628 \u0645\u0633\u062a\u0648\u0627\u0647\u0645 \u0627\u0644\u0623\u062f\u0627\u0621 \u0627\u0644\u0641\u0639\u0644\u064a \u0627\u0644\u0645\u0633\u062a\u0642\u0644 \u0639\u0646 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u062f\u0631\u0627\u0633\u064a \u0648\u0625\u0631\u062c\u0627\u0639\u0647\u0645 \u0644\u0644\u0623\u0635\u0648\u0644 \u0639\u0628\u0631 \u0623\u0646\u0634\u0637\u0629 \u062a\u0641\u0627\u0639\u0644\u064a\u0629.","\u062a\u0642\u062f\u064a\u0645 \u062f\u0631\u0648\u0633 \u0627\u0644\u0641\u064a\u0632\u064a\u0627\u0621 \u0648\u0627\u0644\u0643\u0645\u064a\u0627\u0621 \u0644\u0644\u0645\u0631\u0627\u062d\u0644 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aLi=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u0627\u0644\u0645\u0628\u062f\u0623 \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a \u0627\u0644\u0645\u0633\u0645\u0649 "\u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0648\u0641\u0642 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u0646\u0627\u0633\u0628" (TaRL) \u064a\u0631\u062a\u0643\u0632 \u0641\u064a \u0627\u0644\u062f\u0639\u0645 \u0639\u0644\u0649:',B.aow,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0641\u064a\u064a\u0626 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u062d\u0633\u0628 \u0645\u0633\u062a\u0648\u0627\u0647\u0645 \u0627\u0644\u0623\u062f\u0627\u0621 \u0627\u0644\u0641\u0639\u0644\u064a \u0627\u0644\u0645\u0633\u062a\u0642\u0644 \u0639\u0646 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u062f\u0631\u0627\u0633\u064a \u0648\u0625\u0631\u062c\u0627\u0639\u0647\u0645 \u0644\u0644\u0623\u0635\u0648\u0644 \u0639\u0628\u0631 \u0623\u0646\u0634\u0637\u0629 \u062a\u0641\u0627\u0639\u0644\u064a\u0629.",u.e)
B.akJ=s(["\u0625\u0639\u0637\u0627\u0621 \u0646\u0641\u0633 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0648\u0646\u0641\u0633 \u0627\u0644\u0625\u064a\u0642\u0627\u0639 \u0648\u0627\u0644\u0648\u0633\u0627\u0626\u0644 \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0644\u062a\u0623\u0645\u064a\u0646 \u0627\u0644\u0645\u0633\u0627\u0648\u0627\u0629.","\u062a\u0646\u0648\u064a\u0639 \u0627\u0644\u0648\u0636\u0639\u064a\u0627\u062a \u0648\u0637\u0631\u0642 \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0648\u0627\u0644\u0623\u062f\u0648\u0627\u062a \u0648\u0648\u062a\u0627\u0626\u0631 \u0627\u0644\u062a\u0639\u0644\u0645 \u0644\u062a\u0646\u0627\u0633\u0628 \u0627\u0644\u0641\u0631\u0648\u0642 \u0627\u0644\u0641\u0631\u062f\u064a\u0629 \u0644\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646.","\u0641\u0635\u0644 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0627\u0644\u0645\u062a\u0639\u062b\u0631\u064a\u0646 \u0641\u064a \u0623\u0642\u0633\u0627\u0645 \u062e\u0627\u0635\u0629 \u0645\u0633\u062a\u0642\u0644\u0629 \u0637\u064a\u0644\u0629 \u0627\u0644\u0633\u0646\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b87=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'"\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0641\u0627\u0631\u0642\u064a\u0629" \u062a\u062f\u0639\u0648 \u062f\u0627\u062e\u0644 \u062f\u0631\u0633 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0625\u0644\u0649:',B.akJ,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u062a\u0646\u0648\u064a\u0639 \u0627\u0644\u0648\u0636\u0639\u064a\u0627\u062a \u0648\u0637\u0631\u0642 \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0648\u0627\u0644\u0623\u062f\u0648\u0627\u062a \u0648\u0648\u062a\u0627\u0626\u0631 \u0627\u0644\u062a\u0639\u0644\u0645 \u0644\u062a\u0646\u0627\u0633\u0628 \u0627\u0644\u0641\u0631\u0648\u0642 \u0627\u0644\u0641\u0631\u062f\u064a\u0629 \u0644\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646.",u.e)
B.atF=s(["\u0627\u0644\u0627\u0642\u062a\u0635\u0627\u0631 \u0627\u0644\u0633\u0627\u0628\u0642 \u0639\u0644\u0649 \u0636\u0631\u0628 \u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0627\u0644\u0635\u062d\u064a\u062d\u0629 \u0642\u0628\u0644 \u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0627\u0644\u0639\u0634\u0631\u064a\u0629 \u0648\u0627\u0644\u0643\u0633\u0631\u064a\u0629 (\u0627\u0644\u0623\u0635\u063a\u0631 \u0645\u0646 1).","\u0636\u0639\u0641 \u062d\u0641\u0638 \u062c\u062f\u0648\u0644 \u0627\u0644\u0636\u0631\u0628 \u0627\u0644\u0625\u0639\u062a\u064a\u0627\u062f\u064a.","\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0645\u0633\u0627\u0637\u0631 \u063a\u064a\u0631 \u062f\u0642\u064a\u0642\u0629 \u0641\u064a \u0627\u0644\u0631\u0633\u0645 \u0627\u0644\u0647\u0646\u062f\u0633\u064a.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aGF=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u064a\u0639\u062a\u0628\u0631 \u0627\u0644\u0639\u0627\u0626\u0642 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u0627\u0644\u0645\u062a\u0645\u062b\u0644 \u0641\u064a \u0627\u0644\u0627\u0639\u062a\u0642\u0627\u062f \u0628\u0623\u0646 "\u0627\u0644\u0636\u0631\u0628 \u064a\u0624\u062f\u064a \u062f\u0627\u0626\u0645\u0627\u064b \u0625\u0644\u0649 \u0627\u0644\u062a\u0643\u0628\u064a\u0631" \u0646\u0627\u062a\u062c\u0627\u064b \u0639\u0646:',B.atF,0,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0627\u0642\u062a\u0635\u0627\u0631 \u0627\u0644\u0633\u0627\u0628\u0642 \u0639\u0644\u0649 \u0636\u0631\u0628 \u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0627\u0644\u0635\u062d\u064a\u062d\u0629 \u0642\u0628\u0644 \u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0627\u0644\u0639\u0634\u0631\u064a\u0629 \u0648\u0627\u0644\u0643\u0633\u0631\u064a\u0629 (\u0627\u0644\u0623\u0635\u063a\u0631 \u0645\u0646 1).",u.e)
B.YD=s(["\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0628\u0635\u0631\u064a \u0627\u0644\u0641\u0636\u0627\u0626\u064a \u0641\u0642\u0637.","\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0645\u0646\u0637\u0642\u064a \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a (Logico-math\xe9matique).","\u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0645\u0648\u0633\u064a\u0642\u064a \u0627\u0644\u0625\u064a\u0642\u0627\u0639\u064a.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aR7=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u0641\u064a \u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0630\u0643\u0627\u0621\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u062f\u062f\u0629 \u0644\u0640 "\u063a\u0627\u0631\u062f\u0646\u0631"\u060c \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0623\u0643\u062b\u0631 \u0627\u0631\u062a\u0628\u0627\u0637\u0627\u064b \u0628\u0645\u0627\u062f\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0648\u0627\u0644\u0645\u0646\u0637\u0642 \u0647\u0648:',B.YD,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0645\u0646\u0637\u0642\u064a \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a (Logico-math\xe9matique).",u.e)
B.Wc=s(["\u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u062a\u0630\u0643\u0631 \u0627\u0644\u0645\u0633\u0627\u0631\u0627\u062a \u0627\u0644\u062d\u0633\u0627\u0628\u064a\u0629 \u0627\u0644\u0645\u0639\u0637\u0627\u0629 \u0645\u0646 \u0627\u0644\u0645\u0639\u0644\u0645 \u0628\u062d\u0631\u0641\u064a\u062a\u0647\u0627.","\u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u062a\u0648\u0644\u064a\u062f \u0623\u0641\u0643\u0627\u0631 \u0648\u0637\u0631\u0642 \u062d\u0644\u0648\u0644 \u0645\u062a\u0639\u062f\u062f\u0629 \u0648\u063a\u064a\u0631 \u062a\u0642\u0644\u064a\u062f\u064a\u0629 \u0644\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0634\u0643\u0644\u0629.","\u0627\u0644\u0628\u0637\u0621 \u0627\u0644\u0634\u062f\u064a\u062f \u0641\u064a \u062d\u0633\u0627\u0628 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0628\u0633\u064a\u0637\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aFU=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u064a\u064f\u0642\u0635\u062f \u0628\u0645\u0641\u0647\u0648\u0645 "\u0627\u0644\u062a\u0641\u0643\u064a\u0631 \u0627\u0644\u0645\u062a\u0634\u0639\u0628/\u0627\u0644\u0625\u0628\u062f\u0627\u0639\u064a" \u0641\u064a \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a:',B.Wc,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u062a\u0648\u0644\u064a\u062f \u0623\u0641\u0643\u0627\u0631 \u0648\u0637\u0631\u0642 \u062d\u0644\u0648\u0644 \u0645\u062a\u0639\u062f\u062f\u0629 \u0648\u063a\u064a\u0631 \u062a\u0642\u0644\u064a\u062f\u064a\u0629 \u0644\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0634\u0643\u0644\u0629.",u.e)
B.ag5=s(["\u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0629 \u0641\u0642\u0637.","\u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0639\u0627\u0644\u0645\u0629 (Savoir savant) \u0625\u0644\u0649 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0648\u0627\u062c\u0628 \u062a\u062f\u0631\u064a\u0633\u0647\u0627 \u062b\u0645 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0645\u062f\u0631\u0633\u0629.","\u0627\u0644\u0623\u0633\u0644\u0648\u0628 \u0627\u0644\u0642\u062f\u064a\u062f \u0641\u064a \u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0644\u0648\u0628 \u0627\u0644\u062d\u062f\u064a\u062b.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aSx=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639","\u0627\u0644\u0646\u0642\u0644 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a ( Transposition  didactique ) \u064a\u062a\u0636\u0645\u0646 \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0645\u0646:",B.ag5,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0639\u0627\u0644\u0645\u0629 (Savoir savant) \u0625\u0644\u0649 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0648\u0627\u062c\u0628 \u062a\u062f\u0631\u064a\u0633\u0647\u0627 \u062b\u0645 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0627\u0644\u0645\u062f\u0631\u0633\u0629.",u.e)
B.a6Q=s(["\u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u062a\u062e\u064a\u0644 \u0627\u0644\u0623\u0634\u0643\u0627\u0644 \u0627\u0644\u0647\u0646\u062f\u0633\u064a\u0629 \u0645\u0646 \u0645\u0646\u0638\u0648\u0631 \u0634\u062e\u0635 \u0622\u062e\u0631 \u0628\u0633\u0647\u0648\u0644\u0629.","\u0635\u0639\u0648\u0628\u0629 \u0627\u0633\u062a\u064a\u0639\u0627\u0628 \u0627\u0644\u062a\u0645\u0627\u062b\u0644 \u0627\u0644\u0645\u062d\u0648\u0631\u064a \u0648\u0627\u0644\u0625\u0632\u0627\u062d\u0629 \u0648\u0631\u0624\u064a\u0629 \u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0645\u0646 \u0648\u062c\u0647\u0629 \u0646\u0638\u0631 \u0641\u0636\u0627\u0626\u064a\u0629 \u0645\u062e\u0627\u0644\u0650\u0641\u0629.","\u0627\u0644\u062a\u0641\u0648\u0642 \u0627\u0644\u0639\u0627\u0644\u064a \u0641\u064a \u0625\u062c\u0631\u0627\u0621 \u0627\u0644\u0642\u0633\u0645\u0629 \u0627\u0644\u0645\u0637\u0648\u0644\u0629.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aPT=new A.a("\u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0631\u0627\u0628\u0639",'\u0645\u0641\u0647\u0648\u0645 "\u0627\u0644\u062a\u0645\u0631\u0643\u0632 \u062d\u0648\u0644 \u0627\u0644\u0630\u0627\u062a" (Egocentrisme) \u0627\u0644\u0645\u0639\u0631\u0641\u064a \u0639\u0646\u062f \u0627\u0644\u0637\u0641\u0644 \u064a\u062a\u0633\u0628\u0628 \u0641\u064a \u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a \u0641\u064a:',B.a6Q,1,"\u0627\u0644\u0625\u062c\u0627\u0628\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629: \u0635\u0639\u0648\u0628\u0629 \u0627\u0633\u062a\u064a\u0639\u0627\u0628 \u0627\u0644\u062a\u0645\u0627\u062b\u0644 \u0627\u0644\u0645\u062d\u0648\u0631\u064a \u0648\u0627\u0644\u0625\u0632\u0627\u062d\u0629 \u0648\u0631\u0624\u064a\u0629 \u0627\u0644\u0623\u0634\u064a\u0627\u0621 \u0645\u0646 \u0648\u062c\u0647\u0629 \u0646\u0638\u0631 \u0641\u0636\u0627\u0626\u064a\u0629 \u0645\u062e\u0627\u0644\u0650\u0641\u0629.",u.e)
B.aiH=s(["\u062a\u0636\u064a\u064a\u0639 \u0644\u0644\u0648\u0642\u062a \u0648\u0627\u0644\u0647\u0631\u0648\u0628 \u0645\u0646 \u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629 \u0627\u0644\u0645\u0633\u0637\u0631\u0629.","\u0625\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0629 \u0645\u0648\u062c\u0647\u0629 \u062a\u064f\u0648\u0638\u0641 \u0627\u0644\u0644\u0639\u0628 \u0627\u0644\u0647\u0627\u062f\u0641 \u0643\u0648\u0627\u0633\u0637\u0629 \u0644\u0628\u0646\u0627\u0621 \u0648\u0636\u0628\u0637 \u0627\u0644\u0645\u0641\u0627\u0647\u064a\u0645 \u0648\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u062a\u0639\u0627\u0648\u0646.","\u0646\u0634\u0627\u0637 \u0644\u0627 \u0635\u0641\u064a \u064a\u0646\u062c\u0632\u0647 \u0627\u0644\u062a\u0644\u0645\u064a\u0630 \u0641\u064a \u0633\u0627\u062d\u0629 \u0627\u0644\u0627\u0633\u062a\u0631\u0627\u062d\u0629 \u062d\u0635\u0631\u0627\u064b.","\u062c\u0645\u064a\u0639 \u0627\u0644\u062e\u064a\u0627\u0631\u0627\u062a \u062e\u0627\u0637\u0626\u0629."],t.s)
