B.ab4=s(["\u0642\u0631\u0627\u0621\u0629 (\u0646\u0635 \u062a\u0643\u0645\u064a\u0644\u064a) \u0648\u0642\u0631\u0627\u0621\u0629 \u0645\u0633\u062a\u0631\u0633\u0644\u0629 (\u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u062a\u0631\u0643\u064a\u0628\u064a) \u0648\u062a\u0648\u0627\u0635\u0644 \u0634\u0641\u0647\u064a (\u062f\u0639\u0645) \u0648\u0642\u0631\u0627\u0621\u0629 \u0648\u0641\u0647\u0645 \u0648\u0634\u0643\u0644 (\u062f\u0639\u0645) \u0648\u0635\u0631\u0641 \u0648\u062a\u062d\u0648\u064a\u0644 (\u062f\u0639\u0645) \u0648\u062a\u0631\u0627\u0643\u064a\u0628 (\u062f\u0639\u0645) \u0648\u0625\u0645\u0644\u0627\u0621 (\u062f\u0639\u0645) \u0648\u062a\u0639\u0628\u064a\u0631 \u0643\u062a\u0627\u0628\u064a (\u062f\u0639\u0645) \u0628\u062d\u0635\u062a\u064a\u0646","\u0642\u0631\u0627\u0621\u0629 \u0646\u0635 \u062c\u062f\u064a\u062f \u0645\u0646 \u062e\u0627\u0631\u062c \u0627\u0644\u0643\u062a\u0627\u0628 \u0648\u062a\u0639\u0628\u064a\u0631 \u0643\u062a\u0627\u0628\u064a \u0628\u062d\u0635\u0629 \u0648\u0627\u062d\u062f\u0629 \u0641\u0642\u0637","\u0627\u0633\u062a\u0643\u0634\u0627\u0641 \u0645\u0648\u0627\u0631\u062f \u062c\u062f\u064a\u062f\u0629 \u0644\u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u0643\u0648\u0646\u0627\u062a \u0645\u0639 \u062a\u0642\u0648\u064a\u0645 \u0625\u062c\u0645\u0627\u0644\u064a","\u0625\u0646\u062c\u0627\u0632 \u0645\u0634\u0631\u0648\u0639 \u0627\u0644\u0648\u062d\u062f\u0629 \u0648\u0639\u0631\u0636\u0647 \u0641\u0642\u0637 \u062f\u0648\u0646 \u0628\u0642\u064a\u0629 \u0627\u0644\u0645\u0643\u0648\u0646\u0627\u062a","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b6x=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062e\u0627\u0645\u0633 \u0645\u0646 \u0627\u0644\u0648\u062d\u062f\u0629 \u0627\u0644\u062f\u0631\u0627\u0633\u064a\u0629 \u0628\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 (\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062f\u0639\u0645) \u064a\u064f\u062f\u0628\u064e\u0651\u0631 \u0648\u0641\u0642 \u0645\u0627 \u064a\u0623\u062a\u064a:",B.ab4,0,"\u0627\u0644\u0628\u0631\u0645\u062c\u0629 \u0627\u0644\u0632\u0645\u0646\u064a\u0629 \u0644\u0644\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062e\u0627\u0645\u0633 \u062a\u062e\u0635\u0635 \u0642\u0631\u0627\u0621\u0629 \u0646\u0635 \u062a\u0643\u0645\u064a\u0644\u064a \u0648\u0642\u0631\u0627\u0621\u0629 \u0645\u0633\u062a\u0631\u0633\u0644\u0629 (\u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u062a\u0631\u0643\u064a\u0628\u064a) \u0648\u0623\u0646\u0634\u0637\u0629 \u062f\u0639\u0645 \u0641\u064a \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0627\u0644\u0634\u0641\u0647\u064a \u0648\u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0648\u0627\u0644\u0634\u0643\u0644 \u0648\u0627\u0644\u0635\u0631\u0641 \u0648\u0627\u0644\u062a\u0631\u0627\u0643\u064a\u0628 \u0648\u0627\u0644\u0625\u0645\u0644\u0627\u0621 \u0648\u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0627\u0644\u0643\u062a\u0627\u0628\u064a (\u062d\u0635\u0629 \u062f\u0639\u0645 \xd72).",u.Z)
B.amK=s(["\u0627\u0644\u0625\u0646\u062c\u0627\u0632\u060c \u062b\u0645 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u0648\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0644\u0647\u060c \u062b\u0645 \u0627\u0644\u062a\u062c\u0648\u064a\u062f \u0648\u0627\u0644\u0639\u0631\u0636","\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u0648\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0644\u0647\u060c \u062b\u0645 \u0627\u0644\u0625\u0646\u062c\u0627\u0632\u060c \u062b\u0645 \u0627\u0644\u062a\u062c\u0648\u064a\u062f \u0648\u0627\u0644\u0639\u0631\u0636","\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0634\u0631\u0648\u0639\u060c \u062b\u0645 \u0627\u0644\u062a\u062c\u0648\u064a\u062f \u0648\u0627\u0644\u0639\u0631\u0636\u060c \u062b\u0645 \u0627\u0644\u0625\u0646\u062c\u0627\u0632","\u0627\u0644\u062a\u062c\u0648\u064a\u062f \u0648\u0627\u0644\u0639\u0631\u0636\u060c \u062b\u0645 \u0627\u0644\u0625\u0646\u062c\u0627\u0632\u060c \u062b\u0645 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u0648\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0644\u0647","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b4u=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u062a\u064f\u0646\u062c\u064e\u0632 \u062d\u0635\u0629 \u0645\u0634\u0631\u0648\u0639 \u0627\u0644\u0648\u062d\u062f\u0629 \u0628\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 (\u0639\u0628\u0631 \u0623\u0631\u0628\u0639 \u062d\u0635\u0635) \u0648\u0641\u0642 \u0627\u0644\u0633\u064a\u0631\u0648\u0631\u0629 \u0627\u0644\u062a\u0627\u0644\u064a\u0629:",B.amK,1,"\u062c\u0630\u0627\u0630\u0629 \u0645\u0634\u0631\u0648\u0639 \u0627\u0644\u0648\u062d\u062f\u0629 \u062a\u062d\u062f\u062f 4 \u062d\u0635\u0635 (\u062d\u0635\u0629 \u0643\u0644 \u0623\u0633\u0628\u0648\u0639): \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u0648\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0644\u0647\u060c \u0627\u0644\u0625\u0646\u062c\u0627\u0632 (1)\u060c \u0627\u0644\u0625\u0646\u062c\u0627\u0632 (2)\u060c \u0627\u0644\u062a\u062c\u0648\u064a\u062f \u0648\u0627\u0644\u0639\u0631\u0636.","\u062f\u0644\u064a\u0644 \u0627\u0644\u0623\u0633\u062a\u0627\u0630(\u0629) \u0643\u062a\u0627\u0628\u064a \u0641\u064a \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 6 \u2014 \u0635 23")
B.any=s(["\u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u0627\u0644\u062a\u0648\u0638\u064a\u0641\u060c \u062b\u0645 \u0627\u0633\u062a\u0643\u0634\u0627\u0641 \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0648\u0628\u0646\u0627\u0624\u0647\u0627","\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0646\u0635\u060c \u062b\u0645 \u0627\u0644\u0625\u0645\u0644\u0627\u0621\u060c \u062b\u0645 \u0627\u0644\u062a\u0642\u0648\u064a\u0645","\u0627\u0633\u062a\u0643\u0634\u0627\u0641 \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0648\u0628\u0646\u0627\u0624\u0647\u0627\u060c \u062b\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u0627\u0644\u062a\u0648\u0638\u064a\u0641","\u0627\u0633\u062a\u0643\u0634\u0627\u0641 \u0627\u0644\u0638\u0627\u0647\u0631\u0629\u060c \u062b\u0645 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0625\u062c\u0645\u0627\u0644\u064a \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b2B=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u062a\u064f\u0646\u062c\u064e\u0632 \u062d\u0635\u0629 \u0627\u0644\u0635\u0631\u0641 \u0648\u0627\u0644\u062a\u062d\u0648\u064a\u0644 \u0628\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0648\u0641\u0642 \u0627\u0644\u0633\u064a\u0631\u0648\u0631\u0629 \u0627\u0644\u062a\u0627\u0644\u064a\u0629:",B.any,2,"\u062c\u0630\u0627\u0630\u0629 \u0627\u0644\u0635\u0631\u0641 \u0648\u0627\u0644\u062a\u062d\u0648\u064a\u0644: \u0627\u0644\u062d\u0635\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 (\u0627\u0633\u062a\u0643\u0634\u0627\u0641 \u0627\u0644\u0638\u0627\u0647\u0631\u0629 \u0648\u0628\u0646\u0627\u0624\u0647\u0627)\u060c \u0627\u0644\u062d\u0635\u0629 \u0627\u0644\u062b\u0627\u0646\u064a\u0629 (\u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u0627\u0644\u062a\u0648\u0638\u064a\u0641).",u.Z)
B.akD=s(["\u0627\u0644\u0645\u0633\u0648\u062f\u0629\u060c \u0627\u0644\u062a\u062e\u0637\u064a\u0637\u060c \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629\u060c \u0627\u0644\u0639\u0631\u0636","\u0627\u0644\u062a\u062e\u0637\u064a\u0637\u060c \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629\u060c \u0627\u0644\u0645\u0633\u0648\u062f\u0629\u060c \u0627\u0644\u0639\u0631\u0636","\u0627\u0644\u062a\u062e\u0637\u064a\u0637\u060c \u0627\u0644\u0645\u0633\u0648\u062f\u0629\u060c \u0627\u0644\u0639\u0631\u0636\u060c \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629","\u0627\u0644\u062a\u062e\u0637\u064a\u0637\u060c \u0627\u0644\u0645\u0633\u0648\u062f\u0629\u060c \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629\u060c \u0627\u0644\u0639\u0631\u0636","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aFw=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u0645\u0631\u0627\u062d\u0644 \u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a\u0629 \u0628\u0645\u0643\u0648\u0651\u0646 \u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0627\u0644\u0643\u062a\u0627\u0628\u064a\u060c \u0648\u0641\u0642 \u0645\u0627 \u064a\u0623\u062a\u064a:",B.akD,3,"\u0648\u0631\u062f \u0641\u064a \u0627\u0644\u062f\u0644\u064a\u0644 \u0635\u0631\u0627\u062d\u0629: \xab\u0645\u0631\u0627\u062d\u0644 \u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a\u0629: \u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u2013 \u0627\u0644\u0645\u0633\u0648\u062f\u0629 \u2013 \u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u2013 \u0627\u0644\u0639\u0631\u0636\xbb.",u.cF)
B.amS=s(["\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u062a\u0644\u062e\u064a\u0635 \u0648\u0627\u0644\u062a\u0648\u0633\u0639 \u0648\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0648\u0627\u0644\u062a\u062d\u0648\u064a\u0644","\u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a\u0629 \u0628\u0645\u0631\u0627\u062d\u0644\u0647\u0627 \u0627\u0644\u0623\u0631\u0628\u0639 \u0641\u0642\u0637","\u0645\u0647\u0627\u0631\u0629 \u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u0631\u0633\u0627\u0644\u0629 \u0648\u0627\u0644\u0637\u0644\u0628 \u0641\u0642\u0637","\u0627\u0644\u0625\u0645\u0644\u0627\u0621 \u0627\u0644\u0645\u0646\u0638\u0648\u0631 \u0648\u0627\u0644\u0645\u0646\u0642\u0648\u0644","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b1V=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u0645\u0643\u0648\u0651\u0646 \u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0627\u0644\u0643\u062a\u0627\u0628\u064a \u0628\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629\u060c \u0641\u064a \u0627\u0644\u0648\u062d\u062f\u0627\u062a \u0645\u0646 2 \u0625\u0644\u0649 6\u060c \u064a\u064f\u062f\u0628\u064e\u0651\u0631 \u0639\u0628\u0631:",B.amS,0,"\u0627\u0644\u062f\u0644\u064a\u0644: \u0627\u0644\u0648\u062d\u062f\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u062a\u064f\u0639\u062a\u0645\u062f \u0641\u064a\u0647\u0627 \u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0627\u0644\u062a\u0641\u0627\u0639\u0644\u064a\u0629 \u0628\u0645\u0631\u0627\u062d\u0644\u0647\u0627 \u0627\u0644\u0623\u0631\u0628\u0639\u060c \u0648\u0627\u0644\u0648\u062d\u062f\u0627\u062a \u0645\u0646 2 \u0625\u0644\u0649 6 \u062a\u064f\u062f\u0631\u0633 \u0641\u064a\u0647\u0627 \u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0643\u062a\u0627\u0628\u0629 \u0643\u0627\u0644\u062a\u0644\u062e\u064a\u0635 \u0648\u0627\u0644\u062a\u0648\u0633\u0639 \u0648\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0648\u0627\u0644\u062a\u062d\u0648\u064a\u0644.","\u062f\u0644\u064a\u0644 \u0627\u0644\u0623\u0633\u062a\u0627\u0630(\u0629) \u0643\u062a\u0627\u0628\u064a \u0641\u064a \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 6 \u2014 \u0635 22")
B.axQ=s(["\u0627\u0644\u062a\u0647\u064a\u0626\u0629\u060c \u0627\u0644\u0646\u0645\u0630\u062c\u0629\u060c \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0648\u062c\u0647\u0629\u060c \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0633\u062a\u0642\u0644\u0629\u060c \u062b\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642","\u0627\u0644\u0646\u0645\u0630\u062c\u0629\u060c \u0627\u0644\u062a\u0647\u064a\u0626\u0629\u060c \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0633\u062a\u0642\u0644\u0629","\u0627\u0644\u062a\u0647\u064a\u0626\u0629\u060c \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0633\u062a\u0642\u0644\u0629\u060c \u0627\u0644\u0646\u0645\u0630\u062c\u0629\u060c \u0627\u0644\u062a\u0637\u0628\u064a\u0642","\u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0627\u0644\u062a\u0647\u064a\u0626\u0629\u060c \u0627\u0644\u0646\u0645\u0630\u062c\u0629\u060c \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0648\u062c\u0647\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aFZ=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u064a\u062a\u062f\u0631\u062c \u0628\u0646\u0627\u0621 \u062a\u0639\u0644\u0645\u0627\u062a \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0648\u0641\u0642 \u0645\u0628\u062f\u0623 \xab\u0627\u0644\u062a\u0641\u0648\u064a\u0636 \u0627\u0644\u062a\u062f\u0631\u064a\u062c\u064a \u0644\u0644\u0645\u0633\u0624\u0648\u0644\u064a\u0629\xbb \u0643\u0645\u0627 \u064a\u0644\u064a:",B.axQ,0,"\u0627\u0644\u062f\u0644\u064a\u0644: \xab\u064a\u0642\u0648\u0645 \u0627\u0644\u062a\u0641\u0648\u064a\u0636 \u0627\u0644\u062a\u062f\u0631\u064a\u062c\u064a \u0644\u0644\u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u062a\u0647\u064a\u0626\u0629 \u062b\u0645 \u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u0641\u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0648\u062c\u0647\u0629 \u062b\u0645 \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0645\u0633\u062a\u0642\u0644\u0629 \u0648\u0635\u0648\u0644\u0627\u064b \u0625\u0644\u0649 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\xbb.",u.u)
B.aba=s(["\u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u060c \u0645\u0627 \u0642\u0628\u0644 \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u060c \u0645\u0627 \u0628\u0639\u062f \u0627\u0644\u0642\u0631\u0627\u0621\u0629","\u0645\u0627 \u0642\u0628\u0644 \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u060c \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u060c \u0645\u0627 \u0628\u0639\u062f \u0627\u0644\u0642\u0631\u0627\u0621\u0629","\u0645\u0627 \u0642\u0628\u0644 \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u060c \u0645\u0627 \u0628\u0639\u062f \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u060c \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0642\u0631\u0627\u0621\u0629","\u0627\u0644\u0641\u0647\u0645\u060c \u0627\u0644\u062a\u062d\u0644\u064a\u0644\u060c \u0627\u0644\u062a\u0631\u0643\u064a\u0628\u060c \u0642\u0628\u0644 \u0627\u0644\u0642\u0631\u0627\u0621\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aUE=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u062a\u064f\u0646\u062c\u064e\u0632 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u0646\u0647\u062c\u064a\u0629 \u0648\u0641\u0642 \u0627\u0644\u0633\u064a\u0631\u0648\u0631\u0629 \u0627\u0644\u062a\u0627\u0644\u064a\u0629:",B.aba,1,"\u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u0646\u0647\u062c\u064a\u0629 \u062a\u0645\u0631 \u0628\u062b\u0644\u0627\u062b \u0645\u0631\u0627\u062d\u0644: \u0642\u0628\u0644 \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u060c \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 (\u0627\u0644\u0641\u0647\u0645 \u0648\u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u0627\u0644\u062a\u062d\u0644\u064a\u0644)\u060c \u0628\u0639\u062f \u0627\u0644\u0642\u0631\u0627\u0621\u0629 (\u0627\u0644\u062a\u0631\u0643\u064a\u0628 \u0648\u0627\u0644\u062a\u0642\u0648\u064a\u0645).","\u062f\u0644\u064a\u0644 \u0627\u0644\u0623\u0633\u062a\u0627\u0630(\u0629) \u0643\u062a\u0627\u0628\u064a \u0641\u064a \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 6 \u2014 \u0635 16")
B.aoJ=s(["\u0623\u0641\u0642 \u0627\u0644\u0627\u0646\u062a\u0638\u0627\u0631 \u0648\u0623\u0641\u0642 \u0627\u0644\u062a\u0648\u0642\u0639","\u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u0633\u0631\u062f\u064a\u0629 \u0648\u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u062d\u062c\u0627\u062c\u064a\u0629","\u062c\u0645\u0627\u0644\u064a\u0629 \u0627\u0644\u062a\u0644\u0642\u064a \u0648\u062c\u0645\u0627\u0644\u064a\u0629 \u0627\u0644\u062a\u0623\u062b\u064a\u0631","\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u0624\u0644\u0641 \u0648\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0646\u0627\u0642\u062f","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aZw=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u062a\u0644\u0642\u064a \u0641\u064a \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0645\u0646\u0647\u062c\u064a\u0629 \u062a\u0642\u0648\u0645 \u0639\u0644\u0649 \u0645\u0641\u0647\u0648\u0645\u064a\u0646 \u0645\u062a\u0643\u0627\u0645\u0644\u064a\u0646 \u0647\u0645\u0627:",B.aoJ,2,"\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u062a\u0644\u0642\u064a \u062a\u0642\u0648\u0645 \u0639\u0644\u0649 \u0645\u0641\u0647\u0648\u0645\u064a\u0646 \u0623\u062d\u062f\u0647\u0645\u0627 \u0645\u0643\u0645\u0644 \u0644\u0644\u0622\u062e\u0631: \u062c\u0645\u0627\u0644\u064a\u0629 \u0627\u0644\u062a\u0644\u0642\u064a (\u064a\u0627\u0648\u0633: \u0623\u0641\u0642 \u0627\u0644\u0627\u0646\u062a\u0638\u0627\u0631) \u0648\u062c\u0645\u0627\u0644\u064a\u0629 \u0627\u0644\u062a\u0623\u062b\u064a\u0631 (\u0622\u064a\u0632\u0631: \u0631\u062f\u0645 \u0627\u0644\u0641\u0631\u0627\u063a\u0627\u062a \u0648\u0627\u0644\u0641\u062c\u0648\u0627\u062a).",null)
B.atX=s(["\u0642\u064a\u0627\u0645 \u0627\u0644\u0642\u0627\u0631\u0626 \u0628\u0631\u062f\u0645 \u0627\u0644\u0641\u0631\u0627\u063a\u0627\u062a \u0623\u0648 \u0627\u0644\u0641\u062c\u0648\u0627\u062a \u0627\u0644\u062a\u064a \u064a\u062a\u0631\u0643\u0647\u0627 \u0627\u0644\u0646\u0635\u060c \u0645\u0645\u0627 \u064a\u062f\u0641\u0639\u0647 \u0625\u0644\u0649 \u0627\u0644\u063a\u0648\u0635 \u0641\u064a \u0623\u0639\u0645\u0627\u0642\u0647","\u062a\u062d\u0631\u064a\u0643 \u0627\u0644\u0642\u0627\u0631\u0626 \u0644\u0645\u0639\u0627\u0631\u0641\u0647 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0644\u064a\u0635\u0648\u063a \u0623\u0641\u0642 \u0627\u0646\u062a\u0638\u0627\u0631\u0647 \u062d\u0648\u0644 \u0627\u0644\u0646\u0635","\u0627\u0639\u062a\u0628\u0627\u0631 \u0627\u0644\u0642\u0627\u0631\u0626 \u0630\u0627\u062a\u0627\u064b \u0646\u0635\u064a\u0629 \u062a\u0633\u0647\u0645 \u0641\u064a \u0628\u0646\u0627\u0621 \u0645\u0639\u0646\u0649 \u0627\u0644\u0646\u0635","\u062f\u0631\u0627\u0633\u0629 \u0627\u0644\u0639\u0645\u0644\u064a\u0627\u062a \u0627\u0644\u0639\u0642\u0644\u064a\u0629 \u0627\u0644\u062a\u064a \u064a\u0642\u0648\u0645 \u0628\u0647\u0627 \u0627\u0644\u0642\u0627\u0631\u0626 \u0644\u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0639\u0646\u0649","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aVU=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\xab\u062c\u0645\u0627\u0644\u064a\u0629 \u0627\u0644\u062a\u0623\u062b\u064a\u0631\xbb \u0641\u064a \u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u062a\u0644\u0642\u064a \u062a\u0639\u0646\u064a:",B.atX,0,"\u062c\u0645\u0627\u0644\u064a\u0629 \u0627\u0644\u062a\u0623\u062b\u064a\u0631 \u0639\u0646\u062f \u0622\u064a\u0632\u0631: \u0627\u0644\u0642\u0627\u0631\u0626 \u064a\u0631\u062f\u0645 \u0627\u0644\u0641\u0631\u0627\u063a\u0627\u062a \u0623\u0648 \u0627\u0644\u0641\u062c\u0648\u0627\u062a \u0627\u0644\u062a\u064a \u064a\u062a\u0631\u0643\u0647\u0627 \u0627\u0644\u0646\u0635\u060c \u0648\u0647\u0630\u0627 \u064a\u062f\u0641\u0639\u0647 \u0625\u0644\u0649 \u0627\u0644\u063a\u0648\u0635 \u0641\u064a \u0623\u0639\u0645\u0627\u0642 \u0627\u0644\u0646\u0635.",null)
