B.aPY=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u0633\u0648\u0633\u064a\u0648\u0644\u0648\u062c\u064a\u0629 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0639\u0646\u062f \u0631\u0648\u0644\u0627\u0646 \u0628\u0627\u0631\u062a \u062a\u0639\u062a\u0628\u0631 \u0627\u0644\u0642\u0627\u0631\u0626:",B.ams,1,"\u0628\u0627\u0631\u062a \u064a\u0639\u062a\u0628\u0631 \u0627\u0644\u0642\u0627\u0631\u0626 \xab\u0630\u0627\u062a\u0627\u064b \u0646\u0635\u064a\u0629\xbb \u062a\u0633\u0647\u0645 \u0628\u0641\u0639\u0627\u0644\u064a\u0629 \u0641\u064a \u0628\u0646\u0627\u0621 \u0645\u0639\u0646\u0649 \u0627\u0644\u0646\u0635\u061b \u0641\u0627\u0644\u0645\u0639\u0646\u0649 \u0646\u062a\u0627\u062c \u0644\u0642\u0627\u0621 \u0628\u064a\u0646 \u0646\u0635 \u0627\u0644\u0642\u0627\u0631\u0626 \u0648\u0646\u0635 \u0627\u0644\u0645\u0624\u0644\u0641.",null)
B.ady=s(["\u0627\u0644\u0623\u0648\u0644\u0649 (\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a 1-3) \u0645\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u0642\u0631\u0627\u0621\u0629\u060c \u0648\u0627\u0644\u062b\u0627\u0646\u064a\u0629 (\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a 4-6) \u0645\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0648\u0627\u0644\u062a\u062d\u062f\u062b","\u0627\u0644\u0623\u0648\u0644\u0649 (\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a 1-2) \u0645\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u0643\u062a\u0627\u0628\u0629\u060c \u0648\u0627\u0644\u062b\u0627\u0646\u064a\u0629 (\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a 3-6) \u0645\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u0642\u0631\u0627\u0621\u0629","\u0627\u0644\u0623\u0648\u0644\u0649 (\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a 1-3) \u0645\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0648\u0627\u0644\u062a\u062d\u062f\u062b\u060c \u0648\u0627\u0644\u062b\u0627\u0646\u064a\u0629 (\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a 4-6) \u0645\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u0642\u0631\u0627\u0621\u0629","\u0627\u0644\u0623\u0648\u0644\u0649 (\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a 1-4) \u0645\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u062a\u0639\u0628\u064a\u0631\u060c \u0648\u0627\u0644\u062b\u0627\u0646\u064a\u0629 (\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a 5-6) \u0645\u062f\u062e\u0644\u0647\u0627 \u0627\u0644\u0642\u0631\u0627\u0621\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aZ0=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u064a\u062a\u062f\u0631\u062c \u062a\u0642\u062f\u064a\u0645 \u062a\u0639\u0644\u0645 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0641\u064a \u0627\u0644\u0633\u0644\u0643 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a \u0639\u0628\u0631 \u0645\u0631\u062d\u0644\u062a\u064a\u0646:",B.ady,2,"\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u062b\u0644\u0627\u062b\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u062a\u0639\u062a\u0645\u062f \u0645\u062f\u062e\u0644 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0648\u0627\u0644\u062a\u062d\u062f\u062b\u060c \u0648\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0639\u0644\u064a\u0627 (4\u060c 5\u060c 6) \u062a\u0639\u062a\u0645\u062f \u0645\u062f\u062e\u0644 \u0627\u0644\u0642\u0631\u0627\u0621\u0629.",u.L)
