B.aFC=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u062a\u0639\u062f \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u062b\u0627\u0644\u062b\u0629 \u0645\u0646 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u060c \u0641\u064a \u0647\u0646\u062f\u0633\u0629 \u0645\u0646\u0627\u0647\u062c \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629:",B.a07,0,"\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u062b\u0627\u0644\u062b\u0629 \u062e\u0627\u062a\u0645\u0629 \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0645\u0628\u0643\u0631 \u0644\u0644\u0642\u0631\u0627\u0621\u0629 \u0648\u0645\u062d\u0637\u0629 \u0645\u0647\u0645\u0629 \u0641\u064a \u062f\u0639\u0645 \u0627\u0644\u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0629 \u0641\u064a \u0627\u0644\u0633\u0646\u062a\u064a\u0646 \u0627\u0644\u0623\u0648\u0644\u0649 \u0648\u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u0648\u062a\u062b\u0628\u064a\u062a\u0647\u0627 \u0648\u0625\u063a\u0646\u0627\u0626\u0647\u0627.",u.L)
B.av6=s(["\u062e\u0627\u062a\u0645\u0629 \u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0645\u0628\u0643\u0631 \u0644\u0644\u0642\u0631\u0627\u0621\u0629","\u0645\u0631\u062d\u0644\u0629 \u0627\u0646\u062a\u0642\u0627\u0644\u064a\u0629 \u0648\u062a\u0648\u0637\u0626\u0629 \u0644\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0645\u0648\u0627\u0644\u064a\u0629 \u0627\u0644\u0645\u062a\u0645\u062b\u0644\u0629 \u0641\u064a \u0627\u0644\u0633\u0646\u062a\u064a\u0646 \u0627\u0644\u062e\u0627\u0645\u0633\u0629 \u0648\u0627\u0644\u0633\u0627\u062f\u0633\u0629","\u0628\u062f\u0627\u064a\u0629 \u0645\u062f\u062e\u0644 \u0627\u0644\u0627\u0633\u062a\u0645\u0627\u0639 \u0648\u0627\u0644\u062a\u062d\u062f\u062b","\u0645\u0631\u062d\u0644\u0629 \u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u0627\u0644\u0645\u0643\u062a\u0633\u0628\u0627\u062a \u0641\u0642\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b_R=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u062a\u0639\u062f \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0631\u0627\u0628\u0639\u0629 \u0645\u0646 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u060c \u0641\u064a \u0647\u0646\u062f\u0633\u0629 \u0645\u0646\u0627\u0647\u062c \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629:",B.av6,1,"\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0631\u0627\u0628\u0639\u0629 \u0645\u0631\u062d\u0644\u0629 \u0627\u0646\u062a\u0642\u0627\u0644\u064a\u0629 \u0648\u062a\u0648\u0637\u0626\u0629 \u0644\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0645\u0648\u0627\u0644\u064a\u0629 \u0627\u0644\u0645\u062a\u0645\u062b\u0644\u0629 \u0641\u064a \u0627\u0644\u0633\u0646\u062a\u064a\u0646 \u0627\u0644\u062e\u0627\u0645\u0633\u0629 \u0648\u0627\u0644\u0633\u0627\u062f\u0633\u0629.",u.L)
B.ahG=s(["\u0633\u062a \u0648\u062d\u062f\u0627\u062a \u062f\u0631\u0627\u0633\u064a\u0629 \u0645\u0648\u0632\u0639\u0629 \u0628\u0627\u0644\u062a\u0633\u0627\u0648\u064a \u0639\u0644\u0649 \u0627\u0644\u0623\u0633\u062f\u0648\u0633\u064a\u0646\u060c \u062e\u0645\u0633\u0629 \u0623\u0633\u0627\u0628\u064a\u0639 \u0644\u0643\u0644 \u0648\u062d\u062f\u0629","\u0623\u0631\u0628\u0639 \u0648\u062d\u062f\u0627\u062a \u062f\u0631\u0627\u0633\u064a\u0629\u060c \u0633\u062a\u0629 \u0623\u0633\u0627\u0628\u064a\u0639 \u0644\u0643\u0644 \u0648\u062d\u062f\u0629","\u062e\u0645\u0633 \u0648\u062d\u062f\u0627\u062a \u062f\u0631\u0627\u0633\u064a\u0629\u060c \u062e\u0645\u0633\u0629 \u0623\u0633\u0627\u0628\u064a\u0639 \u0644\u0643\u0644 \u0648\u062d\u062f\u0629","\u0633\u062a \u0648\u062d\u062f\u0627\u062a \u062f\u0631\u0627\u0633\u064a\u0629\u060c \u0623\u0631\u0628\u0639\u0629 \u0623\u0633\u0627\u0628\u064a\u0639 \u0644\u0643\u0644 \u0648\u062d\u062f\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aLw=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u064a\u0646\u062a\u0638\u0645 \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u0633\u0646\u0648\u064a \u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0628\u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u0633\u0627\u062f\u0633\u0629 \u0639\u0628\u0631:",B.ahG,0,"\u0648\u0631\u062f \u0641\u064a \u062f\u0644\u064a\u0644 \u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629: \u064a\u0646\u062a\u0638\u0645 \u0627\u0644\u0628\u0631\u0646\u0627\u0645\u062c \u0627\u0644\u0633\u0646\u0648\u064a \u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0639\u0628\u0631 \u0633\u062a \u0648\u062d\u062f\u0627\u062a \u062f\u0631\u0627\u0633\u064a\u0629 \u0645\u0648\u0632\u0639\u0629 \u0628\u0627\u0644\u062a\u0633\u0627\u0648\u064a \u0639\u0644\u0649 \u0627\u0644\u0623\u0633\u062f\u0648\u0633\u064a\u0646\u060c \u062a\u0636\u0645 \u0643\u0644 \u0648\u062d\u062f\u0629 \u062e\u0645\u0633\u0629 \u0623\u0633\u0627\u0628\u064a\u0639.",u.u)
B.Wx=s(["\u0627\u0633\u062a\u0636\u0645\u0627\u0631 \u0627\u0644\u0628\u0646\u064a\u0629 \u0623\u0648\u0644\u0627\u064b: \u0627\u0644\u0644\u063a\u0629 \u0623\u0633\u0628\u0642 \u0645\u0646 \u0627\u0644\u0642\u0648\u0627\u0639\u062f","\u0627\u0644\u062a\u0635\u0631\u064a\u062d \u0628\u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0642\u0628\u0644 \u0645\u0644\u0627\u062d\u0638\u0629 \u0627\u0644\u0644\u063a\u0629 \u0648\u0627\u0633\u062a\u0639\u0645\u0627\u0644\u0647\u0627","\u0625\u0644\u063a\u0627\u0621 \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0646\u0647\u0627\u0626\u064a\u0627\u064b \u0641\u064a \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629","\u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0642\u0648\u0627\u0639\u062f \u0645\u0646\u0641\u0635\u0644\u0629 \u0639\u0646 \u0627\u0644\u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0627\u0644\u0644\u063a\u0648\u064a","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aEP=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u0645\u0628\u062f\u0623 \xab\u0627\u0644\u0625\u0636\u0645\u0627\u0631 \u0648\u0627\u0644\u062a\u0635\u0631\u064a\u062d\xbb \u0641\u064a \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0638\u0648\u0627\u0647\u0631 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 \u064a\u0639\u0646\u064a:",B.Wx,0,"\u0645\u0628\u062f\u0623 \u0627\u0644\u0625\u0636\u0645\u0627\u0631 \u0648\u0627\u0644\u062a\u0635\u0631\u064a\u062d: \u0627\u0644\u0644\u063a\u0629 \u0623\u0633\u0628\u0642 \u0645\u0646 \u0627\u0644\u0642\u0648\u0627\u0639\u062f\u061b \u062a\u0633\u062a\u0636\u0645\u0631 \u0627\u0644\u0628\u0646\u064a\u0629 \u0623\u0648\u0644\u0627\u064b (\u0627\u0633\u062a\u0636\u0645\u0627\u0631 \u0627\u0644\u0628\u0646\u064a\u0629) \u062b\u0645 \u064a\u064f\u0635\u0631\u064e\u0651\u062d \u0628\u0627\u0644\u0642\u0627\u0639\u062f\u0629.",u.u)
