B.aY2=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u0645\u0628\u062f\u0623 \xab\u0627\u0644\u062a\u0643\u0627\u0645\u0644\xbb \u0641\u064a \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u064a\u062a\u062c\u0644\u0649 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649:",B.a89,1,"\u0635 10: \u0645\u0628\u062f\u0623 \u0627\u0644\u062a\u0643\u0627\u0645\u0644 \u064a\u062a\u062c\u0644\u0649 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u064a\u064a\u0646 \u0647\u0627\u0645\u064a\u0646: \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u062c\u0627\u0644 \u0627\u0644\u0630\u064a \u062a\u062a\u0645\u062d\u0648\u0631 \u062d\u0648\u0644\u0647 \u0645\u062e\u062a\u0644\u0641 \u062f\u0631\u0648\u0633 \u0627\u0644\u0648\u062d\u062f\u0629\u060c \u0648\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0628\u0646\u0627\u0621 \u0627\u0644\u0647\u064a\u0643\u0644\u064a \u0644\u0644\u062d\u0635\u0635 \u0627\u0644\u0645\u062e\u062a\u0644\u0641\u0629 \u0644\u0645\u0643\u0648\u0646\u0627\u062a \u0627\u0644\u0645\u0627\u062f\u0629.",u.u)
B.acX=s(["\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642\u060c \u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\u060c \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0631\u0643\u0632\u0629\u060c \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u062a\u0642\u0648\u064a\u0645 \u0648\u062f\u0639\u0645","\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642\u060c \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\u060c \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0631\u0643\u0632\u0629","\u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642\u060c \u062a\u0642\u0648\u064a\u0645 \u0648\u062f\u0639\u0645\u060c \u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a","\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642\u060c \u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\u060c \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0631\u0643\u0632\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aXy=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631 \u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u0639\u0644\u0645",null,"\u062a\u064f\u0646\u062c\u064e\u0632 \u0627\u0644\u062d\u0635\u0629 \u0645\u0646 \u0645\u0643\u0648\u0651\u0646 \u0627\u0644\u0642\u0631\u0627\u0621\u0629 \u0628\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0623\u0648\u0644 (\u0627\u0644\u0648\u0639\u064a \u0627\u0644\u0635\u0648\u062a\u064a) \u0648\u0641\u0642 \u0627\u0644\u0633\u064a\u0631\u0648\u0631\u0629 \u0627\u0644\u062a\u0627\u0644\u064a\u0629:",B.acX,0,"\u0645\u0631\u0627\u062d\u0644 \u0645\u062d\u0648\u0631 \u0627\u0644\u0648\u0639\u064a \u0627\u0644\u0635\u0648\u062a\u064a \u0628\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0623\u0648\u0644: \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0627\u0646\u0637\u0644\u0627\u0642\u060c \u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\u060c \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0631\u0643\u0632\u0629\u060c \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u060c \u062a\u0642\u0648\u064a\u0645 \u0648\u062f\u0639\u0645.",null)
