B.aMk=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631",null,"\u062a\u0636\u0645 \u0627\u0644\u0648\u062b\u064a\u0642\u0629 \u0627\u0644\u062a\u064a \u064a\u0639\u062f\u0647\u0627 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0642\u0628\u0644\u064a\u0627 \u0642\u0628\u0644 \u0625\u0646\u062c\u0627\u0632 \u062d\u0635\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a: \u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u062f\u0631\u0633\u060c \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0627\u0644\u0633\u0627\u0628\u0642\u0629\u060c \u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u062a\u0639\u0644\u0645\u064a\u0629\u060c \u0627\u0644\u0627\u0645\u062a\u062f\u0627\u062f\u0627\u062a\u060c \u0627\u0644\u0645\u0639\u064a\u0646\u0627\u062a \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629 \u0648\u062a\u062f\u0628\u064a\u0631 \u0627\u0644\u062d\u0635\u0629. \u0645\u0627 \u0647\u064a \u0647\u0630\u0647 \u0627\u0644\u0648\u062b\u064a\u0642\u0629\u061f",B.a5L,1,"\u0628\u0637\u0627\u0642\u0629 \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0642\u0628\u0644\u064a (\u0627\u0644\u062e\u0637\u0627\u0637\u0629) \u062a\u062c\u0645\u0639 \u0627\u0644\u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0644\u0644\u062a\u062e\u0637\u064a\u0637 \u0644\u0644\u062f\u0631\u0633: \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0648\u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0648\u0627\u0644\u0623\u0647\u062f\u0627\u0641 \u0648\u0627\u0644\u0648\u0633\u0627\u0626\u0644 \u0648\u062a\u062f\u0628\u064a\u0631 \u0627\u0644\u062d\u0635\u0629. \u064a\u062d\u0631\u0631\u0647\u0627 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0642\u0628\u0644 \u0625\u0646\u062c\u0627\u0632 \u0627\u0644\u062f\u0631\u0633.",u.C)
B.aqr=s(["\u0645\u0628\u062f\u0623 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0627\u0644\u062e\u0637\u0627\u0628 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a \u0627\u0644\u0633\u0644\u064a\u0645","\u0645\u0628\u062f\u0623 \u0627\u0644\u062a\u0647\u064a\u0626\u0629 \u0627\u0644\u0644\u063a\u0648\u064a\u0629","\u0645\u0628\u062f\u0623 \u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a\u0629","\u0645\u0628\u062f\u0623 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u062a\u0643\u0648\u064a\u0646\u064a","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aFc=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631",null,"\u064a\u0633\u062a\u0647\u062f\u0641 \u062a\u062f\u0631\u064a\u0633 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u062d\u0644 \u0627\u0644\u0645\u0634\u0643\u0644\u0627\u062a \u0648\u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0639\u0646 \u0627\u0644\u0623\u0641\u0643\u0627\u0631 \u0628\u062e\u0637\u0648\u0627\u062a \u0645\u0646\u0647\u062c\u064a\u0629 \u0645\u0639 \u0625\u0643\u0633\u0627\u0628 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0646\u0645\u0627\u0630\u062c \u062a\u0641\u0633\u064a\u0631\u064a\u0629 \u0644\u0638\u0648\u0627\u0647\u0631 \u0645\u0646 \u0648\u0627\u0642\u0639\u0647. \u0647\u0630\u0627 \u0627\u0644\u0647\u062f\u0641 \u064a\u0646\u062f\u0631\u062c \u0636\u0645\u0646 \u0645\u0628\u062f\u0623:",B.aqr,2,"\u0645\u0628\u062f\u0623 \u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u064a\u0629 \u064a\u0647\u062f\u0641 \u0625\u0644\u0649 \u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0642\u062f\u0631\u0629 \u0639\u0644\u0649 \u062d\u0644 \u0627\u0644\u0645\u0634\u0643\u0644\u0627\u062a \u0648\u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0639\u0646 \u0627\u0644\u0623\u0641\u0643\u0627\u0631 \u0628\u062e\u0637\u0648\u0627\u062a \u0645\u0646\u0647\u062c\u064a\u0629 \u0645\u0639 \u0625\u0643\u0633\u0627\u0628 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0646\u0645\u0627\u0630\u062c \u062a\u0641\u0633\u064a\u0631\u064a\u0629\u060c \u0623\u064a \u062a\u062d\u0648\u064a\u0644 \u0648\u0636\u0639\u064a\u0627\u062a \u0645\u0646 \u0627\u0644\u0648\u0627\u0642\u0639 \u0625\u0644\u0649 \u062a\u0639\u0628\u064a\u0631 \u0631\u064a\u0627\u0636\u064a.","\u062a\u0642\u064a\u064a\u0645 \u0634\u0627\u0645\u0644 \u0641\u064a \u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a (\u0641\u0635\u064a\u062d)")
B.agN=s(["\u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0648\u0627\u0644\u062d\u0633\u0627\u0628 \u2013 \u0627\u0644\u0647\u0646\u062f\u0633\u0629 \u2013 \u0627\u0644\u0642\u064a\u0627\u0633 \u2013 \u062a\u0646\u0638\u064a\u0645 \u0648\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a","\u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0648\u0627\u0644\u062c\u0628\u0631 \u2013 \u0627\u0644\u0647\u0646\u062f\u0633\u0629 \u2013 \u0627\u0644\u0642\u064a\u0627\u0633 \u2013 \u0627\u0644\u0625\u062d\u0635\u0627\u0621","\u0627\u0644\u062d\u0633\u0627\u0628 \u2013 \u0627\u0644\u062c\u0628\u0631 \u2013 \u0627\u0644\u0647\u0646\u062f\u0633\u0629 \u2013 \u0627\u0644\u0627\u062d\u062a\u0645\u0627\u0644\u0627\u062a","\u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0648\u0627\u0644\u062d\u0633\u0627\u0628 \u2013 \u0627\u0644\u0647\u0646\u062f\u0633\u0629 \u2013 \u0627\u0644\u0646\u0645\u0630\u062c\u0629 \u2013 \u0627\u0644\u0625\u062d\u0635\u0627\u0621","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b2D=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631",null,"\u062a\u062a\u0648\u0632\u0639 \u0645\u062d\u062a\u0648\u064a\u0627\u062a \u0645\u0646\u0647\u0627\u062c \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a \u0648\u0641\u0642 \u0648\u062b\u064a\u0642\u0629 \u0627\u0644\u0645\u0646\u0647\u0627\u062c (\u0627\u0644\u0635\u064a\u063a\u0629 \u0627\u0644\u0646\u0647\u0627\u0626\u064a\u0629 2021) \u0639\u0644\u0649 \u0623\u0631\u0628\u0639\u0629 \u0645\u062c\u0627\u0644\u0627\u062a\u060c \u0647\u064a:",B.agN,0,"\u062a\u0634\u0645\u0644 \u0645\u062c\u0627\u0644\u0627\u062a \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a: \u0627\u0644\u0623\u0639\u062f\u0627\u062f \u0648\u0627\u0644\u062d\u0633\u0627\u0628\u060c \u0627\u0644\u0647\u0646\u062f\u0633\u0629\u060c \u0627\u0644\u0642\u064a\u0627\u0633\u060c \u0648\u062a\u0646\u0638\u064a\u0645 \u0648\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a\u060c \u0648\u064a\u0628\u0642\u0649 \u062d\u0644 \u0627\u0644\u0645\u0633\u0627\u0626\u0644 \u0645\u062c\u0627\u0644\u0627 \u0645\u0646\u062f\u0645\u062c\u0627 \u0636\u0645\u0646 \u0647\u0630\u0647 \u0627\u0644\u0645\u062c\u0627\u0644\u0627\u062a.",u.C)
B.ae_=s(["\u0623\u0631\u0628\u0639 \u062d\u0635\u0635","\u062e\u0645\u0633 \u062d\u0635\u0635","\u062b\u0644\u0627\u062b \u062d\u0635\u0635","\u0633\u062a \u062d\u0635\u0635","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aFe=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631",null,"\u0643\u0645 \u0639\u062f\u062f \u0627\u0644\u062d\u0635\u0635 \u0627\u0644\u0623\u0633\u0628\u0648\u0639\u064a\u0629 \u0627\u0644\u0645\u062e\u0635\u0635\u0629 \u0644\u0645\u0627\u062f\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a \u0648\u0641\u0642 \u0628\u0631\u0645\u062c\u0629 \u0648\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a\u061f",B.ae_,1,"\u0639\u062f\u062f \u0627\u0644\u062d\u0635\u0635 \u0627\u0644\u0623\u0633\u0628\u0648\u0639\u064a\u0629 \u0627\u0644\u0645\u062e\u0635\u0635\u0629 \u0644\u0645\u0627\u062f\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0647\u0648 \u062e\u0645\u0633 \u062d\u0635\u0635\u060c \u062a\u0648\u0632\u0639 \u062e\u0644\u0627\u0644 \u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u0648\u0627\u062d\u062f \u0648\u0641\u0642 \u0627\u0644\u062a\u0642\u0633\u064a\u0645 \u0627\u0644\u0632\u0645\u0646\u064a \u0627\u0644\u0645\u0642\u0631\u0631 \u0641\u064a \u0648\u062b\u064a\u0642\u0629 \u0627\u0644\u0645\u0646\u0647\u0627\u062c.",u.C)
B.atz=s(["\u0628\u0646\u0627\u0621 \u2013 \u062a\u0631\u064a\u064a\u0636 \u2013 \u062a\u0631\u064a\u064a\u0636 \u2013 \u062a\u0642\u0648\u064a\u0645 \u2013 \u062f\u0639\u0645","\u0628\u0646\u0627\u0621 \u0648\u062a\u0631\u064a\u064a\u0636 \u2013 \u062a\u0642\u0648\u064a\u0645 \u0648\u062f\u0639\u0645 \u2013 \u0628\u0646\u0627\u0621 \u0648\u062a\u0631\u064a\u064a\u0636 \u2013 \u062a\u0642\u0648\u064a\u0645 \u0648\u062f\u0639\u0645 \u2013 \u062f\u0639\u0645 \u062f\u0631\u0633\u064a","\u062a\u0642\u0648\u064a\u0645 \u2013 \u0645\u0639\u0627\u0644\u062c\u0629 \u2013 \u062f\u0639\u0645 \u2013 \u062a\u062b\u0628\u064a\u062a \u2013 \u0625\u063a\u0646\u0627\u0621","\u062a\u0642\u0648\u064a\u0645 (\u0631\u0627\u0626\u0632) \u2013 \u062f\u0639\u0645 \u0648\u062a\u062b\u0628\u064a\u062a \u2013 \u062f\u0639\u0645 \u0648\u062a\u062b\u0628\u064a\u062a \u2013 \u062a\u0642\u0648\u064a\u0645 \u0627\u0644\u0623\u062b\u0631 \u2013 \u0645\u0639\u0627\u0644\u062c\u0629 \u0648\u0625\u063a\u0646\u0627\u0621","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aWQ=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631",null,"\u062e\u0644\u0627\u0644 \u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0630\u064a \u064a\u0644\u064a \u0625\u0646\u062c\u0627\u0632 \u0627\u0644\u0648\u062d\u062f\u0629\u060c \u062a\u062a\u0648\u0632\u0639 \u0627\u0644\u062d\u0635\u0635 \u0627\u0644\u062e\u0645\u0633 \u0644\u0645\u0627\u062f\u0629 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0639\u0644\u0649 \u0627\u0644\u0634\u0643\u0644 \u0627\u0644\u062a\u0627\u0644\u064a:",B.atz,3,"\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u064a\u0634\u0645\u0644: \u062d\u0635\u0629 \u062a\u0642\u0648\u064a\u0645 (\u0631\u0627\u0626\u0632) \u062b\u0645 \u062d\u0635\u062a\u064a\u0646 \u0644\u0644\u062f\u0639\u0645 \u0648\u0627\u0644\u062a\u062b\u0628\u064a\u062a \u0648\u0627\u0644\u062a\u0648\u0644\u064a\u0641\u060c \u0641\u062d\u0635\u0629 \u0644\u062a\u0642\u0648\u064a\u0645 \u0623\u062b\u0631 \u0627\u0644\u062f\u0639\u0645\u060c \u0648\u0623\u062e\u064a\u0631\u0627 \u062d\u0635\u0629 \u0644\u0644\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0631\u0643\u0632\u0629 \u0648\u0625\u063a\u0646\u0627\u0621 \u0627\u0644\u062a\u0639\u0644\u0645\u0627\u062a.",u.C)
B.avK=s(["\u0648\u0636\u0639\u064a\u0629 \u062a\u062d\u0645\u0644 \u0645\u0634\u0643\u0644\u0629 \u0630\u0627\u062a \u062f\u0644\u0627\u0644\u0629\u060c \u0645\u0633\u062a\u0645\u062f\u0629 \u0645\u0646 \u0627\u0644\u0648\u0627\u0642\u0639 \u0627\u0644\u0645\u0639\u064a\u0634\u060c \u062a\u062d\u0641\u0632 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0630\u0627\u062a\u064a \u0648\u062a\u0633\u0645\u062d \u0628\u0627\u0644\u0628\u062d\u062b \u0648\u0627\u0644\u0627\u0633\u062a\u062f\u0644\u0627\u0644","\u0648\u0636\u0639\u064a\u0629 \u064a\u0639\u0631\u0636 \u0641\u064a\u0647\u0627 \u0627\u0644\u0623\u0633\u062a\u0627\u0630 \u0627\u0644\u062d\u0644 \u0627\u0644\u062c\u0627\u0647\u0632 \u0645\u0646\u0630 \u0627\u0644\u0628\u062f\u0627\u064a\u0629","\u0648\u0636\u0639\u064a\u0629 \u0644\u0627 \u062a\u0633\u062a\u062c\u064a\u0628 \u0644\u062d\u0627\u062c\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0648\u0644\u0627 \u0644\u062e\u0635\u0627\u0626\u0635\u0647\u0645 \u0627\u0644\u0646\u0641\u0633\u064a\u0629 \u0648\u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629","\u0648\u0636\u0639\u064a\u0629 \u062a\u0647\u062f\u0641 \u0623\u0633\u0627\u0633\u0627 \u0625\u0644\u0649 \u062d\u0641\u0638 \u0627\u0644\u062a\u0639\u0627\u0631\u064a\u0641 \u0648\u0627\u0644\u0642\u0648\u0627\u0639\u062f","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aWy=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631",null,"\u0623\u064a \u0645\u0646 \u0627\u0644\u062e\u0635\u0627\u0626\u0635 \u0627\u0644\u062a\u0627\u0644\u064a\u0629 \u062a\u0639\u062f \u0645\u0646 \u062e\u0635\u0627\u0626\u0635 \u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0634\u0643\u0644\u0629 \u0627\u0644\u062a\u064a \u064a\u0646\u0637\u0644\u0642 \u0645\u0646\u0647\u0627 \u062a\u062f\u0628\u064a\u0631 \u062f\u0631\u0633 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a\u061f",B.avK,0,"\u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0645\u0634\u0643\u0644\u0629 \u0648\u0636\u0639\u064a\u0629 \u062a\u062d\u0645\u0644 \u0645\u0634\u0643\u0644\u0629 \u0630\u0627\u062a \u062f\u0644\u0627\u0644\u0629\u060c \u0645\u0633\u062a\u0645\u062f\u0629 \u0645\u0646 \u0627\u0644\u0648\u0627\u0642\u0639 \u0627\u0644\u0645\u0639\u064a\u0634\u060c \u062a\u0628\u062f\u0623 \u0628\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u0641\u0639\u0644\u060c \u0648\u062a\u062d\u0641\u0632 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0630\u0627\u062a\u064a \u0648\u062a\u0633\u0645\u062d \u0628\u0627\u0644\u062a\u0646\u0638\u064a\u0645 \u0648\u0627\u0644\u0628\u062d\u062b \u0648\u0627\u0644\u0627\u0633\u062a\u062f\u0644\u0627\u0644 \u0648\u062a\u0642\u0628\u0644 \u0627\u0644\u0623\u062e\u0637\u0627\u0621.","\u062a\u0642\u064a\u064a\u0645 \u0634\u0627\u0645\u0644 \u0641\u064a \u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a (\u0641\u0635\u064a\u062d)")
B.ao2=s(["\u0627\u0644\u0641\u0639\u0644 \u2013 \u0627\u0644\u0635\u064a\u0627\u063a\u0629 \u2013 \u0627\u0644\u062a\u062f\u0627\u0648\u0644 \u2013 \u0627\u0644\u0645\u0623\u0633\u0633\u0629 \u2013 \u0627\u0644\u062a\u0642\u0648\u064a\u0645","\u0627\u0644\u062a\u0639\u0627\u0642\u062f \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u2013 \u0627\u0644\u0635\u064a\u0627\u063a\u0629 \u2013 \u0627\u0644\u0641\u0639\u0644 \u2013 \u0627\u0644\u062a\u062f\u0627\u0648\u0644 \u2013 \u0627\u0644\u0645\u0623\u0633\u0633\u0629","\u0627\u0644\u062a\u0639\u0627\u0642\u062f \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u2013 \u0627\u0644\u0641\u0639\u0644 \u2013 \u0627\u0644\u0635\u064a\u0627\u063a\u0629 \u2013 \u0627\u0644\u062a\u062f\u0627\u0648\u0644 \u2013 \u0627\u0644\u0645\u0623\u0633\u0633\u0629","\u0627\u0644\u0641\u0639\u0644 \u2013 \u0627\u0644\u062a\u0639\u0627\u0642\u062f \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a \u2013 \u0627\u0644\u062a\u062f\u0627\u0648\u0644 \u2013 \u0627\u0644\u0635\u064a\u0627\u063a\u0629 \u2013 \u0627\u0644\u0645\u0623\u0633\u0633\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aPL=new A.a("\u0627\u0644\u062a\u062e\u0637\u064a\u0637 \u0648\u0627\u0644\u062a\u062f\u0628\u064a\u0631",null,"\u0645\u0627 \u0627\u0644\u062a\u0631\u062a\u064a\u0628 \u0627\u0644\u0635\u062d\u064a\u062d \u0644\u0644\u0645\u0631\u0627\u062d\u0644 \u0627\u0644\u0645\u0646\u0647\u062c\u064a\u0629 \u0627\u0644\u062e\u0645\u0633 \u0644\u062a\u062f\u0628\u064a\u0631 \u062f\u0631\u0633 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a \u0648\u0641\u0642 \u0645\u0633\u0627\u0631 \u0627\u0644\u0648\u0636\u0639\u064a\u0629\u061f",B.ao2,2,"\u062a\u0645\u0631 \u0627\u0644\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u0629 \u0628\u062e\u0645\u0633 \u0645\u0631\u0627\u062d\u0644 \u0645\u062a\u062a\u0627\u0628\u0639\u0629: \u0627\u0644\u062a\u0639\u0627\u0642\u062f \u0627\u0644\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643\u064a\u060c \u062b\u0645 \u0627\u0644\u0641\u0639\u0644\u060c \u0641\u0627\u0644\u0635\u064a\u0627\u063a\u0629\u060c \u062b\u0645 \u0627\u0644\u062a\u062f\u0627\u0648\u0644\u060c \u0648\u0623\u062e\u064a\u0631\u0627 \u0627\u0644\u0645\u0623\u0633\u0633\u0629 (\u0627\u0644\u062e\u0644\u0627\u0635\u0629 \u0648\u0636\u0628\u0637 \u0627\u0644\u0645\u0635\u0637\u0644\u062d\u0627\u062a \u0648\u0627\u0644\u0631\u0645\u0648\u0632).","\u062a\u0642\u064a\u064a\u0645 \u0634\u0627\u0645\u0644 \u0641\u064a \u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0631\u064a\u0627\u0636\u064a\u0627\u062a (\u0641\u0635\u064a\u062d)")
B.abW=s(["\u0627\u0644\u0627\u0633\u062a\u0642\u0631\u0627\u0621","\u0627\u0644\u0627\u0633\u062a\u0646\u062a\u0627\u062c","\u0627\u0644\u062a\u0642\u062f\u064a\u0631 \u0648\u0627\u0644\u062a\u062e\u0645\u064a\u0646","\u0627\u0644\u062a\u0639\u0628\u064a\u0631 \u0628\u0627\u0644\u0631\u0645\u0648\u0632","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
