B.aC9={"\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629":0,"\u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0633\u062a\u0631\u0627\u062a\u064a\u062c\u064a\u0627\u062a \u0627\u0643\u062a\u0633\u0627\u0628 \u0627\u0644\u0641\u0647\u0645":1,"\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627":2,"\u0635\u0639\u0648\u0628\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0639\u0648\u0627\u0626\u0642\u0647":3,[u.G]:4,"\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0648\u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0627\u0646":5,"\u0627\u0644\u0625\u0635\u0644\u0627\u062d \u0627\u0644\u062a\u0631\u0628\u0648\u064a \u0648\u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629":6}
