B.ae4=s(["\u0645\u0627 \u064a\u062a\u0639\u0644\u0645\u0647 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u062f\u0627\u062e\u0644 \u0627\u0644\u0642\u0633\u0645 \u0648\u0645\u0627 \u064a\u062a\u0639\u0644\u0645\u0647 \u062e\u0627\u0631\u062c\u0647","\u0645\u0627 \u064a\u0645\u0643\u0646 \u0644\u0644\u0645\u062a\u0639\u0644\u0645 \u0625\u0646\u062c\u0627\u0632\u0647 \u0628\u0646\u0641\u0633\u0647 \u0648\u0645\u0627 \u064a\u062d\u0642\u0642\u0647 \u0628\u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0622\u062e\u0631\u064a\u0646","\u0627\u0644\u062a\u0645\u062b\u0644 \u0627\u0644\u0639\u0645\u0644\u064a \u0648\u0627\u0644\u062a\u0645\u062b\u0644 \u0627\u0644\u0631\u0645\u0632\u064a \u0644\u0644\u0645\u0639\u0631\u0641\u0629","\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0641\u0639\u0644\u064a \u0648\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0639\u0627\u0637\u0641\u064a \u0644\u0644\u0645\u062a\u0639\u0644\u0645","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b31=new A.a("\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629",null,"\u062a\u064f\u0639\u0631\u0641 \xab\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0642\u0631\u064a\u0628\xbb \u0639\u0646\u062f \u0641\u064a\u063a\u0648\u062a\u0633\u0643\u064a \u0628\u0623\u0646\u0647\u0627 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646:",B.ae4,1,"\u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0646\u0645\u0648 \u0627\u0644\u0642\u0631\u064a\u0628 (ZPD) \u0647\u064a \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646 \u0645\u0627 \u064a\u0641\u0639\u0644\u0647 \u0627\u0644\u0641\u0631\u062f \u0628\u0646\u0641\u0633\u0647 \u0648\u0645\u0627 \u064a\u0645\u0643\u0646\u0647 \u062a\u062d\u0642\u064a\u0642\u0647 \u0628\u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0623\u0642\u0631\u0627\u0646 \u0623\u0648 \u0627\u0644\u0645\u0639\u0644\u0645\u064a\u0646\u060c \u0648\u064a\u062d\u062f\u062b \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0623\u0645\u062b\u0644 \u0641\u064a\u0647\u0627 \u0639\u0628\u0631 \u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a.","\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0645\u0646 \u0625\u0639\u062f\u0627\u062f \u062a\u0648\u0641\u064a\u0642 \u0644\u062e\u0635\u0627\u0635")
B.ass=s(["\u0627\u0644\u0639\u0645\u0644\u064a\u060c \u0627\u0644\u0635\u0648\u0631\u0629 \u0627\u0644\u0630\u0647\u0646\u064a\u0629 (\u0627\u0644\u0623\u064a\u0642\u0648\u0646\u064a)\u060c \u0648\u0627\u0644\u0631\u0645\u0632\u064a","\u0627\u0644\u062d\u0633\u064a\u060c \u0627\u0644\u0627\u0646\u0641\u0639\u0627\u0644\u064a\u060c \u0648\u0627\u0644\u0639\u0642\u0644\u064a","\u0627\u0644\u0645\u062d\u0633\u0648\u0633\u060c \u0634\u0628\u0647 \u0627\u0644\u0645\u062d\u0633\u0648\u0633\u060c \u0648\u0627\u0644\u0645\u062c\u0631\u062f","\u0627\u0644\u0627\u0633\u062a\u0643\u0634\u0627\u0641\u064a\u060c \u0627\u0644\u062a\u0648\u062c\u064a\u0647\u064a\u060c \u0648\u0627\u0644\u062a\u0642\u0648\u064a\u0645\u064a","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b82=new A.a("\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629",null,"\u0642\u0633\u0651\u0645 \u0628\u0631\u0648\u0646\u0631 \u062a\u0645\u062b\u064a\u0644 \u0627\u0644\u0645\u0639\u0631\u0641\u0629 \u0625\u0644\u0649 \u062b\u0644\u0627\u062b\u0629 \u0623\u0646\u0645\u0627\u0637 \u0647\u064a:",B.ass,0,"\u0628\u0631\u0648\u0646\u0631 (\u0627\u0644\u0628\u0646\u0627\u0626\u064a\u0629 \u0627\u0644\u0625\u062f\u0631\u0627\u0643\u064a\u0629) \u062d\u062f\u062f \u0645\u0631\u0627\u062d\u0644 \u062a\u0645\u062b\u064a\u0644 \u0627\u0644\u0645\u0639\u0631\u0641\u0629: \u0627\u0644\u0646\u0645\u0637 \u0627\u0644\u0639\u0645\u0644\u064a\u060c \u062b\u0645 \u0627\u0644\u0635\u0648\u0631\u0629 \u0627\u0644\u0630\u0647\u0646\u064a\u0629\u060c \u062b\u0645 \u0627\u0644\u0646\u0645\u0637 \u0627\u0644\u0631\u0645\u0632\u064a.","\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0645\u0646 \u0625\u0639\u062f\u0627\u062f \u062a\u0648\u0641\u064a\u0642 \u0644\u062e\u0635\u0627\u0635")
B.a6V=s(["\u0627\u0644\u062d\u0641\u0638 \u0648\u0627\u0644\u0627\u0633\u062a\u0638\u0647\u0627\u0631 \u0648\u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a","\u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0629 \u0627\u0644\u0633\u0644\u0628\u064a\u0629 \u0644\u0644\u062f\u0631\u0633 \u0627\u0644\u0646\u0645\u0648\u0630\u062c\u064a","\u0627\u0644\u062a\u0639\u0644\u0645 \u0628\u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 (\u0627\u0644\u062a\u062c\u0631\u064a\u0628) \u0648\u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0645\u0639 \u0627\u0644\u0628\u064a\u0626\u0629","\u0627\u0644\u062a\u0644\u0642\u064a \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0644\u0644\u0645\u0639\u0627\u0631\u0641 \u0627\u0644\u062c\u0627\u0647\u0632\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aLv=new A.a("\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629",null,"\u064a\u0631\u0643\u0632 \u062c\u0648\u0646 \u062f\u064a\u0648\u064a \u0639\u0644\u0649 \u0623\u0646 \u0627\u0644\u062a\u0639\u0644\u0645 \u064a\u062d\u062f\u062b \u0628\u0634\u0643\u0644 \u0623\u0633\u0627\u0633\u064a \u0645\u0646 \u062e\u0644\u0627\u0644:",B.a6V,2,"\u062f\u064a\u0648\u064a \u0635\u0627\u062d\u0628 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u062a\u062c\u0631\u064a\u0628\u064a: \u0627\u0644\u062a\u0639\u0644\u0645 \u0628\u0627\u0644\u0646\u0634\u0627\u0637 \u0648\u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 (learning by doing) \u0645\u0646 \u062e\u0644\u0627\u0644 \u0627\u0644\u062a\u062c\u0631\u064a\u0628 \u0648\u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0645\u0639 \u0627\u0644\u0645\u062d\u064a\u0637.","\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0645\u0646 \u0625\u0639\u062f\u0627\u062f \u062a\u0648\u0641\u064a\u0642 \u0644\u062e\u0635\u0627\u0635")
B.acK=s(["\u0639\u0644\u0645 \u0642\u064a\u0627\u0633 \u0627\u0644\u0633\u0644\u0648\u0643 \u0648\u062a\u0642\u064a\u064a\u0645\u0647","\u0639\u0644\u0645 \u0646\u0641\u0633 \u0627\u0644\u0637\u0641\u0644 \u0648\u0637\u0631\u0642 \u0639\u0644\u0627\u062c\u0647","\u0642\u064a\u0627\u062f\u0629 \u0623\u0648 \u062a\u0648\u062c\u064a\u0647 \u0623\u0648 \u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0637\u0641\u0644","\u0639\u0644\u0645 \u062a\u0646\u0638\u064a\u0645 \u0627\u0644\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.b6C=new A.a("\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629",null,"\u062a\u062f\u0644 \u0643\u0644\u0645\u0629 \xab\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627\xbb \u0644\u063a\u0648\u064a\u0627\u064b (P\xe9dagogie) \u0639\u0644\u0649:",B.acK,2,"\u062a\u062a\u0643\u0648\u0646 \u0643\u0644\u0645\u0629 P\xe9dagogie \u0645\u0646 \xabp\xe9da\xbb (\u0637\u0641\u0644) \u0648\xabgogie\xbb (\u0642\u064a\u0627\u062f\u0629/\u062a\u0648\u062c\u064a\u0647)\u060c \u0623\u064a \u0642\u064a\u0627\u062f\u0629 \u0623\u0648 \u062a\u0648\u062c\u064a\u0647 \u0623\u0648 \u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0637\u0641\u0644.","\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627\u062a \u0627\u0644\u0648\u0638\u064a\u0641\u064a\u0629")
B.axW=s(["\u0623\u0637\u0641\u0627\u0644 \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0631\u0627\u0634\u062f\u064a\u0646 \u0643\u0645\u062c\u0627\u0644\u0627\u062a \u0645\u062d\u0627\u0631\u0628\u0629 \u0627\u0644\u0623\u0645\u064a\u0629 \u0648\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0639\u0627\u0644\u064a","\u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0641\u064a \u0648\u0636\u0639\u064a\u0629 \u0625\u0639\u0627\u0642\u0629","\u0627\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0641\u064a \u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0623\u0648\u0644\u064a","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aXT=new A.a("\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629",null,"\u0627\u0644\u0623\u0646\u062f\u0631\u0627\u063a\u0648\u062c\u064a\u0627 (Andragogie) \u0647\u064a \u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0645\u0648\u062c\u0647\u0629 \u0625\u0644\u0649:",B.axW,1,"Andragogie \u062a\u0639\u0646\u064a \u0642\u064a\u0627\u062f\u0629 \u0623\u0648 \u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0631\u0627\u0634\u062f (Andro = \u0631\u062c\u0644/\u0631\u0627\u0634\u062f)\u060c \u0648\u062a\u0633\u062a\u0639\u0645\u0644 \u0641\u064a \u0645\u062d\u0627\u0631\u0628\u0629 \u0627\u0644\u0623\u0645\u064a\u0629 \u0648\u0627\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0639\u0627\u0644\u064a \u0645\u0642\u0627\u0628\u0644 \u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627 \u0627\u0644\u0637\u0641\u0644.","\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627\u062a \u0627\u0644\u0648\u0638\u064a\u0641\u064a\u0629")
B.ax3=s(["\u0633\u0628\u0639 \u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627\u062a","\u062e\u0645\u0633 \u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627\u062a","\u062a\u0633\u0639 \u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627\u062a","\u062b\u0644\u0627\u062b \u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627\u062a","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aYr=new A.a("\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0645\u0642\u0627\u0631\u0628\u0627\u062a \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629",null,"\u0639\u062f\u062f \u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627\u062a \u0627\u0644\u0648\u0638\u064a\u0641\u064a\u0629 \u0627\u0644\u062a\u064a \u064a\u062a\u0628\u0646\u0627\u0647\u0627 \u0627\u0644\u0645\u0646\u0647\u0627\u062c \u0627\u0644\u0645\u063a\u0631\u0628\u064a \u0647\u0648:",B.ax3,0,"\u064a\u062a\u0628\u0646\u0649 \u0627\u0644\u0645\u0646\u0647\u0627\u062c \u0627\u0644\u0645\u063a\u0631\u0628\u064a \u0633\u0628\u0639 \u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627\u062a \u0648\u0638\u064a\u0641\u064a\u0629 (\u0627\u0644\u062e\u0637\u0623\u060c \u0627\u0644\u0645\u0634\u0631\u0648\u0639\u060c \u0627\u0644\u0644\u0639\u0628\u060c \u0627\u0644\u062a\u0639\u0627\u0642\u062f\u060c \u0627\u0644\u0648\u0636\u0639\u064a\u0629-\u0627\u0644\u0645\u0634\u0643\u0644\u060c \u0627\u0644\u0641\u0627\u0631\u0642\u064a\u0629\u060c \u0627\u0644\u0625\u062f\u0645\u0627\u062c...).","\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627\u062a \u0627\u0644\u0648\u0638\u064a\u0641\u064a\u0629")
