B.aoF=s(["\u062a\u062d\u062f\u064a\u062f \u0627\u0644\u0631\u0648\u0627\u062a\u0628 \u0648\u0627\u0644\u062a\u0639\u0648\u064a\u0636\u0627\u062a \u0627\u0644\u0645\u0647\u0646\u064a\u0629","\u062a\u0646\u0638\u064a\u0645 \u0627\u0644\u0627\u0645\u062a\u062d\u0627\u0646\u0627\u062a \u0627\u0644\u0648\u0637\u0646\u064a\u0629 \u0627\u0644\u0645\u0648\u062d\u062f\u0629","\u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u0643\u062a\u0628 \u0627\u0644\u0645\u062f\u0631\u0633\u064a\u0629","\u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u0633\u0644\u0648\u0643 \u0641\u064a \u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062a \u0627\u0644\u0645\u0647\u0646\u064a\u0629 \u0645\u0639 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aZh=new A.a("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u062a\u064f\u0639\u0646\u0649 \u0623\u062e\u0644\u0627\u0642\u064a\u0627\u062a \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0633\u064a\u0643\u0648\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629 (\u0623\u062e\u0644\u0627\u0642\u064a\u0627\u062a \u0627\u0644\u0627\u0633\u062a\u0634\u0627\u0631\u0629 \u0641\u064a \u0627\u0644\u0645\u062c\u0627\u0644 \u0627\u0644\u062a\u0631\u0628\u0648\u064a) \u0628\u0640:",B.aoF,3,"\u0623\u062e\u0644\u0627\u0642\u064a\u0627\u062a \u0645\u0645\u0627\u0631\u0633\u0629 \u0623\u064a \u0645\u0647\u0646\u0629 \u062a\u0639\u0646\u064a \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0645\u0628\u0627\u062f\u0626 \u0627\u0644\u0633\u0644\u0648\u0643 \u0641\u064a \u0627\u0644\u0639\u0644\u0627\u0642\u0627\u062a \u0645\u0639 \u0627\u0644\u0622\u062e\u0631\u064a\u0646 \u0641\u064a \u0625\u0637\u0627\u0631 \u0627\u0644\u0645\u0647\u0646\u0629\u060c \u0648\u0645\u0646\u0647\u0627 \u0627\u0644\u0627\u0633\u062a\u0634\u0627\u0631\u0629 \u0641\u064a \u0627\u0644\u0645\u062c\u0627\u0644 \u0627\u0644\u062a\u0631\u0628\u0648\u064a.","\u0636\u0648\u0627\u0628\u0637 \u0648\u0623\u062e\u0644\u0627\u0642\u064a\u0627\u062a \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0633\u064a\u0643\u0648\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629")
B.ar3=s(["\u0648\u0636\u0639 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631\u0627\u062a \u0627\u0644\u0625\u0634\u0647\u0627\u062f\u064a\u0629 \u0648\u062a\u0635\u062d\u064a\u062d\u0647\u0627","\u0627\u0644\u0625\u0639\u0644\u0627\u0645 \u0627\u0644\u0645\u062f\u0631\u0633\u064a \u0648\u0627\u0644\u0645\u0647\u0646\u064a \u0648\u0627\u0644\u0642\u064a\u0627\u0645 \u0628\u0627\u0644\u0645\u0642\u0627\u0628\u0644\u0627\u062a \u0648\u0627\u0644\u0641\u062d\u0648\u0635 \u0627\u0644\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0629","\u062a\u0633\u064a\u064a\u0631 \u0627\u0644\u0645\u0635\u0627\u0644\u062d \u0627\u0644\u0645\u0627\u0644\u064a\u0629 \u0644\u0644\u0645\u0624\u0633\u0633\u0629","\u062a\u0646\u0638\u064a\u0645 \u0627\u0644\u062d\u0635\u0635 \u0627\u0644\u0623\u0633\u0628\u0648\u0639\u064a\u0629 \u0644\u0644\u0623\u0633\u0627\u062a\u0630\u0629","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aYM=new A.a("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u0645\u0646 \u0645\u0647\u0627\u0645 \u0627\u0644\u0645\u0633\u062a\u0634\u0627\u0631\u064a\u0646 \u0641\u064a \u0627\u0644\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u062a\u0631\u0628\u0648\u064a:",B.ar3,1,"\u0645\u0646 \u0645\u0647\u0627\u0645 \u0627\u0644\u0645\u0633\u062a\u0634\u0627\u0631\u064a\u0646: \u0627\u0644\u0625\u0639\u0644\u0627\u0645 \u0627\u0644\u0645\u062f\u0631\u0633\u064a \u0648\u0627\u0644\u0645\u0647\u0646\u064a\u060c \u062a\u062d\u064a\u064a\u0646 \u0627\u0644\u0645\u0639\u0637\u064a\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0642\u0629 \u0628\u0627\u0644\u0622\u0641\u0627\u0642 \u0627\u0644\u062a\u0639\u0644\u064a\u0645\u064a\u0629\u060c \u062f\u0631\u0627\u0633\u0629 \u0627\u0644\u0645\u0644\u0641\u0627\u062a\u060c \u0627\u0644\u0645\u0642\u0627\u0628\u0644\u0627\u062a \u0648\u0627\u0644\u0641\u062d\u0648\u0635 \u0627\u0644\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0629\u060c \u0648\u0627\u0644\u0645\u0648\u0627\u0643\u0628\u0629 \u0641\u064a \u0628\u0646\u0627\u0621 \u0627\u0644\u0645\u0634\u0627\u0631\u064a\u0639 \u0627\u0644\u0634\u062e\u0635\u064a\u0629.","\u0636\u0648\u0627\u0628\u0637 \u0648\u0623\u062e\u0644\u0627\u0642\u064a\u0627\u062a \u0627\u0644\u0645\u0645\u0627\u0631\u0633\u0629 \u0627\u0644\u0633\u064a\u0643\u0648\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0629")
B.as4=s(["\u062e\u0627\u0631\u062c\u064a\u0629 \u062a\u062d\u0631\u0643\u0647\u0627 \u0627\u0644\u0645\u062b\u064a\u0631\u0627\u062a \u0648\u0627\u0644\u062a\u0639\u0632\u064a\u0632\u0627\u062a","\u062f\u0627\u062e\u0644\u064a\u0629 \u062a\u0646\u0628\u062b\u0642 \u0645\u0646 \u0625\u062f\u0631\u0627\u0643 \u0627\u0644\u0645\u0639\u0646\u0649","\u0648\u062c\u062f\u0627\u0646\u064a\u0629 \u0645\u0631\u062a\u0628\u0637\u0629 \u0628\u0627\u0644\u0645\u0634\u0627\u0639\u0631","\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629 \u0645\u0631\u062a\u0628\u0637\u0629 \u0628\u0627\u0644\u062a\u0641\u0627\u0639\u0644 \u0645\u0639 \u0627\u0644\u0623\u0642\u0631\u0627\u0646","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aPj=new A.a("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u062a\u0648\u0635\u0641 \u0627\u0644\u062f\u0627\u0641\u0639\u064a\u0629 \u0641\u064a \u0627\u0644\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0633\u0644\u0648\u0643\u064a\u0629 \u0628\u0623\u0646\u0647\u0627:",B.as4,0,"\u0641\u064a \u0627\u0644\u0633\u0644\u0648\u0643\u064a\u0629 \u0627\u0644\u062f\u0627\u0641\u0639\u064a\u0629 \u062e\u0627\u0631\u062c\u064a\u0629: \u0645\u0627 \u064a\u062d\u0641\u0632 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0647\u0648 \u0627\u0644\u0645\u062b\u064a\u0631 \u0627\u0644\u062e\u0627\u0631\u062c\u064a \u0648\u0627\u0644\u062a\u0639\u0632\u064a\u0632\u060c \u062e\u0644\u0627\u0641\u0627\u064b \u0644\u0644\u062c\u0634\u0637\u0627\u0644\u062a\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u0631\u0649 \u0627\u0644\u062d\u0648\u0627\u0641\u0632 \u062f\u0627\u062e\u0644\u064a\u0629.","\u0646\u0638\u0631\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645")
B.a6p=s(["\u0627\u0644\u0646\u0638\u0645 \u0627\u0644\u0633\u064a\u0627\u0633\u064a\u0629 \u0644\u0644\u062f\u0648\u0644","\u0627\u0644\u0628\u0646\u0649 \u0627\u0644\u0627\u0642\u062a\u0635\u0627\u062f\u064a\u0629 \u0644\u0644\u0645\u062c\u062a\u0645\u0639","\u0633\u0644\u0648\u0643 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u0638\u0648\u0627\u0647\u0631 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629 \u0641\u064a \u0648\u0636\u0639\u064a\u0627\u062a \u0627\u0644\u062a\u0639\u0644\u0645","\u0627\u0644\u062a\u0646\u0638\u064a\u0645 \u0627\u0644\u0625\u062f\u0627\u0631\u064a \u0644\u0644\u0645\u0624\u0633\u0633\u0627\u062a","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
B.aFy=new A.a("\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627",null,"\u062a\u064f\u0639\u0646\u0649 \u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0623\u0633\u0627\u0633\u0627\u064b \u0628\u062f\u0631\u0627\u0633\u0629:",B.a6p,2,"\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u062a\u062f\u0631\u0633 \u0633\u0644\u0648\u0643 \u0627\u0644\u0645\u062a\u0639\u0644\u0645 \u0648\u0638\u0648\u0627\u0647\u0631 \u0627\u0644\u062a\u0639\u0644\u0645 \u0648\u0627\u0644\u062a\u062f\u0631\u064a\u0633 \u0648\u0627\u0644\u062a\u0642\u0648\u064a\u0645 \u0645\u0646 \u0645\u0646\u0638\u0648\u0631 \u0646\u0641\u0633\u064a\u060c \u0648\u062a\u062a\u0642\u0627\u0637\u0639 \u0645\u0639 \u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u0646\u0645\u0648 \u0648\u0627\u0644\u062a\u0639\u0644\u0645.","\u0633\u064a\u0643\u0648\u0644\u0648\u062c\u064a\u0627 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u062a\u0642\u0627\u0637\u0639\u0627\u062a\u0647\u0627")
B.aag=s(["\u0641\u0631\u0636 \u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u0635\u0627\u0631\u0645 \u0639\u0644\u0649 \u0627\u0644\u062a\u0644\u0627\u0645\u064a\u0630 \u0637\u0648\u0627\u0644 \u0627\u0644\u062d\u0635\u0629","\u0625\u0644\u063a\u0627\u0621 \u0627\u0644\u062d\u0631\u064a\u0629 \u0627\u0644\u0643\u0627\u0645\u0644\u0629 \u062f\u0627\u062e\u0644 \u0627\u0644\u0641\u0635\u0644","\u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0639\u0642\u0648\u0628\u0627\u062a \u0644\u0643\u0644 \u062e\u0637\u0623","\u0627\u0644\u0645\u062d\u0627\u0641\u0638\u0629 \u0639\u0644\u0649 \u062d\u062f \u0645\u0639\u0642\u0648\u0644 \u0645\u0646 \u0627\u0644\u0646\u0638\u0627\u0645 \u062f\u0648\u0646 \u0625\u0641\u0631\u0627\u0637 \u0623\u0648 \u062a\u0641\u0631\u064a\u0637","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
