B.aSG=new A.a("\u062f\u064a\u062f\u0627\u0643\u062a\u064a\u0643 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a",null,"\u0623\u064a \u0645\u0646 \u0627\u0644\u0622\u062a\u064a \u064a\u0639\u062f \u0645\u0646 \u0645\u0631\u062a\u0643\u0632\u0627\u062a \u0645\u0646\u0647\u0627\u062c \u0645\u0627\u062f\u0629 \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a \u0648\u0641\u0642 \u0627\u0644\u0645\u0646\u0647\u0627\u062c \u0627\u0644\u062f\u0631\u0627\u0633\u064a \u0644\u0644\u062a\u0639\u0644\u064a\u0645 \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u061f",B.a3m,0,"\u0645\u0631\u062a\u0643\u0632\u0627\u062a \u0645\u0646\u0647\u0627\u062c \u0627\u0644\u0646\u0634\u0627\u0637 \u0627\u0644\u0639\u0644\u0645\u064a \u0647\u064a \u0645\u0647\u0627\u0631\u0627\u062a \u0627\u0644\u0642\u0631\u0646 \u0627\u0644\u062d\u0627\u062f\u064a \u0648\u0627\u0644\u0639\u0634\u0631\u064a\u0646 \u0648\u0627\u0644\u062b\u0642\u0627\u0641\u0629 \u0627\u0644\u0639\u0644\u0645\u064a\u0629 \u0648\u0623\u0647\u062f\u0627\u0641 \u0627\u0644\u062a\u0646\u0645\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u062f\u0627\u0645\u0629 \u0648\u0627\u0644\u062a\u0647\u064a\u0626\u0629 \u0627\u0644\u0644\u063a\u0648\u064a\u0629 (\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0627\u0644\u0644\u063a\u0648\u064a).",u.j)
B.ana=s(["\u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0626\u064a\u0629 \u0645\u0646\u0630 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0623\u0648\u0644","\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u064a\u0646 \u0627\u0644\u062e\u0627\u0645\u0633 \u0648\u0627\u0644\u0633\u0627\u062f\u0633 \u0627\u0628\u062a\u062f\u0627\u0626\u064a","\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u064a\u0646 \u0627\u0644\u0623\u0648\u0644 \u0648\u0627\u0644\u062b\u0627\u0646\u064a \u0641\u0642\u0637","\u0627\u0644\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u064a\u0629 \u062d\u0635\u0631\u064a\u0627","\u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u062c\u0648\u0628\u0629 \u0627\u0644\u0645\u0642\u062a\u0631\u062d\u0629 \u0623\u0639\u0644\u0627\u0647 \u062e\u0627\u0637\u0626\u0629."],t.s)
