B.aKi=new A.a("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,'\u0645\u0646 \u0623\u0637\u0644\u0642 \u0639\u0644\u0649 \u0627\u0644\u0639\u0642\u0644 \u062a\u0633\u0645\u064a\u0629 "\u0627\u0644\u0639\u0644\u0628\u0629 \u0627\u0644\u0633\u0648\u062f\u0627\u0621" \u0636\u0645\u0646 \u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0633\u0644\u0648\u0643\u064a\u0629\u061f',B.arN,2,"\u0627\u0644\u0648\u0627\u0637\u0633\u0648\u0646 (1878-1958) \u0627\u0644\u0645\u0624\u0633\u0633 \u0627\u0644\u062d\u0642\u064a\u0642\u064a \u0644\u0644\u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0633\u0644\u0648\u0643\u064a\u0629\u060c \u0643\u0627\u0646 \u064a\u0633\u0645\u064a \u0627\u0644\u0639\u0642\u0644 \u0628\u0627\u0644\u0639\u0644\u0628\u0629 \u0627\u0644\u0633\u0648\u062f\u0627\u0621 \u0644\u0623\u0646\u0647 \u0644\u0627 \u064a\u0645\u0643\u0646 \u0631\u0635\u062f\u0647 \u0648\u0645\u0644\u0627\u062d\u0638\u062a\u0647 \u0645\u0628\u0627\u0634\u0631\u0629.",null)
