B.b_1=new A.a("\u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629","\u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0623\u0648\u0644",'\u0645\u0646 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062f\u0627\u0644\u0629 \u0639\u0644\u0649 "\u0627\u0644\u0648\u0639\u064a \u0627\u0644\u0635\u0648\u062a\u064a" \u0644\u062f\u0649 \u062a\u0644\u0645\u064a\u0630 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0623\u0648\u0644:',B.axt,1,"\u0627\u0644\u0648\u0639\u064a \u0627\u0644\u0635\u0648\u062a\u064a \u064a\u0634\u0645\u0644: \u062a\u062c\u0632\u0626\u0629 \u0627\u0644\u0643\u0644\u0645\u0627\u062a \u0625\u0644\u0649 \u0645\u0642\u0627\u0637\u0639 \u0635\u0648\u062a\u064a\u0629\u060c \u062a\u0645\u064a\u064a\u0632 \u0627\u0644\u0648\u062d\u062f\u0627\u062a \u0627\u0644\u0635\u0648\u062a\u064a\u0629\u060c \u062a\u0639\u0631\u0641 \u0635\u0648\u062a \u0645\u062d\u062f\u062f \u0641\u064a \u0643\u0644\u0645\u0627\u062a \u0645\u062e\u062a\u0644\u0641\u0629\u060c \u062a\u0639\u0648\u064a\u0636 \u0648\u062d\u062f\u0629 \u0635\u0648\u062a\u064a\u0629 \u0628\u0623\u062e\u0631\u0649 \u0644\u062a\u0634\u0643\u064a\u0644 \u0643\u0644\u0645\u0629 \u062c\u062f\u064a\u062f\u0629.",null)
B.aqs=s(["\u0628\u0631\u0648\u0646\u0631","\u0623\u0648\u0632\u0648\u0628\u0644 (Ausubel)","\u0633\u0643\u064a\u0646\u0631","\u0628\u064a\u0627\u062c\u064a"],t.s)
B.b_9=new A.a("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"\u0635\u0627\u062d\u0628 \u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u062a\u0639\u0644\u0645 \u0627\u0644\u0644\u0641\u0638\u064a \u0627\u0644\u0645\u0639\u0631\u0641\u064a \u0647\u0648:",B.aqs,1,"\u0623\u0648\u0632\u0648\u0628\u0644 \u0647\u0648 \u0645\u0646 \u062d\u0627\u0648\u0644 \u062a\u0641\u0633\u064a\u0631 \u0643\u064a\u0641\u064a\u0629 \u062a\u0639\u0644\u0645 \u0627\u0644\u0645\u0627\u062f\u0629 \u0627\u0644\u0644\u0641\u0638\u064a\u0629\u060c \u062d\u064a\u062b \u064a\u062a\u0645 \u062a\u0642\u062f\u064a\u0645 \u0623\u0641\u0643\u0627\u0631 \u0645\u0646\u0638\u0645\u0629 \u0644\u0644\u0645\u062a\u0639\u0644\u0645\u064a\u0646 \u0645\u0646\u0630 \u0627\u0644\u0628\u062f\u0621 \u0644\u062a\u0648\u062c\u064a\u0647\u0647\u0645 \u0628\u062f\u0644 \u0627\u0644\u0628\u062d\u062b \u0639\u0646\u0647\u0627 \u0623\u0648 \u0627\u0643\u062a\u0634\u0627\u0641\u0647\u0627.",null)
B.ahD=s(["\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0625\u0634\u0631\u0627\u0637 \u0627\u0644\u0625\u062c\u0631\u0627\u0626\u064a","\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629 \u0648\u0627\u0644\u062e\u0637\u0623","\u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0625\u0634\u0631\u0627\u0637 \u0627\u0644\u0643\u0644\u0627\u0633\u064a\u0643\u064a","\u0646\u0638\u0631\u064a\u0629 \u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a"],t.s)
B.b_O=new A.a("\u0639\u0644\u0648\u0645 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u062f\u0627\u063a\u0648\u062c\u064a\u0627",null,"\u064a\u0639\u062a\u0628\u0631 \u0627\u0644\u0639\u0627\u0644\u0645 \u0627\u0644\u0631\u0648\u0633\u064a \u0625\u064a\u0641\u0627\u0646 \u0628\u0627\u0641\u0644\u0648\u0641 (Pavlov) \u0635\u0627\u062d\u0628:",B.ahD,2,"\u0625\u064a\u0641\u0627\u0646 \u0628\u0627\u0641\u0644\u0648\u0641 \u0639\u0627\u0644\u0645 \u0631\u0648\u0633\u064a \u0635\u0627\u062d\u0628 \u0646\u0638\u0631\u064a\u0629 \u0627\u0644\u0625\u0634\u0631\u0627\u0637 \u0627\u0644\u0643\u0644\u0627\u0633\u064a\u0643\u064a\u060c \u0627\u0644\u062a\u064a \u062a\u0642\u0648\u0645 \u0639\u0644\u0649 \u0623\u0646 \u0627\u0644\u062a\u0639\u0644\u0645 \u0645\u0631\u062a\u0628\u0637 \u0628\u0645\u0628\u062f\u0623 \u0627\u0644\u0645\u062b\u064a\u0631/\u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629\u060c \u0648\u0643\u0627\u0646 \u064a\u0633\u062a\u0639\u0645\u0644 \u0627\u0644\u062d\u064a\u0648\u0627\u0646\u0627\u062a \u0641\u064a \u062a\u062c\u0627\u0631\u0628\u0647.",null)
B.anY=s(["\u064a\u0642\u0631\u0631\u0647\u0627 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0628\u0648\u0639\u064a","\u062a\u062d\u062f\u062b \u0628\u0633\u0631\u0639\u0629 \u062f\u0648\u0646 \u062a\u062f\u062e\u0644 \u0627\u0644\u0625\u0631\u0627\u062f\u0629 \u0648\u0623\u0647\u0645\u064a\u062a\u0647\u0627 \u0627\u0644\u0648\u0642\u0627\u064a\u0629 \u0645\u0646 \u0627\u0644\u0623\u062e\u0637\u0627\u0631","\u062a\u0633\u062a\u063a\u0631\u0642 \u0648\u0642\u062a\u0627\u064b \u0637\u0648\u064a\u0644\u0627\u064b \u0628\u0627\u0644\u062a\u0641\u0643\u064a\u0631","\u062a\u062e\u0635 \u0627\u0644\u0639\u0636\u0644\u0627\u062a \u0641\u0642\u0637 \u062f\u0648\u0646 \u0627\u0644\u062c\u0647\u0627\u0632 \u0627\u0644\u0639\u0635\u0628\u064a"],t.s)
